window.HB_TR["2-kings"]["ur"]=["1۔ پھر موآب نے اخاب کی موت کے بعد اسرائیل کے خلاف بغاوت کی۔\n2۔ اور اخزیاہ اپنے اوپری کمرے میں ایک جالی سے گر گیا جو سامریہ میں تھا، اور بیمار ہو گیا، اور اس نے قاصد بھیجے اور کہا، جاؤ، ایکرون کے خدا بعلزبوب سے پوچھو کہ کیا میں اس بیماری سے صحت یاب ہو جاؤں گا۔\n3۔ لیکن خداوند کے فرشتے نے ایلیاہ تشبیت سے کہا، اٹھو، سامریہ کے بادشاہ کے رسولوں سے ملنے جاؤ، اور ان سے کہو، {کیا} اس لیے نہیں کہ {اسرائیل} میں کوئی خدا نہیں، {کہ} تم بعلزبوب سے پوچھنے جا رہے ہو، جو عکرون کا خدا ہے؟\n4۔ اب خداوند یوں فرماتا ہے، تو اس بستر سے نیچے نہیں آؤ گے جس پر تم چڑھے ہو، بلکہ ضرور مر جاؤ گے۔ اور ایلیجہ چلا گیا۔ {تم چاہو گے...: عبرانی۔ جہاں تم اوپر گئے ہو، وہاں سے نیچے نہیں آؤ گے}\n5۔ اور جب قاصد اس کے پاس واپس آئے، اس نے ان سے کہا، اب تم کیوں پلٹ گئے ہو؟\n6۔ اور انہوں نے اس سے کہا، ایک آدمی ہم سے ملنے آیا، اور کہا، جاؤ، اس بادشاہ کی طرف رجوع کرو جس نے تمہیں بھیجا ہے، اور اس سے کہو، خداوند نے ایسا فرمایا، {کیا یہ اس لیے نہیں کہ {اسرائیل میں کوئی خدا نہیں} {جو} تو عکرون کے خدا بعلزبوب سے پوچھنے بھیجتا ہے؟ لہٰذا تم اس بستر سے نیچے نہیں آؤ گے جس پر تم چڑھے ہو، بلکہ ضرور مر جاؤ گے۔\n7۔ اور اس نے ان سے کہا، وہ کس قسم کا انسان تھا جو آپ سے ملنے آیا اور آپ کو یہ الفاظ کہے؟ {کیا...: عبرانی۔ اس آدمی کا انداز کیا تھا؟\n8۔ اور انہوں نے جواب دیا، {وہ} ایک بالوں والا آدمی تھا، اور اپنی کمر کے گرد چمڑے کی بیلٹ پہنے ہوئے تھا۔ اور اس نے کہا، یہ ایلیجہ دی تشبائٹ ہے۔\n9۔ پھر بادشاہ نے اس کے پاس پچاس کا کپتان بھیجا جس کے ساتھ وہ پچاس تھا۔ اور وہ اس کے پاس گیا: اور دیکھو، وہ ایک پہاڑی کی چوٹی پر بیٹھا تھا۔ اور اس نے اس سے کہا، اے خدا کے بندے، بادشاہ نے کہا، نیچے آؤ۔\n10۔ اور ایلیاہ نے جواب دیا اور پچاس کے سردار سے کہا، اگر میں خدا کا بندہ ہوں، تو آسمان سے آگ آ کر تمہیں اور تمہارے پچاس کو جلا دے۔ اور آسمان سے آگ اتری، اور اسے اور اس کے پچاس کو جلا دیا۔\n11۔ پھر اس نے پچاس کے ساتھ ایک اور کپتان بھیجا۔ اور اس نے جواب دیا اور کہا، اے خدا کے بندے، بادشاہ نے کہا، جلدی نیچے آؤ۔\n12۔ اور ایلیاہ نے جواب دیا اور ان سے کہا، اگر میں خدا کا بندہ ہوں، تو آسمان سے آگ نیچے آ کر تمہیں اور تمہارے پچاس کو جلا دے۔ اور خدا کی آگ آسمان سے نیچے آئی، اور اسے اور اس کے پچاس کو جلا دیا۔\n13۔ اور اس نے پھر تیسری نصف سنچریوں کا کپتان اپنی نصف سنچری کے ساتھ بھیجا۔ اور پچاس میں سے تیسرا کپتان اوپر آیا، ایلیاہ کے سامنے گھٹنے ٹیک کر اس سے التجا کی اور کہا، اے خدا کے بندے، میں دعا کرتا ہوں کہ میری زندگی اور ان پچاس بندوں کی جان تمہاری نظر میں قیمتی ہو۔ {گرنا: عبرانی۔ جھک گیا}\n14۔ دیکھو، آسمان سے آگ آئی، اور پچاس کی دہائی کے دو کپتانوں کو ان کی پچاس کی دہائی میں جلا دیا: اس لیے میری جان اب تمہاری نظر میں قیمتی ہو۔\n15۔ اور خداوند کے فرشتے نے ایلیاہ سے کہا، اس کے ساتھ نیچے آؤ، اس سے مت ڈرو۔ اور وہ اٹھا، اور اس کے ساتھ بادشاہ کے پاس گیا۔\n16۔ اور اس نے اس سے کہا، خداوند نے یہی فرمایا، کیونکہ تو نے عکرون کے خدا بعلزبوب سے پوچھنے کے لیے پیغامبر بھیجے ہیں، کیا یہ اس لیے نہیں کہ اسرائیل میں کوئی خدا نہیں جو اس کے کلام سے پوچھے؟ لہٰذا تم اس بستر سے نہیں اترو گے جس پر تم چڑھے ہو، بلکہ ضرور مر جاؤ گے۔\n17۔ تو وہ خداوند کے کلام کے مطابق مرا، جو ایلیاہ نے کہا تھا۔ اور یہورام نے اس کی جگہ یہورام کے دوسرے سال میں یہورام بادشاہ یہوشافاط کے بیٹے کی حکومت کی؛ کیونکہ اس کا کوئی بیٹا نہیں تھا۔\n18۔ اب اخزیا کے باقی اعمال جو اس نے کیے، کیا وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟","1۔ اور ایسا ہوا، جب خداوند نے ایلیاہ کو ایک طوفان کے ذریعے آسمان میں لے جانے کا ارادہ کیا، تو ایلیاہ الیشع کے ساتھ گلگل سے گیا۔\n2۔ اور ایلیاہ نے الیشع سے کہا، یہاں رہو، میں تم سے دعا کرتا ہوں؛ کیونکہ خداوند نے مجھے بیت ایل بھیجا ہے۔ اور الیشع نے اس سے کہا، جیسا کہ خداوند زندہ ہے، اور جیسا کہ تیری جان زندہ ہے، میں تمہیں نہیں چھوڑوں گا۔ تو وہ بیتھل چلے گئے۔\n3۔ اور بیت ایل میں موجود نبیوں کے بیٹے الیشع کے پاس آئے اور اس سے کہا، کیا تم جانتے ہو کہ خداوند آج تمہارے سر سے تمہارے مالک کو ہٹا دے گا؟ اور اس نے کہا، ہاں، میں جانتا ہوں؛ خاموش رہو۔\n4۔ اور ایلیاہ نے اس سے کہا، الیشع، یہاں رہو، میں تم سے دعا کرتا ہوں؛ کیونکہ خداوند نے مجھے یریحو بھیجا ہے۔ اور اس نے کہا، {جسے} خداوند زندہ ہے، اور {جیسا کہ} تیری جان زندہ ہے، میں تمہیں نہیں چھوڑوں گا۔ تو وہ یریحو آ گئے۔\n5۔ اور نبیوں کے بیٹے جو یریحو میں تھے، الیشع کے پاس آئے اور اس سے کہا، کیا تم جانتے ہو کہ خداوند آج تک تمہارے مالک کو تمہارے سر سے لے جائے گا؟ اور اس نے جواب دیا، ہاں، میں جانتا ہوں؛ خاموش رہو۔\n6۔ اور ایلیاہ نے اس سے کہا، تاری، میں تم سے دعا کرتا ہوں، یہاں؛ کیونکہ خداوند نے مجھے اردن بھیجا ہے۔ اور اس نے کہا، {جسے} خداوند زندہ ہے، اور {جیسا کہ} تیری جان زندہ ہے، میں تمہیں نہیں چھوڑوں گا۔ اور وہ دونوں آگے بڑھ گئے۔\n7۔ اور انبیاء کے بیٹوں کے پچاس آدمی گئے اور دور سے دیکھنے کے لیے کھڑے ہو گئے: اور وہ دونوں اردن کے پاس کھڑے تھے۔ {دیکھنے کے لیے: عبرانی۔ نظر میں، یا، اس کے خلاف}\n8۔ اور ایلیاہ نے اپنا چادر اٹھا لیا، اسے لپیٹ کر پانیوں کو مارا، اور وہ دونوں ادھر ادھر تقسیم ہو گئے، یہاں تک کہ وہ دونوں خشک زمین پر گر گئے۔\n9۔ اور جب وہ چلے گئے، تو ایلیاہ نے الیشع سے کہا، پوچھو کہ میں تمہارے لیے کیا کروں گا، اس سے پہلے کہ مجھے تم سے دور کر دیا جائے۔ اور الیشع نے کہا، میں تم سے دعا کرتا ہوں کہ اپنی روح کا دوہرا حصہ مجھ پر ہو۔\n10۔ اور اس نے کہا، تم نے ایک مشکل بات مانگی ہے: {بہرحال}، اگر تم مجھے دیکھو {جب میں} تم سے چھین لیا گیا ہوں، تو وہ تمہارے لیے بھی ایسا ہی ہوگا؛ لیکن اگر نہیں، تو یہ {so} نہیں ہوگا۔ {تم نے ہاسٹ...: عبرانی۔ تم نے پوچھنے میں بہت محنت کی ہے}\n11۔ اور جب وہ ابھی بھی باتیں کر رہے تھے، ایسا ہوا کہ {وہاں آگ کی ایک گاڑی اور آگ کے گھوڑے نمودار ہوئے، اور دونوں کو جدا کر دیا؛ اور ایلیاہ ایک طوفان کے ذریعے آسمان میں چلا گیا۔\n12۔ اور الیشع نے اسے دیکھا، اور پکارا، میرے باپ، میرے والد، اسرائیل کی رتھ اور اس کے سوار۔ اور اس نے اسے دوبارہ نہیں دیکھا: اور اس نے اپنے کپڑے اٹھا لیے، اور انہیں دو ٹکڑوں میں پھاڑ دیا۔\n13۔ اس نے ایلیاہ کا لباس بھی اٹھایا جو اس سے گرا تھا، اور واپس چلا گیا اور اردن کے کنارے کھڑا ہو گیا؛ {بینک: عبوری۔ لپ}\n14۔ اور اس نے ایلیاہ کی چادر جو اس کے اوپر سے گرا تھا، اٹھا کر پانی پر مارا اور کہا، \"ایلیاہ کا خداوند خدا کہاں ہے؟ اور جب اس نے بھی پانی کو چھوا تو وہ ادھر ادھر جدا ہو گئے: اور الیشع اس کے پاس چلا گیا۔\n15۔ اور جب نبیوں کے بیٹے جو {یریحو میں دیکھنے تھے} نے اسے دیکھا، تو انہوں نے کہا، ایلیاہ کی روح الیشع پر آرام کرتی ہے۔ اور وہ اس سے ملنے آئے، اور اس کے سامنے زمین پر جھک گئے۔\n16۔ اور انہوں نے اس سے کہا، دیکھو، اب تمہارے بندوں کے ساتھ پچاس طاقتور آدمی ہیں؛ ہم تم سے دعا کرتے ہیں کہ انہیں جانے دو اور اپنے مالک کی تلاش کرو: کہیں خداوند کی روح اسے اٹھا کر کسی پہاڑ یا وادی میں نہ پھینک دے۔ اور اس نے کہا، تم نہیں بھیجو گے۔ {مضبوط...: عبرانی۔ طاقت کے بیٹے} {کچھ پہاڑ: عبرانی۔ پہاڑوں میں سے ایک}\n17۔ اور جب انہوں نے اسے شرمندہ ہونے تک اصرار کیا، تو اس نے کہا، بھیجو۔ لہٰذا انہوں نے پچاس آدمی بھیجے؛ اور انہوں نے تین دن تلاش کیے، لیکن وہ نہیں ملا۔\n18۔ اور جب وہ دوبارہ اس کے پاس آئے، (کیونکہ وہ یریحو میں رکا رہا،) تو اس نے ان سے کہا، کیا میں نے تم سے نہیں کہا، مت جاؤ؟\n19۔ اور شہر کے لوگوں نے الیشع سے کہا، دیکھو، میں تم سے دعا کرتا ہوں، اس شہر کی حالت خوشگوار ہے، جیسا کہ میرا رب دیکھ رہا ہے: لیکن پانی کچھ نہیں ہے، اور زمین بنجر ہے۔ {بیرن: عبوری۔ اسقاط حمل کا باعث بنتا ہے}\n20۔ اور اس نے کہا، مجھے نیا کروز لاؤ، اور اس میں نمک ڈال دو۔ اور انہوں نے یہ سب اس کے پاس لے آئے۔\n21۔ اور وہ پانی کے چشمے کی طرف گیا، وہاں نمک ڈالا اور کہا، خداوند فرماتا ہے، میں نے ان پانیوں کو شفا دی ہے؛ وہاں سے مزید کوئی موت یا بنجر زمین نہیں ہوگی۔\n22۔ یوں پانی آج تک شفا پاتا ہے، جیسا کہ الیشع نے کہا تھا۔\n23۔ اور وہ وہاں سے بیٹھل چلا گیا، اور جب وہ راستے سے اوپر جا رہا تھا، تو شہر سے چھوٹے بچے نکلے، اس کا مذاق اڑایا اور کہا، اوپر چڑھو، اے گنجے سر؛ اوپر جاؤ، گنجے سر۔\n24۔ اور وہ پلٹا، ان پر نظر ڈالی، اور خداوند کے نام پر انہیں لعنت دی۔ اور وہاں اس نے جنگل سے دو پیدا کیے، چالیس اور ان میں سے دو بچے تھے۔\n25۔ اور وہ وہاں سے کوہ کرمل گیا، اور وہاں سے سامریہ واپس آیا۔","1۔ اب یہورام، اخاب کا بیٹا، یہوداہ کے بادشاہ یہوشافات کے اٹھارہویں سال میں سامریہ میں اسرائیل پر حکومت کرنے لگا اور بارہ سال حکومت کی۔\n2۔ اور اس نے خداوند کے سامنے برائی کی؛ لیکن اپنے والد کی طرح نہیں، اور اپنی ماں کی طرح: کیونکہ اس نے بعل کی وہ تصویر جو اس کے والد نے بنائی تھی، ایک طرف رکھ دی۔ {تصویر: عبرانی۔ مجسمہ}\n3۔ پھر بھی اس نے نیبت کے بیٹے یربعام کے گناہوں کو قبول کر لیا، جس کی وجہ سے اسرائیل نے گناہ کیا؛ وہ وہاں سے نہیں گیا۔\n4۔ اور موآب کا بادشاہ میشا بھیڑوں کا مالک تھا، اور اس نے اسرائیل کے بادشاہ کو اون کے ساتھ ایک لاکھ بکرے اور ایک لاکھ مینڈھے دیے۔\n5۔ لیکن جب اہاب مر گیا، تو موآب کے بادشاہ نے اسرائیل کے بادشاہ کے خلاف بغاوت کی۔\n6۔ اور بادشاہ یہورام اسی وقت سامریہ سے باہر نکلا اور پورے اسرائیل کو گننے لگا۔\n7۔ اور وہ یہوداہ کے بادشاہ یہوشافات کے پاس گیا، کہنے لگا: موآب کے بادشاہ نے میرے خلاف بغاوت کی ہے: کیا تم میرے ساتھ موآب کے خلاف جنگ میں جاؤ گے؟ اور اس نے کہا، میں اوپر جاؤں گا: میں تمہاری طرح ہوں، میرے لوگ تمہارے لوگوں کی طرح، اور میرے گھوڑے تمہارے گھوڑے کی طرح۔\n8۔ اور اس نے کہا، ہم کس طرف جائیں گے؟ اور اس نے جواب دیا، ایڈوم کے بیابان سے راستہ نکالو۔\n9۔ تو اسرائیل کا بادشاہ، یہوداہ کے بادشاہ اور ایڈوم کے بادشاہ گئے، اور انہوں نے سات دن کے سفر کا کمپاس لایا اور لشکر اور ان کے پیچھے آنے والے مویشیوں کے لیے پانی نہیں تھا۔ {وہ...: عببرانی۔ ان کے قدموں میں}\n10۔ اور اسرائیل کے بادشاہ نے کہا، افسوس! کہ خداوند نے ان تینوں بادشاہوں کو اکٹھا کیا ہے، تاکہ انہیں موآب کے ہاتھ میں دے دے!\n11۔ لیکن یہوشفات نے کہا، {کیا یہاں خداوند کا کوئی نبی نہیں ہے، تاکہ ہم اس کے ذریعے خداوند سے پوچھ گچھ کریں؟ اور اسرائیل کے بادشاہ کے ایک خادم نے جواب دیا اور کہا، یہ رہا الیشع شافات کا بیٹا، جس نے ایلیاہ کے ہاتھوں پر پانی ڈالا۔\n12۔ اور یہوشافاط نے کہا، خداوند کا کلام اس کے ساتھ ہے۔ تو اسرائیل کا بادشاہ، یہوشافاط، اور ایڈوم کا بادشاہ اس کے پاس نیچے آئے۔\n13۔ اور الیشع نے اسرائیل کے بادشاہ سے کہا، میرا تم سے کیا تعلق؟ اپنے باپ کے نبیوں اور اپنی ماں کے نبیوں کے پاس جاؤ۔ اور اسرائیل کے بادشاہ نے اس سے کہا، نہیں: کیونکہ خداوند نے ان تینوں بادشاہوں کو اکٹھا کیا ہے تاکہ انہیں موآب کے ہاتھ میں دے دے۔\n14۔ اور الیشع نے کہا، {جیسا کہ لشکروں کا رب زندہ ہے، جس کے سامنے میں کھڑا ہوں، یقینا، اگر میں یہوداہ کے بادشاہ یہوشافات کی موجودگی کو نہ دیکھتا، تو نہ میں تمہاری طرف دیکھتا اور نہ ہی تمہیں دیکھتا۔\n15۔ لیکن اب مجھے ایک منسٹرل لے آؤ۔ اور جب منسٹریل نے گانا بجایا، تو خداوند کا ہاتھ اس پر آ گیا۔\n16۔ اور اس نے کہا، خداوند فرماتا ہے، اس وادی کو کھائیوں سے بھر دے۔\n17۔ کیونکہ خداوند یہ فرماتا ہے، تم ہوا نہیں دیکھو گے، نہ بارش دیکھو گے؛ پھر بھی وہ وادی پانی سے بھر جائے گی، تاکہ تم پیو، تم، اپنے مویشی اور جانور۔\n18۔ اور یہ {لیکن} خداوند کی نظر میں ایک ہلکی چیز ہے: وہ موآبیوں کو بھی تمہارے ہاتھ میں دے گا۔\n19۔ اور تم ہر باڑ والے شہر کو، ہر منتخب شہر کو تباہ کرو گے، ہر اچھے درخت کو گرا دو گے، تمام پانی کے کنویں بند کرو گے، اور ہر اچھی زمین کو پتھروں سے خراب کرو گے۔ {مار: عبرانی۔ غمگین}\n20۔ اور صبح جب گوشت کی قربانی پیش کی گئی، تو دیکھا کہ ایڈوم کے راستے سے پانی آیا، اور ملک پانی سے بھر گیا۔\n21۔ اور جب تمام موآبیوں نے سنا کہ بادشاہ ان کے خلاف لڑنے آئے ہیں، تو انہوں نے جو کچھ بھی زرہ پہن سکتا تھا جمع کیا، اور سرحد پر کھڑے ہو گئے۔ {جمع شدہ: عبوری۔ ہم ایک ساتھ روتے تھے} {پہن لیں...: عبرانی۔ خود کو بیلٹ پہنا}\n22۔ اور وہ صبح سویرے اٹھے، اور سورج پانی پر چمک اٹھا، اور موآبیوں نے دوسری طرف پانی کو خون کی طرح سرخ دیکھا:\n23۔ اور انہوں نے کہا، یہ خون ہے: بادشاہ ضرور مارے گئے اور ایک دوسرے کو مارا۔ اب موآب، لوٹ مار کے لیے۔ {قتل شدہ: عبرانی۔ تباہ ہو گیا}\n24۔ اور جب وہ اسرائیل کے قید خانے پر پہنچے، تو بنی اسرائیل اٹھ کھڑے ہوئے اور موآبیوں کو مارا، اور وہ ان کے سامنے بھاگ گئے، لیکن وہ آگے بڑھ کر موآبیوں کو ان کے ملک میں بھی مار ڈالے۔ {انہوں نے کہا...: یا، انہوں نے اس میں مارا، حتیٰ کہ مارتے ہوئے}\n25۔ اور انہوں نے شہروں کو تباہ کیا، اور ہر اچھی زمین پر ہر آدمی کو اس کا پتھر پھینکا، اور اسے بھر دیا؛ اور انہوں نے تمام پانی کے کنویں بند کر دیے، اور تمام اچھے درخت کاٹ دیے: صرف کرہارسیتھ میں ان کے پتھر باقی رہے؛ بہرحال، سلنگرز نے اسے مارا، اور اسے مار دیا۔ {صرف میں...: عبرانی میں۔ یہاں تک کہ اس نے اس کے پتھر کرہاراسیتھ میں چھوڑ دیے}\n26۔ اور جب موآب کے بادشاہ نے دیکھا کہ جنگ اس کے لیے بہت دردناک ہے، تو اس نے سات سو آدمی تلواریں نکالنے والے اپنے ساتھ لے کر بادشاہ ایڈوم تک پہنچ گئے، لیکن وہ نہیں پہنچ سکے۔\n27۔ پھر اس نے اپنے سب سے بڑے بیٹے کو لیا جو اس کی جگہ حکومت کرنا چاہیے تھا، اور اسے دیوار پر جلانے کی قربانی پیش کی۔ اور اسرائیل کے خلاف شدید غصہ تھا: اور وہ اس سے دور ہو گئے، اور اپنی زمین پر واپس چلے گئے۔","1۔ وہاں نبیوں کے بیٹوں کی بیویوں کی ایک عورت نے الیشع کو پکارا، کہنے لگی، تیرے بندے میرا شوہر مر چکا ہے؛ اور تم جانتے ہو کہ تمہارا بندہ خدا سے ڈرتا تھا: اور قرض دہندہ آیا ہے تاکہ میرے دو بیٹوں کو غلام بنا سکے۔\n2۔ اور الیشع نے اس سے کہا، میں تمہارے لیے کیا کروں؟ بتاؤ، تمہارے گھر میں کیا ہے؟ اور اس نے کہا، تمہاری خادمہ کے پاس گھر میں کچھ نہیں، سوائے تیل کے ایک برتن کے۔\n3۔ پھر اس نے کہا، جاؤ، اپنے تمام پڑوسیوں کے برتن ادھار لو، {حتیٰ کہ} خالی برتن بھی؛ کم سے کم ادھار لے لو۔ {ادھار نہ لیں...: یا، کم ہی نہیں}\n4۔ اور جب تم اندر آؤ گے، تو دروازہ اپنے اور اپنے بیٹوں پر بند کرو گے، اور ان تمام برتنوں میں بہاؤ گے، اور جو بھرا ہوا ہے اسے ایک طرف رکھ دو۔\n5۔ تو وہ اس سے چلی گئی، اور دروازہ اس پر اور اس کے بیٹوں پر بند کر دیا، جو اس کے پاس برتن لے آئے؛ اور وہ بہنے لگی۔\n6۔ اور جب برتن بھر گئے تو اس نے اپنے بیٹے سے کہا، مجھے ابھی بھی ایک برتن لے آؤ۔ اور اس نے اس سے کہا، {اس سے زیادہ کوئی برتن نہیں ہے}۔ اور تیل وہیں رہا۔\n7۔ پھر وہ آئی اور خدا کے مرد کو بتایا۔ اور اس نے کہا، جاؤ، تیل بیچ دو، اپنا قرض ادا کرو، اور تم اور تمہارے بچے باقی سب سے زندہ رہو۔ {قرض: یا، قرض خواہ}\n8۔ اور ایک دن آیا، جب الیشع شونیم کے پاس چلا گیا، جہاں {تھا} ایک عظیم عورت تھی؛ اور اس نے اسے روٹی کھانے پر مجبور کیا۔ اور {تو} ایسا ہی تھا، {کہ} جب وہ گزرتا تھا، وہ وہاں جا کر روٹی کھاتا تھا۔ {یہ ایک دن گرتا ہے: عبرانی۔ ایک دن تھا} {اسے محدود کیا: عبرانی۔ اسے پکڑ لیا}\n9۔ اور اس نے اپنے شوہر سے کہا، دیکھو، اب میں سمجھتی ہوں کہ یہ خدا کا مقدس آدمی ہے، جو ہم سے مسلسل گزرتا رہتا ہے۔\n10۔ آئیے دیوار پر ایک چھوٹا سا کمرہ بناتے ہیں؛ اور ہم اس کے لیے وہاں ایک بستر، ایک میز، ایک اسٹول اور ایک شمعدان رکھیں: اور جب وہ ہمارے پاس آئے گا تو وہ وہاں جائے گا۔\n11۔ اور ایک دن آیا جب وہ وہاں آیا، وہ کمرے میں گیا اور وہاں لیٹ گیا۔\n12۔ اور اس نے اپنے خادم گہازی سے کہا، اسے شونامائٹے کہو۔ اور جب اس نے اسے بلایا، وہ اس کے سامنے کھڑی تھی۔\n13۔ اور اس نے اس سے کہا، اب اس سے کہو، دیکھو، تم نے ہماری بہت احتیاط سے کام لیا ہے؛ تمہارے لیے کیا کیا جائے؟ کیا تم بادشاہ سے بات کرو گے، یا فوج کے کپتان سے؟ اور اس نے جواب دیا، میں اپنے ہی لوگوں کے درمیان رہتا ہوں۔\n14۔ اور اس نے کہا، تو پھر اس کے لیے کیا کیا جائے؟ اور گہازی نے جواب دیا، بے شک اس کا کوئی بچہ نہیں ہے، اور اس کا شوہر بوڑھا ہے۔\n15۔ اور اس نے کہا، اسے کال کرو۔ اور جب اس نے اسے بلایا، وہ دروازے میں کھڑی تھی۔\n16۔ اور اس نے کہا، اس موسم کے بارے میں، زندگی کے وقت کے مطابق، تم بیٹے کو گلے لگاؤ گے۔ اور اس نے کہا، نہیں، میرے رب، خدا کے بندے، اپنی خادمہ سے جھوٹ مت بولو۔ {سیزن: عبدی۔ وقت مقرر کریں}\n17۔ اور عورت حاملہ ہوئی، اور اس وقت بیٹا پیدا ہوا جو الیشع نے اس سے کہا تھا، زندگی کے وقت کے مطابق۔\n18۔ اور جب بچہ بڑا ہوا، تو ایک دن آیا جب وہ اپنے والد کے پاس ریپرز کے پاس گیا۔\n19۔ اور اس نے اپنے والد سے کہا، میرا سر، میرا سر۔ اور اس نے ایک لڑکے سے کہا، اسے اس کی ماں کے پاس لے جاؤ۔\n20۔ اور جب اس نے اسے لے کر اپنی ماں کے پاس لے آیا، تو وہ دوپہر تک گھٹنوں کے بل بیٹھا رہا، اور {پھر} مر گیا۔\n21۔ اور وہ اوپر گئی، اسے خدا کے آدمی کے بستر پر لٹایا، دروازہ بند کیا اور باہر چلی گئی۔\n22۔ اور اس نے اپنے شوہر کو بلایا اور کہا، میں دعا کرتی ہوں کہ مجھے بھیج دو، نوجوانوں میں سے ایک اور گدھوں میں سے ایک، تاکہ میں خدا کے آدمی کے پاس بھاگ سکوں اور واپس آ سکوں۔\n23۔ اور اس نے کہا، آج تم اس کے پاس کیوں جاؤ گے؟ {یہ ہے} نہ نیا چاند ہے، نہ ہفتہ۔ اور اس نے کہا، {یہ ٹھیک رہے گا}۔ {اچھا: عبرانی۔ امن}\n24۔ پھر اس نے ایک گدھے پر زین لگایا اور اپنے خادم سے کہا، چلو، اور آگے بڑھو؛ میرے لیے اپنی سواری میں ڈھیلی نہ ہو، سوائے اس کے کہ میں تمہیں حکم دوں۔ {ڈھیلا...: عببرانی۔ میرے لیے خود کو قابو میں نہ رکھو}\n25۔ تو وہ گئی اور خدا کے آدمی کے پاس کرمل پر چڑھنے آئی۔ اور ایسا ہوا جب خدا کے آدمی نے اسے دور سے دیکھا، تو اس نے اپنے خادم گہازی سے کہا، دیکھو، {وہاں} وہ شونامائٹے:\n26. اب دوڑو، میں تم سے دعا کرتا ہوں، کہ اس سے ملو اور اسے کہو، {کیا تمہارے ساتھ ٹھیک ہے؟' کیا یہ تمہارے شوہر کے ساتھ ٹھیک ہے؟ کیا بچے کے ساتھ ٹھیک ہے؟ اور اس نے جواب دیا، {ہاں} ٹھیک ہے۔\n27۔ اور جب وہ خدا کے آدمی کے پاس پہاڑی پر پہنچی، تو اس نے اسے پاؤں سے پکڑ لیا، لیکن گہازی قریب آیا اور اسے دھکیل دیا۔ اور خدا کے آدمی نے کہا، اسے چھوڑ دو؛ کیونکہ اس کی روح اس کے اندر پریشان ہے: اور خداوند نے یہ مجھ سے چھپا رکھا ہے، اور مجھے نہیں بتایا۔ {وہ...: عبرانی۔ اس کے قدموں کے پاس} {ناراض: عبرانی۔ کڑوا}\n28۔ پھر اس نے کہا، کیا میں اپنے آقا کا بیٹا چاہتی تھی؟ کیا میں نے نہیں کہا، مجھے دھوکہ نہ دو؟\n29۔ پھر اس نے گہازی سے کہا، اپنی کمر باندھو، اور میری چھڑی اپنے ہاتھ میں لے لو، اور اپنی راہ پر چلو، اگر کسی سے ملے تو اسے سلام نہ کرنا؛ اور اگر کوئی تمہیں سلام کرے تو اسے دوبارہ جواب نہ دینا: اور میرا عصا بچے کے چہرے پر رکھ دو۔\n30۔ اور بچے کی ماں نے کہا، {جیسا کہ خداوند زندہ ہے، اور {جسے} تیری جان زندہ ہے، میں تمہیں نہیں چھوڑوں گی۔ اور وہ اٹھا، اور اس کے پیچھے گیا۔\n31۔ اور گہازی ان کے سامنے گزر گیا، اور چھڑی بچے کے چہرے پر رکھ دی؛ لیکن نہ آواز تھی، نہ سننا۔ چنانچہ وہ دوبارہ اس سے ملنے گیا اور کہا، بچہ جاگا نہیں ہے۔ {سن رہا ہے: عبوری۔ توجہ دیں}\n32۔ اور جب الیشع گھر میں آیا، دیکھو بچہ مردہ تھا، {اور} اپنے بستر پر لیٹا ہوا تھا۔\n33۔ اس لیے وہ اندر گیا، دونوں پر دروازہ بند کر دیا، اور خداوند سے دعا کی۔\n34۔ اور وہ اوپر گیا، بچے پر لیٹ گیا، اپنا منہ منہ پر رکھا، آنکھیں اس کی آنکھوں پر، اور ہاتھ ہاتھوں پر رکھے، اور اس نے بچے پر خود کو پھیلایا؛ اور بچے کا گوشت گرم ہو گیا۔\n35۔ پھر وہ واپس آیا، اور گھر میں آتا جاتا رہا؛ اور اوپر گیا، اور اس پر پھیل گیا: اور بچے نے سات بار چھینک ماری، اور بچے نے اپنی آنکھیں کھول دیں۔ {ادھر ادھر: عبرانی۔ ایک بار یہاں اور ایک بار وہاں}\n36۔ اور اس نے گہازی کو بلایا اور کہا، اس کو شونامائٹے کہو۔ تو اس نے اسے فون کیا۔ اور جب وہ اس کے پاس آئی تو اس نے کہا، اپنے بیٹے کو اٹھا لو۔\n37۔ پھر وہ اندر گئی، اس کے قدموں میں گر گئی، زمین پر جھک گئی، اپنے بیٹے کو اٹھایا اور باہر نکل گئی۔\n38۔ اور الیشع دوبارہ گلگل کے پاس آیا: اور زمین میں کمی تھی؛ اور انبیاء کے بیٹے اس کے سامنے بیٹھے تھے: اور اس نے اپنے خادم سے کہا، بڑے برتن پر رکھ دو، اور انبیاء کے بیٹوں کے لیے برتن کو اگل دو۔\n39۔ اور ایک کھیت میں جڑی بوٹیاں جمع کرنے گیا، وہاں ایک جنگلی بیل ملی، اس نے اپنی گود بھر کر جنگلی کدو جمع کیے، اور آ کر انہیں برتن میں کاٹ دیا، کیونکہ وہ نہیں جانتے تھے۔\n40۔ تو انہوں نے مردوں کے کھانے کے لیے پانی بہایا۔ اور جب وہ مٹی کا کھانا کھا رہے تھے، تو انہوں نے چیخ کر کہا، اے خدا کے بندے، برتن میں موت ہے۔ اور وہ ان میں سے کھا نہیں سکتے تھے۔\n41۔ لیکن اس نے کہا، تو کھانا لے آؤ۔ اور اس نے {یہ} برتن میں ڈال دیا؛ اور اس نے کہا، لوگوں کے لیے انڈیل دو، تاکہ وہ کھا سکیں۔ اور برتن میں کوئی نقصان نہیں تھا۔ {ہارم: ہیب۔ شیطانی چیز}\n42۔ اور بعلشلیشا سے ایک آدمی آیا، اور خدا کے آدمی کو پہلے پھلوں کی روٹی، بیس جو کی روٹیاں، اور اس کے چھلکے میں مکمل اناج کے کانوں لایا۔ اور اس نے کہا، لوگوں کو دے تاکہ وہ کھا سکیں۔ {چھلکا...: یا، اس کا نسخہ، یا، لباس}\n43۔ اور اس کے خادم نے کہا، کیا میں یہ سو آدمیوں کے سامنے رکھوں؟ اس نے دوبارہ کہا، لوگوں کو دے دو تاکہ وہ کھا سکیں: کیونکہ خداوند یہی فرماتا ہے، وہ کھائیں گے اور چلے جائیں گے۔\n44۔ تو اس نے ان کے سامنے رکھا، اور انہوں نے کھایا اور خدا کے کلام کے مطابق وہاں سے چلے گئے۔","1۔ اب نعمان، شام کے بادشاہ کے لشکر کا کپتان، اپنے آقا کے ساتھ ایک عظیم آدمی تھا، اور معزز تھا، کیونکہ اس کے ذریعے خداوند نے شام کو نجات دی تھی: وہ بہادری میں بھی ایک طاقتور آدمی تھا، {لیکن وہ کوڑھی تھا}۔ {ساتھ: عبرانی پہلے} {معزز: یا، مہربانی: عبرانی۔ اٹھایا گیا، یا، چہرے پر قبول کیا گیا} {نجات: یا، فتح}\n2۔ اور شامی گروہوں کے ذریعے باہر نکلے تھے، اور اسرائیل کی سرزمین سے ایک چھوٹی خادمہ کو قید کر کے لے آئے تھے؛ اور وہ نعمان کی بیوی کا انتظار کرتی رہی۔ {انتظار کیا...: عبرانی۔ پہلے تھا}\n3۔ اور اس نے اپنی مالکن سے کہا، کاش خدا میرے رب {ہو} اس نبی کے ساتھ جو {سامریہ} میں ہے! کیونکہ وہ اسے اس کی کوڑھ سے نکال دے گا۔ {ساتھ: عبرانی پہلے} {بازیابی: عبرانی۔ جمع ہو جاؤ}\n4۔ اور {ایک} اندر گیا اور اپنے آقا کو بتایا، کہا، یوں اور یوں وہ کنواری جو زمین اسرائیل کی ہے کہی۔\n5۔ اور شام کے بادشاہ نے کہا، جاؤ، جاؤ، اور میں اسرائیل کے بادشاہ کو خط بھیجوں گا۔ اور وہ روانہ ہوا، اور اپنے ساتھ دس چاندی کے ٹیلنٹ، چھ ہزار سونے کے سکے، اور دس لباس کے بدلے لے گیا۔ {ساتھ...: عبوری۔ اس کے ہاتھ میں}\n6۔ اور اس نے وہ خط اسرائیل کے بادشاہ کو دیا، جس میں کہا، جب یہ خط تمہارے پاس آئے گا، دیکھو، میں نے اپنے خادم نعمان کو تمہارے پاس بھیجا ہے تاکہ تم اسے اس کی جذام سے نجات دلا سکو۔\n7۔ اور جب اسرائیل کے بادشاہ نے خط پڑھا، تو اس نے اپنے کپڑے پھاڑ دیے اور کہا، {کیا میں خدا ہوں، قتل کرنے اور زندہ کرنے کے لیے، کہ یہ آدمی میرے پاس بھیجتا ہے تاکہ ایک کوڑھ والے آدمی کو واپس لاؤں؟ لہٰذا، میں تم سے درخواست کرتا ہوں، غور کرو اور دیکھو کہ وہ میرے خلاف کیسے جھگڑا کرتا ہے۔\n8۔ اور جب خدا کے آدمی الیشع نے سنا کہ اسرائیل کے بادشاہ نے اس کے کپڑے پھاڑ دیے ہیں، تو اس نے بادشاہ کو بھیجا اور کہا، تم نے اپنے کپڑے کیوں پھاڑے؟ اب وہ میرے پاس آئے، اور وہ جان لے گا کہ اسرائیل میں ایک نبی ہے۔\n9۔ تو نعمان اپنے گھوڑوں اور رتھ کے ساتھ آیا، اور الیشع کے گھر کے دروازے پر کھڑا ہو گیا۔\n10۔ اور الیشع نے اس کے پاس ایک پیغام بھیجا کہ سات بار اردن میں غسل کرو، اور تمہارا جسم تمہارے پاس واپس آئے گا، اور تم پاک ہو جاؤ گے۔\n11۔ لیکن نعمان غصے میں آ گیا، چلا گیا، اور کہا، دیکھو، میں نے سوچا، وہ ضرور میرے پاس آئے گا، کھڑا ہوگا، اور خداوند اپنے خدا کے نام پر پکارے گا، اور اس جگہ پر ہاتھ مارے گا، اور کوڑھی کو بحال کرے گا۔ {میں نے سوچا: عبرانی۔ میں نے کہا} {میں نے سوچا...: یا، میں نے اپنے آپ سے کہا، وہ یقینا باہر آئے گا، وغیرہ: عبرانی۔ میں نے کہا} {strike: Heb. اوپر نیچے حرکت کریں}\n12. کیا ابانا اور فارپار، دمشق کی ندیاں، اسرائیل کے تمام پانیوں سے بہتر نہیں ہیں؟ کیا میں ان میں نہا کر صاف نہیں ہو سکتا؟ تو وہ غصے میں مڑا اور چلا گیا۔ {ابانا: یا، امانا}\n13۔ اور اس کے خادم قریب آئے، اس سے بات کی، اور کہا، اے باپ، اگر نبی نے تمہیں کوئی عظیم کام کرنے کا حکم دیا ہوتا، تو کیا تم وہ نہ کرتے؟ تو پھر کتنا بہتر ہے، جب وہ تم سے کہے، دھو لو، اور پاک ہو جاؤ؟\n14۔ پھر وہ نیچے اترا اور خدا کے آدمی کے قول کے مطابق سات بار اردن میں ڈبویا: اور اس کا جسم ایسے واپس آیا جیسے ایک چھوٹے بچے کے گوشت پر ہو، اور وہ پاک ہو گیا۔\n15۔ اور وہ خدا کے آدمی کے پاس واپس آیا، وہ اور اس کی تمام رفاقتیں، اور آیا اور اس کے سامنے کھڑا ہو گیا، اور کہا، دیکھو، اب میں جانتا ہوں کہ زمین پر کوئی خدا نہیں، سوائے اسرائیل کے، لہٰذا، میں تم سے دعا کرتا ہوں، اپنے بندے کی برکت لو۔\n16۔ لیکن اس نے کہا، {جیسا کہ خداوند زندہ ہے، جس کے سامنے میں کھڑا ہوں، میں کوئی نہیں پکاروں گا۔ اور اس نے اسے لینے کی تلقین کی؛ لیکن اس نے انکار کر دیا۔\n17۔ اور نعمان نے کہا، تو کیا پھر، میں تم سے درخواست کرتا ہوں، اپنے خادم کو دو خچروں کی زمین کا بوجھ نہیں دیا جائے گا؟ کیونکہ تمہارا بندہ اب سے نہ تو سلائی کی قربانی دے گا اور نہ ہی کسی دوسرے دیوتاؤں کو قربانی دے گا، بلکہ خداوند کو دے گا۔\n18۔ اس معاملے میں خداوند اپنے بندے کو معاف کرے، {یہ} جب میرا آقا رمون کے گھر میں عبادت کے لیے جاتا ہے، اور وہ میرے ہاتھ پر جھکتا ہے، اور میں رمون کے گھر میں سجدہ کرتا ہوں: جب میں رمون کے گھر میں سجدہ کرتا ہوں، خداوند اس میں اپنے بندے کو معاف کرے۔\n19۔ اور اس نے اسے کہا، امن سے جاؤ۔ لہٰذا وہ اس سے تھوڑا دور ہو گیا۔ {تھوڑا سا...: عبرانی۔ ایک چھوٹا سا زمین کا ٹکڑا}\n20۔ لیکن گیحازی، الیشع خدا کے بندے نے کہا، دیکھو، میرے آقا نے نعمان کو اس شامی کو معاف کر دیا، کیونکہ اس نے جو کچھ لایا وہ اس کے ہاتھوں نہیں لیا: لیکن جیسا کہ خداوند زندہ ہے، میں اس کے پیچھے دوڑوں گا اور اس کا کچھ حصہ لے لوں گا۔\n21۔ تو گہازی نے نعمان کے پیچھے قدم رکھا۔ اور جب نعمان نے دیکھا کہ {اسے} اس کے پیچھے دوڑ رہا ہے، تو وہ رتھ سے اتر کر اس سے ملنے آیا، اور کہا، {کیا} سب خیریت ہے؟ {ہے...: عبرانی۔ کیا امن ہے؟}\n22۔ اور اس نے کہا، سب ٹھیک ہے۔ میرے آقا نے مجھے بھیجا ہے، کہہ رہا ہوں، دیکھو، ابھی تک افریم پہاڑ سے میرے پاس انبیاء کے بیٹوں کے دو نوجوان آئے ہیں: میں تم سے درخواست کرتا ہوں کہ انہیں چاندی کا تحفہ اور دو کپڑے دے دو۔\n23۔ اور نعمان نے کہا، مطمئن ہو جاؤ، دو ٹیلنٹس لو۔ اور اس نے اسے اکسایا، اور دو چاندی کے تحائف دو تھیلوں میں باندھے، دو کپڑوں کے ساتھ، اور انہیں اپنے دو نوکروں پر رکھ دیا؛ اور وہ اس کے سامنے خود کو ظاہر کرتے ہیں۔\n24۔ اور جب وہ مینار پہنچا، تو اس نے ان کے ہاتھ سے لے کر گھر میں دے دیے: اور اس نے مردوں کو جانے دیا، اور وہ روانہ ہو گئے۔ {ٹاور: یا، خفیہ جگہ}\n25۔ لیکن وہ اندر گیا، اور اپنے مالک کے سامنے کھڑا ہو گیا۔ اور الیشع نے اس سے کہا، کہاں سے آئے ہو، گہازی؟ اور اس نے کہا، تمہارا خادم کہیں نہیں گیا۔ {کہاں نہیں: عبوری۔ نہ ادھر نہ ادھر}\n26۔ اور اس نے اس سے کہا، میرا دل {تمہارے ساتھ} نہیں گیا، جب وہ آدمی اپنی رتھ سے مڑ کر تم سے ملنے آیا؟ {کیا یہ وقت ہے پیسے وصول کرنے، کپڑے، زیتون کے باغات، انگور کے باغات، بھیڑیں، بیل، نوکر، اور نوکرانی لینے کا؟\n27۔ لہٰذا نعمان کا جذام تم سے اور تمہاری نسل سے ہمیشہ کے لیے چمٹے گا۔ اور وہ اس کی موجودگی سے باہر نکلا، ایک کوڑھی کی طرح {برف کی طرح سفید}۔","1۔ اور نبیوں کے بیٹوں نے الیشع سے کہا، دیکھو، وہ جگہ جہاں ہم تیرے ساتھ رہتے ہیں ہمارے لیے بہت تنگ ہے۔\n2۔ ہم دعا کرتے ہیں کہ ہم اردن جائیں، اور وہاں سے ہر آدمی کو ایک بیم لے کر جائیں، اور وہاں ایک جگہ بنائیں جہاں ہم رہ سکیں۔ اور اس نے جواب دیا، گو یو۔\n3۔ اور ایک نے کہا، میں دعا کرتا ہوں کہ خوش ہو جاؤ، اور اپنے بندوں کے ساتھ چلو۔ اور اس نے جواب دیا، میں جاؤں گا۔\n4۔ تو وہ ان کے ساتھ چلا گیا۔ اور جب وہ اردن آئے تو انہوں نے لکڑیاں کاٹیں۔\n5۔ لیکن جب کوئی بیم کاٹ رہا تھا، کلہاڑی کا سر پانی میں گر گیا: اور وہ چیخ اٹھا اور کہا، افسوس، مالک! کیونکہ یہ ادھار لیا گیا تھا۔ {کلہاڑی کا سر: عبرانی۔ لوہا}\n6۔ اور خدا کے آدمی نے کہا، کہاں گیا؟ اور اس نے اسے جگہ دکھائی۔ اور اس نے ایک لکڑی کاٹ کر وہاں پھینک دی؛ اور لوہا واقعی تیر رہا تھا۔\n7۔ اس لیے اس نے کہا، اسے اپنے پاس لے جاؤ۔ اور اس نے اپنا ہاتھ بڑھایا، اور اسے پکڑ لیا۔\n8۔ پھر شام کے بادشاہ نے اسرائیل کے خلاف جنگ کی، اور اپنے خادموں سے مشورہ کیا، کہا، فلاں جگہ پر میرا کیمپ ہوگا۔ {کیمپ: یا، کیمپنگ}\n9۔ اور خدا کے آدمی نے اسرائیل کے بادشاہ کو بھیجا اور کہا، \"خبردار رہو کہ تم ایسی جگہ سے نہ گزرو؛ کیونکہ وہاں شامی نیچے آ رہے ہیں۔\n10۔ اور اسرائیل کے بادشاہ نے اس جگہ بھیجا جس کے بارے میں خدا کے آدمی نے اسے بتایا اور خبردار کیا، اور وہاں خود کو بچایا، نہ ایک بار نہ دو بار۔\n11۔ لہٰذا شام کے بادشاہ کا دل اس بات پر دکھ میں تھا؛ اور اس نے اپنے خادموں کو بلایا اور کہا، کیا تم مجھے نہیں دکھاؤ گے کہ ہم میں سے کون اسرائیل کے بادشاہ کے لیے ہے؟\n12۔ اور اس کے ایک خادم نے کہا، اے بادشاہ، میرے رب، کوئی نہیں، بلکہ الیشع، جو اسرائیل میں نبی ہے، اسرائیل کے بادشاہ کو وہ الفاظ سناتا ہے جو تم اپنے کمرے میں کہتے ہو۔ {کوئی نہیں: عبوری۔ نہیں}\n13۔ اور اس نے کہا، جاؤ اور دیکھو کہ وہ کہاں ہے، تاکہ میں اسے بھیج کر لے آؤں۔ اور اسے بتایا گیا، کہ دیکھو، {وہ} دوتھان میں ہے۔\n14۔ اس لیے اس نے وہاں گھوڑے، رتھ اور ایک بڑی فوج بھیجی، اور وہ رات کو آئے، اور شہر کو گھیر لیا۔ {زبردست: عبوری۔ ہیوی}\n15۔ اور جب خدا کے بندے کا خادم صبح سویرے اٹھا اور روانہ ہوا، تو دیکھتے ہی ایک فوج نے شہر کو گھوڑوں اور رتھ سے گھیر لیا۔ اور اس کے خادم نے اسے کہا، افسوس، میرے مالک! ہم کیسے کریں گے؟ {خادم: یا، وزیر}\n16۔ اور اس نے جواب دیا، خوف نہ کرو: کیونکہ جو لوگ ہمارے ساتھ ہیں وہ ان سے زیادہ ہیں جو ان کے ساتھ ہیں۔\n17۔ اور الیشع نے دعا کی اور کہا، اے خداوند، میں تجھ سے دعا کرتا ہوں کہ اس کی آنکھیں کھول دے تاکہ وہ دیکھ سکے۔ اور خداوند نے نوجوان کی آنکھیں کھولیں؛ اور اس نے دیکھا: اور دیکھو، پہاڑ الیشع کے گرد گھوڑوں اور آگ کے رتھوں سے بھرا ہوا تھا۔\n18۔ اور جب وہ اس کے پاس اترے، الیشع نے خداوند سے دعا کی اور کہا، میں دعا کرتا ہوں کہ اس قوم کو اندھے پن سے مارو۔ اور الیشع کے کلام کے مطابق اس نے انہیں اندھا کر دیا۔\n19۔ اور الیشع نے ان سے کہا، یہ راستہ نہیں ہے، اور نہ ہی یہ شہر ہے: میرے پیچھے آؤ، اور میں تمہیں اس آدمی کے پاس لے جاؤں گا جس کی تم تلاش کر رہے ہو۔ لیکن اس نے انہیں سامریا تک پہنچایا۔ {فالو...: عبوری۔ میرے پیچھے آؤ}\n20۔ اور جب وہ سامریہ میں آئے، تو الیشع نے کہا، اے خداوند، ان لوگوں کی آنکھیں کھولو، تاکہ وہ دیکھ سکیں۔ اور خداوند نے ان کی آنکھیں کھولیں، اور انہوں نے دیکھا؛ اور دیکھو، {وہ} سامریہ کے بیچ میں تھے۔\n21۔ اور اسرائیل کے بادشاہ نے الیشع سے کہا، جب اس نے انہیں دیکھا، میرے باپ، کیا میں انہیں ماروں؟ کیا میں انہیں مار دوں؟\n22۔ اور اس نے جواب دیا، تم ان لوگوں کو نہیں مارو گے جنہیں تم نے اپنی تلوار اور کمان سے قید کیا ہے؟ ان کے سامنے روٹی اور پانی رکھو، تاکہ وہ کھائیں، پی سکیں اور اپنے مالک کے پاس جا سکیں۔\n23۔ اور اس نے ان کے لیے بڑی خوراک تیار کی، اور جب وہ کھا کر پی گئے، تو اسے روانہ کر دیا، اور وہ اپنے مالک کے پاس چلے گئے۔ لہٰذا شام کے گروہ اب اسرائیل کی سرزمین میں نہیں آئے۔\n24۔ اور اس کے بعد ہوا کہ شام کے بادشاہ بن حداد نے اپنی پوری فوج جمع کی، اور اوپر جا کر سامریہ کا محاصرہ کر لیا۔\n25۔ اور سامریہ میں بہت بڑا قحط تھا: اور دیکھو، انہوں نے اسے گھیر لیا، یہاں تک کہ ایک گدھے کا سر چالیس چاندی کے سکے اور کبوتر کے گوبر کے چوتھے حصے پانچ چاندی کے سکے میں فروخت ہو گیا۔\n26۔ اور جب اسرائیل کا بادشاہ دیوار کے پاس سے گزر رہا تھا، ایک عورت نے اس سے پکارا، کہا، اے بادشاہ، مدد کرو۔\n27۔ اور اس نے کہا، اگر خداوند تمہاری مدد نہ کرے، تو میں کہاں سے تمہاری مدد کروں؟ بارن فلور سے باہر، یا وائن پریس سے؟ {اگر...: یا، خداوند تمہیں نہ بچائے}\n28۔ اور بادشاہ نے اس سے کہا، تمہیں کیا ہوا ہے؟ اور اس نے جواب دیا، اس عورت نے مجھ سے کہا، اپنے بیٹے کو دے دو، تاکہ ہم آج اسے کھا سکیں، اور کل میرا بیٹا کھائیں گے۔\n29۔ تو ہم نے میرے بیٹے کو ابالا، اور اسے کھا لیا: اور میں نے اگلے دن اس سے کہا، اپنے بیٹے کو دے دو، تاکہ ہم اسے کھا سکیں: اور اس نے اپنا بیٹا چھپا لیا ہے۔ {اگلا: عبرانی دیگر}\n30۔ اور جب بادشاہ نے عورت کے الفاظ سنے تو اس نے اپنے کپڑے پھاڑ دیے؛ اور وہ دیوار کے پاس سے گزرا، اور لوگوں نے دیکھا، اور دیکھو، اس کے جسم پر تھیلا کپڑا تھا۔\n31۔ پھر اس نے کہا، خدا ایسا کرے اور مجھ سے بھی زیادہ، اگر الیشع شافات کے بیٹے کا سر آج اس پر کھڑا ہو۔\n32۔ لیکن الیشع اپنے گھر میں بیٹھا تھا، اور بزرگ اس کے ساتھ بیٹھے تھے؛ اور {بادشاہ} نے اس کے سامنے سے ایک آدمی بھیجا، لیکن اس سے پہلے کہ پیغام رساں اس کے پاس پہنچے، اس نے بزرگوں سے کہا، دیکھو اس قاتل کے بیٹے نے میرا سر چھیننے کے لیے کیسے بھیجا ہے؟ دیکھو، جب پیغام رساں آئے، دروازہ بند کر دینا، اور اسے دروازے پر مضبوطی سے پکڑ لو: کیا یہ اس کے مالک کے قدموں کی آواز نہیں ہے؟\n33۔ اور جب وہ ان سے بات کر رہا تھا، تو رسول اس کے پاس آیا اور کہا، دیکھو، یہ خداوند کی برائی ہے؛ اب مجھے خداوند کے لیے اور کیا انتظار کرنا چاہیے؟","1۔ پھر الیشع نے کہا، خداوند کا کلام سنو؛ خداوند فرماتا ہے، کل اسی وقت {} ایک مقدار عمدہ آٹا {ایک شیکل کے بدلے} اور ایک شیکل کے بدلے دو پیمانہ جو بیچا جائے گا، سامریہ کے دروازے میں۔\n2۔ پھر ایک لارڈ جس کے ہاتھ پر بادشاہ جھکا ہوا تھا، خدا کے بندے کو جواب دیا اور کہا، دیکھو، {اگر} خداوند آسمان میں کھڑکیاں بنا دے، تو کیا یہ چیز ہو سکتی ہے؟ اور اس نے کہا، دیکھو، تم اسے اپنی آنکھوں سے دیکھو گے، لیکن اس میں سے نہ کھاؤ۔ {ایک لارڈ...: عبرانی۔ ایک لارڈ جو بادشاہ کا تھا اور اس کے ہاتھ پر جھکا ہوا تھا}\n3۔ اور دروازے میں داخل ہوتے ہوئے چار کوڑھ والے مرد تھے: اور انہوں نے ایک دوسرے سے کہا، ہم یہاں کیوں بیٹھے ہیں جب تک ہم مر نہ جائیں؟\n4۔ اگر ہم کہیں، ہم شہر میں داخل ہوں گے، تو قحط {ہے} شہر میں، اور ہم وہاں مر جائیں گے: اور اگر ہم یہاں بیٹھے رہیں تو ہم بھی مر جائیں گے۔ اب آؤ، اور شامیوں کے لشکر کے سامنے آؤ: اگر وہ ہمیں زندہ بچائیں گے تو ہم زندہ رہیں گے؛ اور اگر وہ ہمیں مار دیں تو ہم صرف مر جائیں گے۔\n5۔ اور وہ شام کے وقت اٹھ کھڑے ہوئے، شامیوں کے کیمپ کی طرف جانے کے لیے: اور جب وہ شام کے کیمپ کے سب سے کونے میں پہنچے، تو وہاں کوئی آدمی نہیں تھا۔\n6۔ کیونکہ خداوند نے شامیوں کے لشکر کو رتھوں کی آواز، گھوڑوں کی آواز، حتیٰ کہ ایک بڑی فوج کی آواز بھی سنائی دی: اور انہوں نے ایک دوسرے سے کہا، دیکھو، اسرائیل کے بادشاہ نے ہمارے خلاف حتیوں کے بادشاہوں اور مصریوں کے بادشاہوں کو ہمارے خلاف بلایا ہے۔\n7۔ چنانچہ وہ اٹھے اور شام کے وقت بھاگ گئے، اپنے خیمے، گھوڑے، گدے، حتیٰ کہ کیمپ کو بھی چھوڑ کر اپنی جان بچانے کے لیے بھاگ گئے۔\n8۔ اور جب یہ کوڑھی کیمپ کے سب سے کونے والے حصے تک پہنچے، تو وہ ایک خیمے میں گئے، کھایا اور پیا، وہاں سے چاندی، سونا اور کپڑے لے گئے، اور اسے چھپا لیا؛ اور دوبارہ آیا، اور دوسرے خیمے میں داخل ہوا، اور وہاں سے {بھی} لے گیا، اور چھپا گیا۔\n9۔ پھر انہوں نے ایک دوسرے سے کہا، ہم اچھا نہیں ہیں: آج خوشخبری کا دن ہے، اور ہم خاموش رہتے ہیں: اگر ہم صبح تک رکے رہیں تو کوئی مصیبت آ جائے گی، تو اب آؤ تاکہ ہم بادشاہ کے گھرانے کو بتا سکیں۔ {کچھ...: عبرانی۔ ہم سزا پائیں گے}\n10۔ تو وہ آئے اور شہر کے پورٹر کو بلایا، اور انہیں بتایا، کہا، ہم شامیوں کے کیمپ پر آئے، اور دیکھو، وہاں کوئی آدمی نہیں تھا، نہ انسان کی آواز، بلکہ گھوڑے بندھے ہوئے تھے، گدھے باندھے ہوئے تھے، اور خیمے جیسے تھے ویسے ہی تھے۔\n11۔ اور اس نے پورٹرز کو بلایا؛ اور انہوں نے اسے بادشاہ کے گھر کے اندر بتایا۔\n12۔ اور بادشاہ رات کو اٹھا اور اپنے خادموں سے کہا، اب میں تمہیں دکھاؤں گا کہ شامیوں نے ہمارے ساتھ کیا کیا ہے۔ وہ جانتے ہیں کہ ہم بھوکے ہیں؛ اسی لیے وہ کیمپ سے باہر نکل کر میدان میں چھپ جاتے ہیں، کہتے ہیں، جب وہ شہر سے نکلیں گے تو ہم انہیں زندہ پکڑیں گے اور شہر میں داخل ہوں گے۔\n13۔ اور اس کے ایک خادم نے جواب دیا اور کہا، \"کچھ لوگ لے آؤ، میں تم سے دعا کرتا ہوں، پانچ گھوڑے جو شہر میں باقی رہ گئے ہیں، (دیکھو، وہ [ہیں} جیسے اس میں باقی رہ جانے والے تمام اسرائیلی ہجوم: دیکھو، {میں کہتا ہوں}، وہ {ہیں} جیسے تمام بنی اسرائیل جو کھا گئے ہیں: ) اور آئیے بھیجیں اور دیکھیں۔ {شہر میں: عبرانی۔ اس میں}\n14۔ لہٰذا انہوں نے دو رتھ کے گھوڑے لیے؛ اور بادشاہ نے شامیوں کے لشکر کے پیچھے بھیجا اور کہا، جاؤ اور دیکھو۔\n15۔ اور وہ ان کے پیچھے اردن گئے، اور دیکھتے ہی پورا راستہ کپڑوں اور برتنوں سے بھرا ہوا تھا، جو شامیوں نے جلدی میں پھینک دیے تھے۔ اور قاصد واپس آئے، اور بادشاہ کو بتایا۔\n16۔ اور لوگ باہر نکلے اور شامیوں کے خیمے خراب کر دیے۔ لہٰذا خداوند کے کلام کے مطابق ایک شیکل کے بدلے ایک عمدہ آٹا {بیچا} گیا، اور ایک شیکل کے بدلے دو مقدار جو کے لیے۔\n17۔ اور بادشاہ نے اس سردار کو مقرر کیا جس کے ہاتھ پر وہ جھکا ہوا تھا، دروازے کی ذمہ داری سنبھالنے کے لیے: اور لوگ دروازے پر اس پر آ گئے، اور وہ مر گیا، جیسا کہ خدا کے آدمی نے کہا تھا، جو بادشاہ کے نیچے آنے پر بولا۔\n18۔ اور ایسا ہوا جب خدا کے آدمی نے بادشاہ سے کہا، کل اسی وقت سامریہ کے دروازے پر دو پیمائش جو اور ایک شیکل کے لیے عمدہ آٹا ہوگا۔\n19۔ اور اس خداوند نے خدا کے بندے کو جواب دیا اور کہا، اب دیکھو، {اگر} خداوند آسمان میں کھڑکیاں بنائے، تو کیا ایسا ہو سکتا ہے؟ اور اس نے کہا، دیکھو، تم اسے اپنی آنکھوں سے دیکھو گے، لیکن اسے نہ کھاؤ۔\n20۔ اور یوں اس کے ذہن میں آ گیا: کیونکہ لوگ دروازے پر اس پر آ گئے، اور وہ مر گیا۔","1۔ پھر الیشع نے اس عورت سے کہا، جس کے بیٹے کو اس نے زندہ کیا تھا، کہا، اٹھو، اور اپنے گھر والوں کے ساتھ جاؤ، اور جہاں بھی جا سکے قیام کرو، کیونکہ خداوند نے قحط کا اعلان کیا ہے؛ اور یہ سات سال تک زمین پر آئے گا۔\n2۔ اور عورت اٹھی، اور خدا کے مرد کے حکم کے مطابق اٹھی، اور اپنے گھرانے کے ساتھ گئی، اور فلسطینیوں کی سرزمین میں سات سال قیام کیا۔\n3۔ اور سات سال کے اختتام پر عورت فلسطینیوں کی سرزمین سے واپس آئی: اور وہ بادشاہ سے اپنے گھر اور زمین کے لیے پکارنے نکلی۔\n4۔ اور بادشاہ نے خدا کے بندے گیہازی سے بات کی، کہنے لگا، مجھے بتاؤ، میں تم سے دعا کرتا ہوں، کہ الیشع نے کتنے عظیم کام کیے ہیں۔\n5۔ اور جب وہ بادشاہ کو بتا رہا تھا کہ اس نے ایک مردہ جسم کو زندہ کیا، تو دیکھو، وہ عورت، جس کے بیٹے کو اس نے زندہ کیا تھا، بادشاہ سے اپنے گھر اور زمین کے لیے پکارنے لگی۔ اور گہازی نے کہا، میرے آقا، اے بادشاہ، یہ وہ عورت ہے، اور یہ اس کا بیٹا ہے، جسے الیشع نے زندہ کیا۔\n6۔ اور جب بادشاہ نے عورت سے پوچھا، تو اس نے اسے بتایا۔ لہٰذا بادشاہ نے اسے ایک خاص افسر مقرر کیا، کہا، جو کچھ بھی اس کا تھا، اور کھیت کے تمام پھل اس دن سے لے کر اب تک، واپس لو۔ {افسر: یا، خواجہ سرا}\n7۔ اور الیشع دمشق آیا؛ اور شام کا بادشاہ بن حداد بیمار تھا؛ اور اسے بتایا گیا، کہا گیا، خدا کا آدمی یہاں آ گیا ہے۔\n8۔ اور بادشاہ نے حزائیل سے کہا، اپنے ہاتھ میں ایک تحفہ لے لو، اور جاؤ، خدا کے بندے سے ملو، اور اس کے ذریعے خداوند سے پوچھو، کہو، کیا میں اس بیماری سے صحت یاب ہو جاؤں؟\n9۔ تو حزائیل اس سے ملنے گیا، اور اس کے ساتھ دمشق کی ہر اچھی چیز کا تحفہ لیا، چالیس اونٹوں کا بوجھ، اور اس کے سامنے آ کر کہا، تمہارا بیٹا بن ہاداد بادشاہ شام نے مجھے تمہارے پاس بھیجا ہے اور کہا، کیا میں اس بیماری سے صحت یاب ہو جاؤں؟ {ساتھ...: عبوری۔ اس کے ہاتھ میں}\n10۔ اور الیشع نے اس سے کہا، جاؤ، اسے کہو، تم یقینا صحت یاب ہو سکتے ہو، حالانکہ خداوند نے مجھے دکھایا ہے کہ وہ ضرور مر جائے گا۔\n11۔ اور اس نے اپنے چہرے کو مضبوطی سے سنبھالا، یہاں تک کہ شرمندہ ہو گیا: اور خدا کا بندہ رو پڑا۔ {تیز رفتاری سے: عبوری۔ اور سیٹ کرو}\n12۔ اور حزائیل نے کہا، میرے آقا کیوں روتا ہے؟ اور اس نے جواب دیا، کیونکہ میں جانتا ہوں کہ تم بنی اسرائیل کے ساتھ کیا ظلم کرو گے: ان کے قلعے جلا دو گے، اور ان کے نوجوان تلوار سے قتل کرو گے، ان کے بچوں کو تباہ کرو گے، اور ان کی عورتوں کو بچے کے ساتھ پھاڑ دو گے۔\n13۔ اور حزائیل نے کہا، لیکن کیا تمہارا خادم کتا ہے کہ وہ یہ عظیم کام کرے؟ اور الیشع نے جواب دیا، خداوند نے مجھے دکھایا ہے کہ تم شام کا بادشاہ بنو گے۔\n14۔ تو وہ الیشع سے روانہ ہوا اور اپنے مالک کے پاس آیا؛ جس نے اس سے کہا، الیشع نے تم سے کیا کہا؟ اور اس نے جواب دیا، اس نے مجھے کہا کہ تمہیں ضرور صحت یاب ہونا چاہیے۔\n15۔ اور کل ایسا ہوا کہ اس نے ایک موٹا کپڑا لیا، اسے پانی میں ڈبویا اور اپنے چہرے پر پھیلا دیا، یوں وہ مر گیا: اور حزائیل نے اس کی جگہ حکومت کی۔\n16۔ اور یورام کے پانچویں سال میں، جو اسرائیل کے بادشاہ اہاب کا بیٹا تھا، یہوشافات {جو اس وقت یہوداہ کا بادشاہ تھا}، یہورام یہوداہ کے بادشاہ یہوشافات کا بیٹا حکمرانی کرنے لگا۔ {شروع ہوا...: عبرانی۔ حکومت کی}\nسترہ۔ جب اس نے حکومت شروع کی تو اس کی عمر تیس سال تھی؛ اور انہوں نے یروشلم میں آٹھ سال حکومت کی۔\n18۔ اور وہ اسرائیل کے بادشاہوں کے راستے میں چلتا رہا، جیسا کہ اخاب خاندان نے کیا: کیونکہ اہاب کی بیٹی اس کی بیوی تھی، اور اس نے خداوند کے سامنے برا کیا۔\n19۔ پھر بھی خداوند یہوداہ کو داؤد کے خادم کے لیے تباہ نہیں کرے گا، جیسا کہ اس نے اسے وعدہ کیا تھا کہ وہ ہمیشہ اسے روشنی دے گا، {اور} اپنے بچوں کو۔ {روشنی: عبرانی۔ موم بتی، یا، چراغ}\n20۔ اپنے زمانے میں ایڈم نے یہوداہ کے ہاتھوں سے بغاوت کی اور اپنے اوپر بادشاہ بنا لیا۔\n21۔ تو یورام زائیر کے پاس گیا، اور اس کے ساتھ تمام رتھ بھی، اور رات کو اٹھا، اور اس کے گرد گھیرے ہوئے ایڈومیوں اور رتھوں کے کپتانوں کو مارا، اور لوگ اپنے خیموں میں بھاگ گئے۔\n22۔ پھر بھی ایڈم آج تک یہوداہ کے ہاتھوں سے بغاوت کرتا رہا۔ پھر لبنہ نے بھی اسی وقت بغاوت کی۔\n23۔ اور یورام کے باقی اعمال اور اس کے کیے گئے تمام اعمال {کیا یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟'\n24۔ اور یورام اپنے باپ دادا کے ساتھ سو گیا، اور اپنے باپ دادا کے ساتھ داؤد کے شہر میں دفن ہوا: اور اس کے بیٹے آحزیاہ نے اس کی جگہ حکومت کی۔ {آہزیہ: جسے عزریاہ اور یہوآہاز بھی کہا جاتا ہے}\n25۔ یورام کے بارہویں سال میں، اسرائیل کے بادشاہ اخاب کے بیٹے آہزیا نے حکومت شروع کی۔\n26۔ جب اس نے حکومت شروع کی تو وہ دو بیس سال کی عمر میں احزیاہ تھا؛ اور انہوں نے یروشلم میں ایک سال حکومت کی۔ اور اس کی والدہ کا نام {تھا} اتالیا، جو اسرائیل کے بادشاہ عمری کی بیٹی تھی۔ {بیٹی: یا، پوتی}\n27۔ اور وہ اخاب خاندان کے راستے میں چلتا رہا، اور خداوند کے سامنے برا کیا، جیسا کہ اخاب کے گھر نے کیا: کیونکہ وہ اہاب کے گھر کا داماد تھا۔\n28۔ اور وہ جورام، ابن اہاب کے ساتھ، راموتجلعاد میں شام کے بادشاہ حزائیل کے خلاف جنگ میں گیا؛ اور شامیوں نے جورام کو زخمی کیا۔\n29۔ اور بادشاہ جورام واپس گیا تاکہ یزرئیل میں ان زخموں سے شفا پائے، جو شامیوں نے اسے رامہ میں دیے تھے، جب اس نے شام کے بادشاہ حزائیل کے خلاف لڑائی کی تھی۔ اور یہوداہ کے بادشاہ یہورام کا بیٹا آہزیاہ یحریل میں یورام کے بیٹے سے ملنے نیچے گیا، کیونکہ وہ بیمار تھا۔ {جو کہ...: عبرانی جس سے شامیوں نے زخمی کیا تھا} {رامہ: جسے راموتھ کہا جاتا ہے} {بیمار: عبرانی۔ زخمی}","1۔ اور الیشع نبی نے نبیوں کے بچوں میں سے ایک کو بلایا اور اسے کہا، اپنی کمر باندھو، اور یہ تیل کا ڈبہ اپنے ہاتھ میں لے کر راموتجلعاد چلو:\n2۔ اور جب تم وہاں آؤ، وہاں یہوشافاط کے بیٹے یہو، نمشی کے بیٹے کو دیکھو، اور اندر جاؤ، اور اسے اس کے بھائیوں میں سے اٹھا کر اندرونی کمرے میں لے جاؤ؛ {اندرونی...: عبرانی۔ چیمبر ان اے چیمبر}\n3۔ پھر تیل کا ڈبہ لے کر اس کے سر پر ڈال دو، اور کہو، خداوند نے یوں فرمایا، میں نے تمہیں اسرائیل پر بادشاہ مقرر کیا ہے۔ پھر دروازہ کھولو، بھاگ جاؤ، اور دیر نہ کرو۔\n4۔ تو نوجوان، حتیٰ کہ وہ نوجوان نبی، راموتجلعاد گیا۔\n5۔ اور جب وہ آیا، دیکھو، لشکر کے کپتان بیٹھے تھے؛ اور اس نے کہا، اے کپتان، میرے پاس تمہارے لیے ایک کام ہے۔ اور یہو نے کہا، ہم سب میں سے کس کو؟ اور اس نے کہا، اے کپتان۔\n6۔ اور وہ اٹھا، اور گھر میں چلا گیا؛ اور اس نے تیل اس کے سر پر ڈالا اور کہا، یوں کہتا ہے کہ خداوند اسرائیل کا خدا، میں نے تمہیں خداوند کے لوگوں پر بادشاہ مقرر کیا ہے، {حتیٰ کہ} اسرائیل پر۔\n7۔ اور تم اپنے آقا آہاب کے گھر کو سزا دو، تاکہ میں اپنے بندوں، نبیوں کے خون اور خداوند کے تمام بندوں کے خون کا بدلہ لے سکوں، جو ایزابل کے ہاتھوں ہے۔\n8۔ کیونکہ اہاب کا پورا گھرانہ فنا ہو جائے گا: اور میں اس سے کاٹ دوں گا جو دیوار کے خلاف پیشاب کرتا ہے، اور جو اسرائیل میں بند اور چھوڑا گیا ہے:\n9۔ اور میں اخاب کے گھر کو یربعام کے بیٹے نبت کے گھر کی طرح اور احییاہ کے بیٹے بعشا کے گھر کی طرح بنا دوں گا:\n10۔ اور کتے یزبیل کو یزریئل کے حصے میں کھائیں گے، اور {وہاں کوئی نہیں ہوگا} جو {اسے} کو دفن کرے۔ اور اس نے دروازہ کھولا، اور بھاگ گیا۔\n11۔ پھر یہو اپنے رب کے خادموں کے پاس آیا: اور {ایک} نے اس سے کہا، {کیا سب خیر} ہے؟ یہ پاگل آدمی تمہارے پاس کیوں آیا؟ اور اس نے ان سے کہا، تم اس آدمی کو جانتے ہو، اور اس کی بات چیت کو۔\n12۔ اور انہوں نے کہا، {یہ} جھوٹ ہے؛ ابھی بتائیں۔ اور اس نے کہا، یوں اور اس نے مجھ سے کہا، خداوند فرماتا ہے، میں نے تمہیں اسرائیل کا بادشاہ مقرر کیا ہے۔\n13۔ پھر وہ جلدی سے دوڑے، ہر آدمی کا لباس لے کر سیڑھیوں کے اوپر اس کے نیچے رکھ دیا، اور بگل سے بج کر کہا، یہو بادشاہ ہے۔ {بادشاہ ہے: عبری۔ رینیتھ}\n14۔ تو یہو، یہوشافاط کا بیٹا، نمشی کا بیٹا، جورام کے خلاف سازش کرتا رہا۔ (اب جورام نے راموتجلعاد، وہ اور پورے اسرائیل، کو شام کے بادشاہ حزائیل کی وجہ سے اپنے پاس رکھا تھا۔\n15۔ لیکن بادشاہ جورام کو یزرعیل میں ان زخموں سے شفا دی گئی جو شامیوں نے اسے دیے تھے، جب وہ بادشاہ حزائیل سے لڑ رہا تھا۔) اور یہو نے کہا، اگر تمہارے ذہن ہیں، تو کوئی بھی باہر نہ نکل جائے اور نہ ہی شہر سے نکل کر یزرعیل میں اسے بتانے جائے۔ {جورام: عبرانی۔ یہورام لیکن سولہ آیت میں نہیں} {دیا تھا: عبرانی۔ smote} {نہ ہونے دے...: عبرانی۔ کوئی فرار نہ ہونے دیں، وغیرہ}\n16۔ یوں یہو ایک رتھ میں سوار ہوا اور یزریئل کی طرف گیا؛ کیونکہ جورام وہاں پڑا تھا۔ اور یہوداہ کا بادشاہ آہزیاہ یورام سے ملنے نیچے آیا۔\n17۔ اور یزرئیل کے مینار پر ایک چوکیدار کھڑا تھا، اس نے یہو کی جماعت کو دیکھا جب وہ آ رہا تھا، اور کہا، میں ایک گروہ دیکھ رہا ہوں۔ اور جورام نے کہا، ایک گھڑ سوار لے جاؤ، اور ان سے ملنے بھیجو، اور وہ کہے، کیا یہ امن ہے؟\n18۔ تو ایک گھوڑے پر سوار اس سے ملنے گیا، اور کہا، بادشاہ کہتا ہے، {کیا یہ} امن ہے؟ اور یہو نے کہا، تمہیں امن سے کیا لینا دینا ہے؟ میرے پیچھے مڑ جاؤ۔ اور چوکیدار نے کہا، پیغام رساں ان کے پاس آیا، لیکن وہ دوبارہ نہیں آیا۔\n19۔ پھر اس نے دوسرا گھوڑے پر بھیجا، جو ان کے پاس آیا اور کہا، بادشاہ نے یوں کہا، {کیا یہ} امن ہے؟ اور یہو نے جواب دیا، تمہیں امن سے کیا لینا دینا ہے؟ میرے پیچھے مڑ جاؤ۔\n20۔ اور چوکیدار نے کہا، \"وہ ان کے پاس آیا اور دوبارہ نہیں آیا: اور چلانا نمشے کے بیٹے یہو کی دھکیلنے کی طرح ہے؛ کیونکہ وہ غصے سے گاڑی چلاتا ہے۔ {ڈرائیونگ: یا، مارچنگ} {غصے میں: عبرانی۔ پاگل پن میں}\n21۔ اور جورام نے کہا، تیار ہو جاؤ۔ اور اس کی رتھ تیار ہو گئی۔ اور یورام اسرائیل کے بادشاہ اور یہوداہ کے بادشاہ اخزیا ہر ایک اپنی رتھ میں باہر نکلے، اور وہ یہو کے خلاف نکلے اور اس کا مقابلہ نابوث یزرلائٹ کے حصے میں کیا۔ {تیار ہو جاؤ: ہیب۔ bind} {met: Hebrew. مل گیا}\n22۔ اور جب جورام نے یہو کو دیکھا تو اس نے کہا، {کیا یہ} امن ہے، یہو؟ اور اس نے جواب دیا، کیا امن ہے، جب تک تمہاری ماں جیزبل کی بدکاری اور اس کی جادوگری اتنی زیادہ ہے؟\n23۔ اور یورام نے اپنے ہاتھ موڑ لیے، بھاگ گیا، اور اخزیاہ سے کہا، اے آہزیاہ، یہ دھوکہ ہے۔\n24۔ اور یہو نے اپنی پوری طاقت سے کمان نکالی، اور یہورام کو اس کے بازوؤں کے درمیان مارا، اور تیر اس کے دل کی طرف لگا اور وہ اپنی رتھ میں ڈوب گیا۔ {ڈرو...: عبرانی۔ اس نے اپنے ہاتھ میں کمان بھری} {غرق شدہ: عبرانی۔ جھک گیا}\n25۔ پھر {یہو} نے اپنے کپتان بدکار سے کہا، اٹھ کر اسے نابوت یزرلائٹ کے میدان کے حصے میں پھینک دو: کیونکہ یاد رکھو کہ جب میں اور تم اکٹھے آہاب اپنے والد کے پیچھے سوار ہوئے، خداوند نے یہ بوجھ اس پر ڈالا؛\n26. یقینا میں نے کل نابوت کا خون اور اس کے بیٹوں کا خون دیکھا، خداوند فرماتا ہے؛ اور میں اس پلاٹ میں تمہیں بدلہ دوں گا، خداوند فرماتا ہے۔ اب اسے {اور} خدا کے کلام کے مطابق {زمین کے تخت} میں پھینک دو۔ {خون: عبرانی۔ bloods} {پلاٹ: یا، حصہ}\n27۔ لیکن جب یہوداہ کے بادشاہ آحزیا نے یہ دیکھ لیا تو وہ باغ کے گھر کے راستے سے بھاگ گیا۔ اور یہو اس کے پیچھے آیا اور کہا، اسے بھی رتھ میں مارو۔ {اور انہوں نے ایسا کیا} جب وہ گر جا رہے تھے، جو {ہے} ایبلم کے پاس۔ اور وہ میگیدو بھاگ گیا، اور وہیں فوت ہو گیا۔\n28۔ اور اس کے خادموں نے اسے رتھ میں یروشلم لے جایا اور اپنے آباؤ اجداد کے ساتھ داؤد کے شہر میں اس کے مقبرے میں دفن کیا۔\n29۔ اور یورام کے گیارہویں سال میں اخحاب کے بیٹے نے اخزیا کو یہوداہ پر حکومت کرنے کا حکم دیا۔\n30۔ اور جب یہو یزرعیل آیا، یزابل نے اس کے بارے میں سنا؛ اور اس نے اپنا چہرہ رنگا، اپنا سر تھکا دیا، اور کھڑکی کی طرف دیکھا۔ {رنگا ہوا...: عبرانی۔ اپنی آنکھیں پینٹنگ میں ڈالیں}\n31۔ اور جب یہو دروازے پر داخل ہوا تو اس نے کہا، {ہاد} زمری امن ہے، جس نے اپنے مالک کو مارا؟\n32۔ اور اس نے اپنا چہرہ کھڑکی کی طرف اٹھایا اور کہا، میرے ساتھ کون ہے؟ کون؟ اور وہاں اس کی طرف دو یا تین خواجہ سرا نظر آتے تھے۔ {خواجہ سرا: یا، چیمبرلین}\n33۔ اور اس نے کہا، اسے نیچے پھینکو۔ تو انہوں نے اسے نیچے پھینک دیا: اور اس کا کچھ خون دیوار اور گھوڑوں پر چھڑک دیا گیا: اور اس نے اسے پاؤں تلے روندا۔\n34۔ اور جب وہ اندر آیا، تو اس نے کھایا اور پیا، اور کہا، جاؤ، اب اس منحوس عورت کو دیکھو، اور اسے دفن کر دو، کیونکہ وہ بادشاہ کی بیٹی ہے۔\n35۔ اور وہ اسے دفنانے گئے، لیکن انہیں اس کی کھوپڑی، پاؤں اور ہتھیلیوں سے زیادہ کچھ نہیں ملا۔\n36۔ اسی لیے وہ دوبارہ آئے اور اسے بتایا۔ اور اس نے کہا، یہ خداوند کا کلام ہے، جو اس نے اپنے بندے ایلیاہ تشبیت سے کہا، اور کہا، یزرییل کے حصے میں کتے ایزابل کا گوشت کھائیں گے: ہاتھوں سے}\n37۔ اور یزابل کی لاش یزریئل کے حصے میں کھیت کے چہرے پر گوبر کی طرح ہوگی؛ {تاکہ} وہ نہ کہیں، یہ {ہے} جیزبل۔","1۔ اور اخاب کے سامریہ میں ستر بیٹے تھے۔ اور یہو نے خطوط لکھے اور سامریہ، یزرعیل کے حکمرانوں، بزرگوں کو، اور ان لوگوں کو بھیجے جنہوں نے اہاب کے {بچوں} کو پالا، اور کہا، {وہ...: عبرانی۔ غذائیت دینے والے}\n2۔ اب جیسے ہی یہ خط آپ تک پہنچے، آپ کے آقا کے بیٹے آپ کے ساتھ ہیں، اور آپ کے ساتھ رتھ اور گھوڑے ہیں، ایک باڑ والا شہر اور زرہ بھی ہے؛\n3۔ اپنے آقا کے بہترین اور چھوٹے بیٹوں کو برابر کر دو، اور اسے اس کے والد کے تخت پر بٹھاؤ، اور اپنے آقا کے گھر کے لیے لڑو۔\n4۔ لیکن وہ بہت خوفزدہ ہوئے اور کہا، دیکھو، دو بادشاہ اس کے سامنے کھڑے نہیں تھے: تو ہم کیسے کھڑے ہوں گے؟\n5۔ اور جو گھر کے اوپر تھا، اور جو شہر پر تھا، بزرگ بھی، اور بچوں کے لانے والے بھی، یہو کے پاس بھیجے اور کہا، ہم تمہارے بندے ہیں، اور جو کچھ تم کہو گے وہ کریں گے؛ ہم کوئی بادشاہ نہیں بنائیں گے: جو تمہاری نظر میں اچھا ہے وہ کرو۔\n6۔ پھر اس نے دوسری بار انہیں خط لکھا، جس میں کہا، اگر تم میرے ہو، اور اگر میری آواز سنو گے، تو اپنے آقا کے بیٹوں کے سر لے جاؤ، اور کل میرے پاس یعزریل آؤ۔ اب بادشاہ کے بیٹے، جو ستر افراد تھے، شہر کے عظیم لوگوں کے ساتھ تھے، جنہوں نے انہیں پالا۔ {میرا: عبرانی۔ میرے لیے}\n7۔ اور جب خط ان کے پاس آیا تو انہوں نے بادشاہ کے بیٹوں کو لے کر ستر لوگوں کو قتل کر دیا، ان کے سر ٹوکریوں میں ڈال دیے اور اسے یزریل بھیج دیا۔\n8۔ اور ایک قاصد آیا اور اسے بتایا، کہا کہ وہ بادشاہ کے بیٹوں کے سر لے آئے ہیں۔ اور اس نے کہا، دروازے کے اندر داخل ہونے پر انہیں صبح تک دو ڈھیر میں رکھ دو۔\n9۔ اور صبح ہوا کہ وہ باہر گیا، کھڑا ہوا اور سب لوگوں سے کہا، اے نیک ہو: دیکھو، میں نے اپنے مالک کے خلاف سازش کی اور اسے مار ڈالا۔ لیکن یہ سب کس نے مارا؟\n10۔ اب جان لو کہ زمین پر خداوند کے اس کلام میں سے کچھ نہیں گرے گا، جو خداوند نے اہاب کے گھر کے بارے میں کہا تھا: کیونکہ خداوند نے وہ کیا ہے جو اس نے اپنے خادم ایلیاہ کے ذریعے کہا۔ {بذریعہ: عبرانی ہاتھوں سے}\n11۔ یوں یہو نے یزریل میں اخاب خاندان کے باقی ماندہ سب لوگوں کو، اپنے تمام عظیم آدمیوں، اپنے رشتہ داروں، اور اپنے کاہنوں کو قتل کر دیا، یہاں تک کہ اس کے پاس کوئی باقی نہ رہا۔ {رشتہ دار: یا، جان پہچان}\n12۔ اور وہ اٹھا اور روانہ ہوا، اور سامریہ آیا۔ {اور} جب وہ راستے میں شیئرنگ ہاؤس میں تھا، {شیئرنگ...: ہیب۔ چرواہوں کا گھرانہ بھیڑوں کو باندھتا ہے}\n13۔ یہو نے یہوداہ کے بادشاہ اخزیاہ کے بھائیوں سے ملاقات کی اور کہا، تم کون ہو؟ اور انہوں نے جواب دیا، ہم آحزیاہ کے بھائی ہیں؛ اور ہم بادشاہ کے بچوں اور ملکہ کے بچوں کو سلام کرنے کے لیے نیچے جاتے ہیں۔ {ملاقات کے ساتھ: عبرانی۔ مل گیا} {سلامی دینے کے لیے...: عبرانی۔ امن کے لیے، وغیرہ}\n14۔ اور اس نے کہا، انہیں زندہ پکڑو۔ اور انہوں نے انہیں زندہ پکڑ لیا، اور کاٹنے والے گھر کے گڑھے میں قتل کر دیا، {حتیٰ کہ} دو اور چالیس آدمی بھی؛ دونوں نے ان میں سے کوئی نہیں چھوڑا۔\n15۔ اور جب وہ وہاں سے روانہ ہوا، تو اس نے ریچاب کے بیٹے جہوناداب پر روشنی ڈالی جو اس سے ملنے آ رہا تھا، اور اس نے اسے سلام کیا اور کہا، کیا تمہارا دل ٹھیک ہے، جیسے میرا دل تمہارے دل کے ساتھ ہے؟ اور جہونداب نے جواب دیا، ہاں۔ اگر ایسا ہے تو {مجھے} اپنا ہاتھ دو۔ اور اس نے {اسے} اپنا ہاتھ دیا؛ اور وہ اسے رتھ میں اپنے پاس لے گیا۔ {روشن ہو کر: عبوری۔ مل گیا} {سلام: عبرانی۔ مبارک ہو}\n16۔ اور اس نے کہا، میرے ساتھ آؤ، اور خداوند کے لیے میری جوش دیکھو۔ لہٰذا انہوں نے اسے اپنی رتھ میں سوار کیا۔\n17۔ اور جب وہ سامریہ پہنچا، تو اس نے سامریہ میں اخاب کے باقی سب کو قتل کر دیا، یہاں تک کہ اس نے اسے تباہ کر دیا، جیسا کہ خداوند نے ایلیاہ سے کہا تھا۔\n18۔ اور یہو نے سب لوگوں کو اکٹھا کیا اور ان سے کہا، اہاب نے تھوڑا سا بعل کی خدمت کی؛ {لیکن} یہو اس کی بہت خدمت کرے گا۔\n19۔ اب مجھے بعل کے تمام نبیوں، اس کے تمام خادموں، اور اس کے تمام کاہنوں کو پکارو؛ کوئی کمی نہ کرے: کیونکہ میرے پاس بعل کے لیے ایک عظیم قربانی ہے؛ جو چاہے گا، وہ زندہ نہیں رہے گا۔ لیکن یہو نے یہ سب چالاکی سے کیا، اس نیت سے کہ وہ بعل کے پجاریوں کو تباہ کر سکے۔\n20۔ اور یہو نے کہا، بعل کے لیے ایک سنجیدہ اجتماع کا اعلان کرو۔ اور انہوں نے اعلان کیا۔ {اعلان: عبرانی۔ مقدس کرو}\n21۔ اور یہو نے پورے اسرائیل کے ذریعے بھیجا: اور بعل کے تمام عبادت گزار آئے، تاکہ کوئی بھی ایسا نہ بچا جو نہ آیا۔ اور وہ بعل کے گھر میں آئے؛ اور بعل کا گھر ایک سرے سے دوسرے سرے تک بھرا ہوا تھا۔ {بھرپور...: یا، اتنا بھرپور کہ وہ منہ سے منہ ملا کر کھڑے رہے}\n22۔ اور اس نے اسے کہا کہ {ہے} ویسٹری کے اوپر، بعل کے تمام عبادت گزاروں کے لیے لباس لے آؤ۔ اور اس نے ان کے لیے لباس نکالا۔\n23۔ اور یہو اور یہوناداب جو ریخاب کا بیٹا تھا، بعل کے گھر میں گئے اور بعل کے عبادت گزاروں سے کہا، تلاش کرو اور دیکھو کہ یہاں خداوند کے بندوں میں سے کوئی نہ ہو، صرف بعل کے عبادت گزار ہوں۔\n24۔ اور جب وہ قربانیاں اور جلانے کے لیے اندر گئے، یہو نے چالیس آدمیوں کو بغیر کسی کے مقرر کیا اور کہا، {اگر} وہ آدمی جو میں نے تمہارے ہاتھوں میں لایا ہے، فرار ہو جائے، {جو اسے جانے دے} تو اس کی جان {اس کی زندگی کے بدلے ہوگی۔'\n25۔ اور جیسے ہی اس نے سلائی کی قربانی ختم کی، یہو نے محافظوں اور کپتانوں سے کہا، اندر جاؤ، {اور} انہیں قتل کرو؛ کوئی باہر نہ آئے۔ اور انہوں نے تلوار کے دھار سے انہیں مارا؛ اور محافظوں اور کپتانوں نے انہیں نکال دیا، اور بعل خاندان کے شہر کی طرف روانہ ہو گئے۔ {دی ایج: ہیب۔ منہ}\n26۔ اور انہوں نے بعل کے گھر سے تصاویر نکالیں اور جلا دیں۔ {تصاویر: عبرانی۔ مجسمے}\n27۔ اور انہوں نے بعل کی تصویر کو توڑ دیا، بعل کے گھر کو توڑ دیا، اور اسے آج تک ایک خشک گھر بنا دیا۔\n28۔ یوں یہو نے بعل کو اسرائیل سے نکال دیا۔\n29۔ یربعام، نیبت کے بیٹے کے گناہوں کے باوجود، جس نے اسرائیل کو گناہ کیا، یہو ان کے بعد، یعنی وہ سنہری بچھڑے جو بیت ایل میں تھے، اور جو دان میں تھے، سے جدا نہیں ہوا۔\n30۔ اور خداوند نے یہو سے فرمایا، چونکہ تو نے میرے نزدیک جو کچھ درست ہے اسے اچھے طریقے سے انجام دیا، اور میرے دل میں جو کچھ تھا، آہاب خاندان کے ساتھ کیا ہے، اس لیے تمہارے چوتھی نسل کے بچے اسرائیل کے تخت پر بیٹھے ہوں گے۔\n31. لیکن یہو نے پورے دل سے اسرائیل کے خداوند خدا کے قانون میں چلنے کی پرواہ نہ کی، کیونکہ اس نے یربعام کے گناہوں سے دور نہیں ہوا، جنہوں نے اسرائیل کو گناہ میں مبتلا کیا۔ {لیا...: عبرانی۔ مشاہدہ نہیں کیا}\n32۔ ان دنوں خداوند نے اسرائیل کو مختصر کرنا شروع کیا: اور حزائیل نے انہیں اسرائیل کے تمام ساحلوں پر مارا؛ {کٹ کے لیے: عبوری۔ سروں کو کاٹنے کے لیے}\n33۔ اردن سے مشرق کی طرف، گلعاد کی تمام زمین، گادیت، روبینی، اور ماناسیت، آروئر سے، جو دریائے ارنون کے کنارے ہے، حتیٰ کہ گلعاد اور باشان بھی۔ {مشرق کی طرف: عبرانی۔ سورج کے طلوع کی طرف} {حتیٰ کہ...: یا حتیٰ کہ گلعاد اور باشان کی طرف}\n34۔ اب یہو کے باقی اعمال، اور اس نے جو کچھ کیا، اور اس کی تمام طاقت، کیا وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n35۔ اور یہو اپنے باپ و اجداد کے ساتھ سو گیا، اور انہوں نے اسے سامریہ میں دفن کیا۔ اور اس کے بیٹے یہواہاز نے اس کی جگہ حکومت کی۔\n36۔ اور یہو کا سامریہ میں اسرائیل پر حکومت کرنے کا وقت اٹھائیس سال تھا۔ {دی ٹائم: ہیب۔ وہ دن تھے}","1۔ اور جب اتھالیا، آہزیاہ کی ماں نے دیکھا کہ اس کا بیٹا مر چکا ہے، تو وہ اٹھی اور تمام شاہی نسل کو تباہ کر دیا۔ {seed...: عبرانی بادشاہی کا بیج}\n2۔ لیکن یہوشبع، بادشاہ یورام کی بیٹی، جو آحزیاہ کی بہن تھی، نے اخزیا کے بیٹے یوآش کو لے کر بادشاہ کے بیٹوں میں سے چوری کر لیا جو مارے گئے تھے؛ اور انہوں نے اسے، حتیٰ کہ اسے اور اس کی نرس کو بھی، اتھالیا سے بیڈروم میں چھپا دیا تاکہ وہ مارا نہ جائے۔ {یہوشبع: جسے یہوشبیت بھی کہا جاتا ہے} {یوآش: جسے یہواش بھی کہا جاتا ہے}\n3۔ اور وہ اس کے ساتھ چھ سال رب کے گھر میں چھپا رہا۔ اور اتالیاہ نے زمین پر حکومت کی۔\n4۔ اور ساتویں سال یہوعیادا نے سینکڑوں حکمرانوں کو بلایا، کپتانوں اور محافظوں کے ساتھ، اور انہیں خداوند کے گھر میں اپنے پاس لے آیا، ان سے عہد کیا، اور ان سے خدا کے گھر میں قسم کھائی، اور انہیں بادشاہ کا بیٹا دکھایا۔\n5۔ اور اس نے انہیں حکم دیا، کہا، یہ وہ کام ہے جو تم کرو گے؛ تم میں سے ایک تہائی حصہ جو سبت کے دن داخل ہوتا ہے، بادشاہ کے گھر کی پہرہ داری کے محافظ بھی ہوں گے؛\n6۔ اور تیسرا حصہ سور کے دروازے پر ہوگا؛ اور تیسرا حصہ دروازے کے پیچھے محافظ کے پیچھے ہے: اسی طرح تم گھر کی نگرانی کرو گے تاکہ وہ خراب نہ ہو۔ {وہ...: یا، بریک اپ سے}\n7۔ اور تم سب میں سے دو جو سبت کو باہر نکلتے ہیں، وہ بھی بادشاہ کے گرد خداوند کے گھر کی نگرانی کریں گے۔ {حصے: یا، کمپنیاں: عبرانی۔ ہاتھ}\n8۔ اور تم بادشاہ کے گرد گھومو، ہر آدمی اپنے ہتھیار ہاتھ میں لیے: اور جو بھی حد سے اندر آئے گا، اسے مار ڈالا جائے گا: اور بادشاہ کے ساتھ رہو جب وہ باہر جائے اور جب وہ اندر آئے۔\n9۔ اور سینکڑوں کے کپتروں نے وہ سب کچھ کیا جو یہویادعع کاهن نے حکم دیا: اور انہوں نے اپنے ہر آدمی کو جو سبت کے دن آنا تھا، ان کے ساتھ لے کر یہوعیادا کاہن کے پاس آ گئے۔\n10۔ اور سینکڑوں سے زائد کپتانوں کو پادری نے بادشاہ داؤد کے نیزے اور ڈھالیں دیں، جو خداوند کے مندر میں تھیں۔\n11۔ اور محافظ کھڑا تھا، ہر آدمی اپنے ہتھیار لیے، بادشاہ کے گرد گھوم رہا تھا، مندر کے دائیں کونے سے لے کر مندر کے بائیں کونے تک، {ساتھ} قربان گاہ اور مندر کے قریب۔ {کونا: عبوری۔ کندھا}\n12۔ اور اس نے بادشاہ کے بیٹے کو پیش کیا، اس پر تاج پہنایا، اور اسے گواہی دی؛ اور انہوں نے اسے بادشاہ بنایا اور مسح کیا؛ اور انہوں نے تالیاں بجائیں اور کہا، خدا بادشاہ کی حفاظت کرے۔ {خدا...: عبرانی۔ بادشاہ کو زندہ رہنے دو}\n13۔ اور جب اتالیاہ نے لوگوں کے محافظ اور لوگوں کی آواز سنی، تو وہ لوگوں کے پاس خداوند کے مندر میں آئی۔\n14۔ اور جب اس نے دیکھا، تو دیکھو، بادشاہ ایک ستون کے پاس کھڑا تھا، جیسا کہ طریقہ تھا، اور بادشاہ کے شہزادے اور بگل بجانے والے، اور ملک کے تمام لوگ خوشی سے منائے اور بگل بجانے لگے: اور اتالیاہ نے اپنے کپڑے پھاڑ دیے اور چیخی، غداری، غداری۔\n15۔ لیکن یہوعیدہ پادری نے سینکڑوں کے کپتانوں کو حکم دیا، جو لشکر کے افسران تھے، اور ان سے کہا، اسے بغیر حدوں کے باہر لے جاؤ، اور جو اس کے پیچھے آئے وہ تلوار سے قتل کرے۔ کیونکہ پادری نے کہا تھا، اسے خداوند کے گھر میں قتل نہ کیا جائے۔\n16۔ اور انہوں نے اس پر ہاتھ اٹھایا؛ اور وہ اس راستے سے گزری جس سے گھوڑے بادشاہ کے گھر میں داخل ہوئے: اور وہیں وہ قتل ہو گئی۔\n17۔ اور یہوعیادا نے خداوند، بادشاہ اور عوام کے درمیان عہد کیا کہ وہ خداوند کے لوگ ہوں گے؛ بادشاہ اور عوام کے درمیان بھی۔\n18۔ اور زمین کے تمام لوگ بعل کے گھر میں گئے اور اسے توڑ دیا؛ اس کے قربان گاہیں اور اس کی تصویریں انہیں مکمل طور پر توڑ دیتی ہیں، اور قربان گاہوں کے سامنے بعل کے پادری متان کو قتل کر دیتے ہیں۔ اور پادری نے خداوند کے گھر پر افسران مقرر کیے۔ {افسران: عبرانی۔ دفاتر}\n19۔ اور اس نے سینکڑوں حکمرانوں، کپتانوں، محافظوں اور تمام لوگوں کو اپنے قبضے میں لے لیا؛ اور انہوں نے بادشاہ کو خداوند کے گھر سے نیچے اتارا، اور محافظوں کے دروازے سے بادشاہ کے گھر تک پہنچے۔ اور وہ بادشاہوں کے تخت پر بیٹھا۔\n20۔ اور زمین کے تمام لوگ خوش ہوئے، اور شہر خاموش ہو گیا: اور انہوں نے بادشاہ کے گھر کے پاس تلوار سے اتالیاہ کو قتل کر دیا۔\n21۔ سات سال کا یہواش تھا جب اس نے حکومت شروع کی۔","1۔ یہو کے ساتویں سال میں یہواش نے حکومت شروع کی؛ اور انہوں نے یروشلم میں چالیس سال حکومت کی۔ اور ان کی والدہ کا نام زیبیہ آف بیرسبع تھا۔\n2۔ اور یہواش نے خداوند کی نظر میں وہ سب کیا جو اس کے تمام دنوں میں یہویادا کاهن نے اسے ہدایت دی۔\n3۔ لیکن اونچی جگہیں نہیں چھین لی گئیں: لوگ اب بھی اونچی جگہوں پر قربانی دیتے اور لوبان جلاتے رہے۔\n4۔ اور یہواش نے کاہنوں سے کہا، خداوند کے گھر میں لائے گئے وقف شدہ چیزوں کی ساری رقم {حتی} ہر اس شخص کی رقم جو {حساب سے} گزرتا ہے، وہ پیسہ جو ہر انسان کے لیے مقرر ہے، {اور} وہ تمام پیسہ جو کسی کے دل میں آتا ہے تاکہ اسے خداوند کے گھر میں لایا جائے،  {وقف شدہ چیزیں: یا، مقدس باتیں: عبرانی۔ مقدسات} {کہ ہر...: عبرانی۔ اس کی رائے کی روحوں کی} {آتا ہے...: عبرانی۔ ایک انسان کے دل پر چڑھتا ہے}\n5۔ پادری اسے اپنے پاس لے جائیں، ہر اس کے جاننے والے آدمی: اور جہاں بھی کوئی دراڑ ملے گھر کی دراڑیں ٹھیک کریں۔\n6۔ لیکن یہ {ایسا ہی تھا} کہ بادشاہ یہوش کے تیسرے اور بیسویں سال میں کاہنوں نے گھر کی دراڑیں درست نہیں کی تھیں۔ {تین...: عبرانی۔ بیسویں سال اور تیسرا سال}\n7۔ پھر بادشاہ یہوآش نے یہوعیعہ کاہن اور {دیگر} کاہنوں کو بلایا اور کہا، تم گھر کی دراڑوں کی مرمت کیوں نہیں کرتے؟ اب اپنے جاننے والوں سے مزید رقم نہ لو، بلکہ اسے گھر کی خلاف ورزیوں کے لیے دے دو۔\n8۔ اور پادریوں نے عوام سے مزید پیسے نہ لینے اور گھر کی دراڑوں کی مرمت کے لیے رضامندی ظاہر کی۔\n9۔ لیکن یہوعیدہ پادری نے ایک صندوق لیا، اس کے ڈھکن میں سوراخ کیا، اور اسے قربان گاہ کے پاس دائیں طرف رکھ دیا جب کوئی خداوند کے گھر میں داخل ہوتا ہے: اور دروازہ رکھنے والے پادریوں نے اس میں سارا پیسہ رکھ دیا جو خداوند کے گھر میں لایا گیا۔ {دروازہ: عبوری۔ تھریش ہولڈ}\n10۔ اور جب انہوں نے دیکھا کہ صندوق میں بہت سا پیسہ ہے، تو بادشاہ کا کاتب اور اعلیٰ پادری آئے، انہوں نے تھیلوں میں رکھ دیے اور خداوند کے گھر میں ملنے والے پیسے کو بتایا۔ {کاتب: یا، سیکرٹری} {put...: عبدی۔ بندھا ہوا}\n11۔ اور انہوں نے یہ پیسہ ان لوگوں کے حوالے کر دیا جو کام کرتے تھے اور جو خداوند کے گھر کی نگرانی کر رہے تھے: اور انہوں نے اسے بڑھئیوں اور معماروں کے سپرد کر دیا، جو خداوند کے گھر پر کام کرتے تھے، {رکھا...: عبرانی۔ اسے سامنے لایا تھا}\n12۔ اور معماروں، پتھر کاٹنے والوں، اور لکڑی اور پتھر خریدنے کے لیے تاکہ خداوند کے گھر کی دراڑیں ٹھیک کی جا سکیں، اور جو کچھ بھی گھر کی مرمت کے لیے رکھا گیا تھا۔ {تھا...: عبرانی۔ آگے بڑھا}\n13۔ تاہم خداوند کے گھر کے لیے چاندی کے پیالے، سنفرز، بیسن، ٹرمپٹس، سونے کے برتن یا چاندی کے برتن نہیں بنائے گئے، جو خداوند کے گھر میں لائے گئے پیسے سے تھے:\n14۔ لیکن انہوں نے وہ کام کرنے والوں کو دے دیا، اور اس سے خداوند کے گھر کی مرمت کی۔\n15۔ مزید برآں، انہوں نے ان لوگوں کا حساب نہیں لگایا جن کے ہاتھ میں مزدوروں کو دینے کے لیے پیسے دیے جاتے تھے: کیونکہ وہ وفاداری سے سودا کرتے تھے۔\n16۔ گناہ اور خلاف ورزی کا پیسہ خداوند کے گھر میں نہیں لایا گیا: بلکہ یہ پادریوں کا تھا۔\n17۔ پھر شام کا بادشاہ حزائیل اوپر گیا، اور گات کے خلاف لڑا اور اسے فتح کر لیا: اور حزائیل نے یروشلم جانے کے لیے اپنا چہرہ بنایا۔\n18۔ اور یہودا کے بادشاہ یہوآش نے وہ تمام مقدس چیزیں لے لیں جو یہوشافاط، یہورام، اور آہزیہ، اس کے آباؤ اجداد، یہوداہ کے بادشاہوں نے وقف کی تھیں، اور اپنی مقدس چیزیں، اور وہ تمام سونا جو خداوند کے گھرانے اور بادشاہ کے گھر کے خزانے میں پایا تھا، اور شام کے بادشاہ حزائیل کو بھیجا:  اور وہ یروشلم سے چلا گیا۔ {گیا...: عببرانی۔ اوپر چلا گیا}\n19۔ اور یوآش کے باقی اعمال اور جو کچھ اس نے کیا، کیا وہ یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n20۔ اور اس کے خادم اٹھے، سازش کی، اور میلو کے گھر میں یوآش کو قتل کر دیا، جو سیلا تک جاتا ہے۔ {گھر...: یا، بیت میلو}\n21۔ کیونکہ یوزخار شمث کا بیٹا اور شومر کے بیٹے یہوزاباد (اس کے خادموں) نے اسے مارا اور وہ مر گیا؛ اور انہوں نے اسے اس کے باپ دادا کے ساتھ داؤد شہر میں دفن کیا: اور اس کے بیٹے امازیہ نے اس کی جگہ حکومت کی۔","1۔ یوآش کے تیسرے اور بیسویں سال میں، یہوداہ کے بادشاہ آحزیا کے بیٹے یہوآہاز نے سامریہ میں اسرائیل پر حکومت شروع کی، {اور سترہ سال حکومت کی}۔ {تین...: عبرانی۔ بیسویں سال اور تیسرا سال}\n2۔ اور اس نے وہ کیا جو خداوند کی نظر میں برا تھا، اور نیبت کے بیٹے یربعام کے گناہوں کی پیروی کی، جس سے اسرائیل گناہ میں آ گیا؛ وہ وہاں سے نہیں گیا۔ {فالو کیا: عبرانی۔ چلنے کے بعد}\n3۔ اور خداوند کا غصہ اسرائیل کے خلاف بھڑک اٹھا، اور اس نے انہیں شام کے بادشاہ حزائیل کے ہاتھ میں دے دیا، اور ہازائل کے بیٹے بن حداد کے ہاتھ میں، تمام {ان} عمر۔\n4۔ اور یہوآہاز نے خداوند سے دعا کی، اور خداوند نے اس کی بات مانی، کیونکہ اس نے اسرائیل پر ظلم دیکھا، کیونکہ شام کے بادشاہ نے ان پر ظلم کیا۔\n5۔ (اور خداوند نے اسرائیل کو نجات دہندہ دیا، تاکہ وہ شامیوں کے ہاتھوں سے نکل آئیں: اور بنی اسرائیل اپنے خیموں میں رہے، جیسے پہلے تھے۔ {پہلے کی طرح: عبرانی۔ کل کی طرح، اور تیسرے دن}\n6۔ پھر بھی وہ یربعام خاندان کے گناہوں سے نہیں نکلے، جس نے اسرائیل کو گناہ کیا، {بلکہ} وہاں چلے گئے: اور سامریہ میں بھی باغ باقی رہا۔) {چلا: عبرانی۔ وہ چلتا رہا} {باقی رہا: عبرانی۔ کھڑا ہوا}\n7۔ اس نے قوم میں سے صرف یہوآہاز کے لیے صرف پچاس گھڑ سوار، دس رتھ اور دس ہزار پیادہ چھوڑے؛ کیونکہ شام کے بادشاہ نے انہیں تباہ کر دیا تھا، اور انہیں تھریش کر مٹی کی طرح بنا دیا تھا۔\n8۔ اب یہوآحاز کے باقی اعمال، اور اس کے کیے اور اس کی طاقت، کیا وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n9۔ اور یہوآہاز اپنے باپ دادا کے ساتھ سوتا تھا؛ اور انہیں سامریہ میں دفن کیا گیا: اور اس کے بیٹے یوآش نے اس کی جگہ حکومت کی۔ {یوآش: جسے یہواش بھی کہا جاتا ہے}\n10۔ یہوداہ کے بادشاہ یوآش کے ستتیس سال میں یہوآہاز کے بیٹے یہواش نے سامریہ میں اسرائیل پر حکومت شروع کی، {اور سولہ سال حکومت کی}۔\n11۔ اور اس نے وہ کیا جو خداوند کی نظر میں برا تھا؛ اس نے نیبت کے بیٹے یربعام کے تمام گناہوں سے نہیں نکالا، جس نے اسرائیل کو گناہ کیا: {بلکہ} وہ وہاں چلتا رہا۔\n12۔ اور یوآش کے باقی اعمال، اور اس نے جو کچھ کیا، اور اس کی طاقت جس سے اس نے یہوداہ کے بادشاہ امازیا کے خلاف لڑائی کی، کیا وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n13۔ اور یوآش اپنے باپ کے ساتھ سو گیا؛ اور یربعام اپنے تخت پر بیٹھا: اور یوآش کو سامریہ میں اسرائیل کے بادشاہوں کے ساتھ دفن کیا گیا۔\n14۔ اب الیشع اپنی بیماری سے بیمار ہو گیا تھا جس سے وہ فوت ہو گیا۔ اور یوآش بادشاہ اسرائیل اس کے پاس اترا، اس کے چہرے پر رو پڑا اور کہا، اے میرے باپ، میرے باپ، اسرائیل کی رتھ اور اس کے سوار۔\n15۔ اور الیشع نے اس سے کہا، تیر اور کمان لے لو۔ اور اس نے اپنے پاس تیر کمان لے لیے۔\n16۔ اور اس نے اسرائیل کے بادشاہ سے کہا، اپنا ہاتھ کمان پر رکھو۔ اور اس نے اپنا ہاتھ اس پر رکھا: اور الیشع نے اپنے ہاتھ بادشاہ کے ہاتھوں پر رکھ دیے۔ {اپنا لکھو...: عبرانی۔ اپنا ہاتھ سواری کے لیے تیار کرو}\n17۔ اور اس نے کہا، کھڑکی مشرق کی طرف کھولو۔ اور اس نے کھولا۔ پھر الیشع نے کہا، ارے۔ اور اس نے گولی چلائی۔ اور اس نے کہا، خداوند کی نجات کا تیر، اور شام سے نجات کا تیر: کیونکہ تم افیق میں شامیوں کو مارو گے، جب تک کہ تم انہیں نگل نہ جاؤ۔\n18۔ اور اس نے کہا، تیر لے لو۔ اور اس نے {انہیں} لے لیے۔ اور اس نے اسرائیل کے بادشاہ سے کہا، زمین پر مارو۔ اور اس نے تین بار مارا، اور وہیں رکا۔\n19۔ اور خدا کا آدمی اس پر غصہ ہوا اور کہا، تمہیں پانچ یا چھ بار مارنا چاہیے تھا؛ تو اگر تم نے شام کو اس وقت تک مارا ہوتا جب تک کہ تم نے اسے نگل نہ لیا ہوتا، اب تم شام کو تین بار مارو گے۔\n20۔ اور الیشع مر گیا، اور اسے دفن کر دیا۔ اور موآبیوں کے گروہ سال کے آنے پر زمین پر حملہ آور ہوئے۔\n21۔ اور ایسا ہوا، جب وہ ایک آدمی کو دفن کر رہے تھے، تو انہوں نے ایک گروہ دیکھا؛ اور انہوں نے اس آدمی کو الیشع کی قبر میں پھینک دیا: اور جب وہ آدمی اتارا گیا اور الیشع کی ہڈیوں کو چھوا، تو وہ ہوش میں آیا اور اپنے پیروں پر کھڑا ہو گیا۔ {تھا...: عبرانی۔ گر گیا}\n22۔ لیکن شام کے بادشاہ حزائیل نے یہوآہاز کے تمام دنوں اسرائیل پر ظلم کیا۔\n23۔ اور خداوند نے ان پر مہربان رہا، ان پر رحم کیا، اور ان کا احترام کیا، کیونکہ اس نے ابراہیم، اسحاق اور یعقوب کے ساتھ عہد کیا تھا، اور نہ ہی انہیں تباہ کیا اور نہ ہی انہیں اپنی موجودگی سے نکالا۔ {موجودگی: عبرانی۔ چہرہ}\n24۔ یوں ہزائیل شام کا بادشاہ فوت ہوا؛ اور اس کے بیٹے بن حداد نے اس کی جگہ حکومت کی۔\n25۔ اور یہوآہاز کے بیٹے یہوآہاز نے بن حضاعیل کے بیٹے بن حداد کے ہاتھ سے وہ شہر دوبارہ لے لیے جو اس نے جنگ سے اپنے والد یہوآہاز کے ہاتھ سے لیے تھے۔ یوآش نے تین بار اسے مارا اور اسرائیل کے شہر واپس لے لیے۔ {لیا...: عبرانی۔ واپس آیا اور لے لیا}","1۔ یوآش کے دوسرے سال میں، یہوآہاز کے بیٹے، اسرائیل کے بادشاہ نے امازیا حکومت کی، جو یہوداہ کے بادشاہ یوآش کا بیٹا تھا۔\n2۔ وہ پچیس سال کے تھے جب انہوں نے حکومت شروع کی، اور یروشلم میں انتیس سال حکومت کی۔ اور اس کی والدہ کا نام یروشلم کا یہودان تھا۔\n3۔ اور اس نے وہ کیا جو خداوند کی نظر میں درست تھا، لیکن اپنے باپ داؤد کی طرح نہیں: اس نے ہر چیز کے مطابق کیا جیسا اس کے باپ یوآش نے کیا۔\n4۔ تاہم بلند مقامات نہیں چھین لیے گئے: ابھی تک لوگوں نے اونچی جگہوں پر قربانی دی اور لوبان جلائی۔\n5۔ اور جیسے ہی بادشاہی اس کے ہاتھ میں تصدیق ہوئی، اس نے اپنے ان خادموں کو قتل کر دیا جنہوں نے بادشاہ کو اس کے باپ کو قتل کیا تھا۔\n6۔ لیکن قاتلوں کے بچوں کو اس نے قتل نہیں کیا: جیسا کہ موسیٰ کی شریعت کی کتاب میں لکھا ہے، جس میں خداوند نے حکم دیا ہے، کہ باپ بچوں کے لیے قتل نہیں کیے جائیں گے، اور نہ ہی بچوں کو ان کے لیے قتل کیا جائے گا؛ لیکن ہر آدمی کو اس کے اپنے گناہ کی سزا دی جائے گی۔\n7۔ اس نے نمک کی وادی میں دس ہزار آدمیوں کو قتل کیا، اور سیلہ کو جنگ کے ذریعے قبضے میں لیا، اور آج تک اس کا نام جوکتھیل رکھتا ہے۔ {سیلاہ: یا، پتھر}\n8۔ پھر امازیہ نے یہوآہاز کے بیٹے یہوآہز، اسرائیل کے بادشاہ یہوآہاز کے بیٹے کے پاس پیغامبر بھیجے، اور کہا، آؤ، آؤ ایک دوسرے کی آنکھوں میں دیکھتے ہیں۔\n9۔ اور یہوآش، جو اسرائیل کا بادشاہ تھا، نے یہوداہ کے بادشاہ امازیاہ کو بھیجا، کہا، وہ کانٹے جو لبنان میں تھا اس دیودار کے پاس بھیجا جو لبنان میں تھا، اور کہا، اپنی بیٹی کو میرے بیٹے کو بیوی کے حوالے کر دو۔ اور وہاں لبنان میں ایک جنگلی جانور کے پاس سے گزرا اور کانٹے پر چل پڑا۔\n10۔ تم نے واقعی ایڈوم کو مارا ہے، اور تمہارا دل تمہیں بلند کر دیا ہے: اس کی شان و شوکت اور گھر میں ٹھہرو: کیونکہ تم کیوں اپنے زخم میں مداخلت کرو گے، کیوں تم گر جاؤ، یہاں تک کہ تم اور یہوداہ بھی تمہارے ساتھ ہوں؟ {گھر پر: عبوری۔ تمہارے گھر میں}\n11. لیکن امازیہ نے سننا نہیں چاہا۔ لہٰذا یہوآش بادشاہ اسرائیل چلا گیا؛ اور اس نے اور یہوداہ کے بادشاہ امازیا نے بیت شمش میں ایک دوسرے کے چہرے پر دیکھا، جو یہوداہ کی ملکیت ہے۔\n12۔ اور یہوداہ کو اسرائیل کے سامنے بدترین حالت میں ڈال دیا گیا؛ اور وہ ہر آدمی کو اپنے خیموں کی طرف بھاگ گئے۔ {put...: عبدی۔ عاشق}\n13۔ اور یہوآش، اسرائیل کا بادشاہ، یہوداہ کے بادشاہ امازیا کو، یہواش کا بیٹا بیت شمش لے گیا، اور یروشلم پہنچا، اور یروشلم کی دیوار کو افرایم کے دروازے سے کونے کے دروازے تک چار سو کیوبٹس تک توڑ دیا۔\n14۔ اور اس نے خداوند کے گھر میں پائے جانے والے تمام سونا اور چاندی، اور بادشاہ کے گھر کے خزانے اور یرغمالیوں کو لے کر سامریہ واپس آ گیا۔\n15۔ اب یہوآش کے باقی اعمال جو اس نے کیے، اس کی طاقت، اور اس نے یہوداہ کے بادشاہ امازیا سے کیسے لڑا، کیا وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n16۔ اور یہواش اپنے باپ و اجداد کے ساتھ سویا اور سامریہ میں اسرائیل کے بادشاہوں کے ساتھ دفن ہوا؛ اور اس کے بیٹے یربعام نے اس کی جگہ حکومت کی۔\n17۔ اور امازیہ، یہوداہ کے بادشاہ یوآش کا بیٹا، یہوآہاز کے بیٹے کی موت کے بعد پندرہ سال زندہ رہا۔\n18۔ اور امازیا کے باقی اعمال کیا یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n19۔ اب انہوں نے یروشلم میں اس کے خلاف سازش کی: اور وہ لاخیش بھاگ گیا؛ لیکن انہوں نے اسے لاچیش کے پاس بھیجا اور وہاں قتل کر دیا۔\n20۔ اور وہ اسے گھوڑوں پر لے گئے: اور اسے یروشلم میں اس کے آباؤ اجداد کے ساتھ داؤد شہر میں دفن کیا گیا۔\n21۔ اور یہوداہ کے تمام لوگوں نے عزریاہ کو، جو {سولہ} سال کا تھا، لیا اور اسے بادشاہ بنایا، نہ کہ اس کے والد امازیہ کے۔ {آزاریا: جسے اوزیا بھی کہا جاتا ہے}\n22۔ اس نے ایلاتھ تعمیر کیا، اور اسے یہوداہ کو واپس کر دیا، اس کے بعد بادشاہ نے اپنے باپ دادا کے ساتھ رات گزاری۔\n23۔ امازیا کے پندرہویں سال میں، یہوداہ کے بادشاہ یوایش یربعام کا بیٹا، جو اسرائیل کے بادشاہ یوآش کا بیٹا تھا، سامریہ میں حکومت کرنے لگا، {اور اکتالیس سال تک حکومت کی}۔\n24۔ اور اس نے وہ کیا جو خداوند کے سامنے برا تھا: اس نے یربعام نیبت کے بیٹے کے تمام گناہوں سے نہیں ہٹایا، جس نے اسرائیل کو گناہ میں مبتلا کیا۔\n25. اس نے اسرائیل کے ساحل کو حمات کے داخلے سے بحیرہ میدانوں تک بحال کیا، جیسا کہ خداوند اسرائیل کے خدا کے کلام کے مطابق اس نے اپنے خادم یونس کے ہاتھ سے کہا، جو امیتائی کے بیٹے، نبی تھے اور جو غاثفر کا {تھا} تھا۔\n26۔ کیونکہ خداوند نے اسرائیل کی مصیبت دیکھی، {کہ وہ بہت تلخ تھی} کیونکہ {نہ کوئی خاموش} تھا، نہ کوئی بچا، نہ کوئی مددگار اسرائیل کے لیے۔\n27۔ اور خداوند نے یہ نہیں کہا کہ وہ اسرائیل کا نام آسمان کے نیچے سے مٹا دے گا، بلکہ اس نے انہیں یروبعام کے ہاتھ سے بچایا جو یوآش کا بیٹا تھا۔\n28۔ اب یربعام کے باقی اعمال، اور اس نے جو کچھ کیا، اس کی طاقت، کیسے اس نے جنگ کی، اور کیسے اس نے دمشق کو واپس لیا، اور حمات، جو یہوداہ کا تھا، اسرائیل کے لیے، کیا وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھا؟\n29۔ اور یربعام اپنے باپ اجداد کے ساتھ سو گیا، {حتیٰ کہ} اسرائیل کے بادشاہوں کے ساتھ بھی؛ اور زکریا اس کے بیٹے نے اس کی جگہ حکومت کی۔","1۔ یربعام کے ستائیس سال میں اسرائیل کے بادشاہ عزریا بیٹا، امازیا کے بادشاہ یہوداہ کی حکومت کرنے لگا۔ {آزاریا: جسے اوزیا بھی کہا جاتا ہے}\n2۔ وہ سولہ سال کے تھے جب انہوں نے حکومت شروع کی، اور انہوں نے یروشلم میں دو پچاس سال حکومت کی۔ اور اس کی والدہ کا نام یروشلم کا یخولیاہ تھا۔\n3۔ اور اس نے وہ کیا جو خداوند کے سامنے تھا، جیسا کہ اس کے والد امازیا نے کیا تھا؛\n4. سوائے اس کے کہ اونچی جگہیں ہٹا دی گئیں: لوگ اب بھی اونچی جگہوں پر قربان اور لوبان جلاتے تھے۔\n5۔ اور خداوند نے بادشاہ کو مارا، یہاں تک کہ وہ اپنی موت تک کوڑھی رہا، اور کئی گھروں میں رہا۔ اور بادشاہ کا بیٹا یوتھام اس گھر پر حکمرانی کر رہا تھا، اور اس ملک کے لوگوں کا فیصلہ کر رہا تھا۔\n6۔ اور عزریاہ کے باقی اعمال اور اس نے جو کچھ کیا، کیا وہ یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n7. تو عزریاہ اپنے باپ دادا کے ساتھ سو گیا؛ اور انہوں نے اسے اس کے باپ دادا کے ساتھ داؤد شہر میں دفن کیا: اور اس کا بیٹا یوتھم اس کی جگہ حکومت کرنے لگا۔\n8۔ یہوداہ کے بادشاہ عزریاہ کے اڑتیس سال میں زکریا، یربعام کا بیٹا، چھ ماہ تک سامریا میں اسرائیل پر حکومت کرنے لگا۔\n9۔ اور اس نے خداوند کی نظر میں برا کیا، جیسا کہ اس کے آباؤ اجداد نے کیا تھا: اس نے یربعام، نیبت کے بیٹے کے گناہوں سے نہیں ہٹایا، جس نے اسرائیل کو گناہ میں مبتلا کیا۔\n10۔ اور شلوم، یابش کے بیٹے، نے اس کے خلاف سازش کی، اسے لوگوں کے سامنے شکست دی، قتل کر دیا، اور اس کی جگہ حکومت کی۔\n11۔ اور زکریا کے باقی اعمال دیکھیں، وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں لکھے گئے ہیں۔\n12. یہ خداوند کا کلام تھا جو اس نے یہو سے کہا، کہ تیرے بیٹے چوتھی نسل تک اسرائیل کے تخت پر بیٹھے ہوں گے۔ اور یوں یہ سب ہوا۔\n13۔ شلوم، یابش کا بیٹا، یہوداہ کے بادشاہ عزیاہ کے نویں اور تیسویں سال میں حکومت کرنے لگا؛ اور انہوں نے سامریہ میں پورا ایک مہینہ حکومت کی۔ {اوزیاہ: گریڈ اوزیاس} {ایک مکمل...: عبرانی۔ ایک مہینہ دن}\n14۔ کیونکہ مناہیم گادی کا بیٹا تیرزہ سے اوپر گیا، سامریہ آیا، اور سامریہ میں جابش کے بیٹے شلم کو مارا اور اسے قتل کر دیا، اور اس کی جگہ حکومت کی۔\n15۔ اور شلوم کے باقی اعمال اور اس کی سازش جو اس نے بنائی، دیکھیں، یہ سب اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں لکھی گئی ہیں۔\n16۔ پھر مناحم نے تیفسا کو مارا، اور اس میں موجود سب کچھ اور اس کے کنارے تیرزہ سے: کیونکہ وہ اس کے لیے نہیں کھلے، اس لیے اس نے اسے مارا اور اس میں موجود تمام عورتوں کو جو حاملہ تھیں پھاڑ دیا۔\n17۔ عزریاہ کے نویں اور تیسویں سال میں، یہوداہ کے بادشاہ مناحم، گادی کے بیٹے، نے اسرائیل پر حکومت شروع کی، {اور دس سال سامریا میں حکومت کی۔\n18۔ اور اس نے وہ کیا جو خداوند کی نظر میں برا تھا: اس نے اپنی تمام زندگی یربعام، نیبت کے بیٹے کے گناہوں سے دور نہیں کی، جس نے اسرائیل کو گناہ پر مجبور کیا۔\n19۔ {اور} آشور کا بادشاہ پل زمین پر حملہ آور ہوا: اور مناحم نے پل کو ہزار ٹیلنٹ چاندی دیے، تاکہ اس کا ہاتھ اس کے ہاتھ میں بادشاہت کی تصدیق ہو سکے۔\n20۔ اور مناحم نے اسرائیل کے پیسے لیے، {حتیٰ کہ} تمام دولت مند لوگوں سے، ہر آدمی سے پچاس شیکل چاندی کے لیے، تاکہ وہ آشور کے بادشاہ کو دے سکیں۔ چنانچہ آشور کا بادشاہ واپس مڑ گیا اور زمین میں نہیں رکا۔ {بالکل: عبرانی۔ سامنے آنے کی وجہ سے}\n21۔ اور میناحیم کے باقی اعمال اور اس نے جو کچھ کیا، کیا وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n22۔ اور مناحم نے اپنے باپ دادا کے ساتھ سونا شروع کیا؛ اور اس کے بیٹے پیکاحیاہ نے اس کی جگہ حکومت کی۔\n23۔ عزریاہ کے پچاسویں سال، یہوداہ پکاحیاہ کے بادشاہ میناہیم کے بیٹے نے سامریہ میں اسرائیل پر حکومت شروع کی، {اور دو سال تک حکومت کی}۔\n24۔ اور اس نے وہ کیا جو خداوند کی نظر میں برا تھا: اس نے یربعام نیبت کے بیٹے کے گناہوں سے نہیں ہٹایا، جس نے اسرائیل کو گناہ میں مبتلا کیا۔\n25۔ لیکن پیکاہ، رملیاہ کا بیٹا، جو اس کا سردار تھا، نے اس کے خلاف سازش کی، اور اسے سامریہ میں، بادشاہ کے محل میں، ارگوب اور آریہ کے ساتھ، اور اس کے ساتھ گلعادیوں کے پچاس آدمیوں کو مار ڈالا: اور اسے قتل کر دیا، اور اس کے کمرے میں حکومت کی۔\n26۔ اور پکاحیاہ کے باقی اعمال اور اس نے جو کچھ کیا، دیکھیں، وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں لکھے گئے ہیں۔\n27۔ عزریاہ کے دو اور پچاسویں سال میں، یہوداہ پیکا کے بادشاہ رملیاہ کے بیٹے نے سامریہ میں اسرائیل پر حکومت شروع کی، {اور بیس سال تک حکومت کی}۔\n28۔ اور اس نے وہ کیا جو خداوند کے سامنے برا تھا: اس نے نیبت کے بیٹے یربعام کے گناہوں سے نہیں ہٹا، جس نے اسرائیل کو گناہ میں مبتلا کیا۔\n29۔ اسرائیل کے بادشاہ پیکاہ کے زمانے میں آشور کے بادشاہ تیگلتھ پیلسر آیا، اور اس نے ایجون، ابیلبیت ماخا، اور یانواہ، قدیش، حزور، جلعاد، گلیل اور تمام نفتالی کی سرزمین پر قبضہ کر کے انہیں آشور میں قید کر لیا۔\n30۔ اور ہوشع ایلہ کے بیٹے نے رملیاہ کے بیٹے پیکا کے خلاف سازش کی، اسے مارا اور قتل کر دیا، اور اس کی جگہ یوثام بیٹے عزیہ کے بیسویں سال میں حکومت کی۔\n31۔ اور پیکہ کے باقی اعمال اور جو کچھ اس نے کیا، دیکھو، وہ اسرائیل کے بادشاہوں کی تاریخ کی کتاب میں لکھی گئی ہیں۔\n32۔ پیکا کے دوسرے سال میں، رملیاہ کے بیٹے، جو اسرائیل کے بادشاہ تھے، یوتھام، جو یہوداہ کے بادشاہ عزیہ کے بیٹے تھے، کو حکومت کرنے کا حکم دیا۔\n33۔ جب اس نے حکومت شروع کی تو اس کی عمر پانچ اور بیس سال تھی، اور اس نے یروشلم میں سولہ سال حکومت کی۔ اور اس کی والدہ کا نام {تھا} جیروشا، زادوک کی بیٹی۔\n34۔ اور اس نے خداوند کی نظر میں جو کچھ تھا وہ کیا: اس نے اپنے والد عزیاہ کے کیے ہوئے تمام اقدامات کے مطابق کیا۔\n35۔ تاہم بلند مقامات کو ہٹایا نہیں گیا: لوگ اب بھی اونچی جگہوں پر قربان کرتے اور لوبان جلاتے تھے۔ اس نے خداوند کے گھر کا اونچا دروازہ تعمیر کیا۔\n36۔ اب یوتھم کے باقی اعمال اور جو کچھ اس نے کیا، کیا وہ یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n37۔ ان دنوں خداوند نے شام کے بادشاہ یہوداہ رزین اور رملیاہ کے بیٹے پیکاہ کے خلاف بھیجنا شروع کیا۔\n38۔ اور یوتھم نے اپنے باپ دادا کے ساتھ سونا اور اپنے باپ کے ساتھ داؤد کے شہر میں دفن ہوا، اور اس کے بیٹے آحاز نے اس کی جگہ بادشاہی کی۔","1۔ پیکاہ کے سترہویں سال میں، رملیاہ کا بیٹا آحاز، جو یہوداہ کے بادشاہ یوتھام کا بیٹا تھا، حکومت کرنے لگا۔\n2. بیس سال کی عمر میں وہ آحاز تھا جب اس نے حکومت شروع کی، اور یروشلم میں سولہ سال حکومت کی، اور وہ جو کچھ تھا وہ خداوند اپنے خدا کی نظر میں درست نہیں تھا، جیسا کہ اس کا باپ داؤد تھا۔\n3۔ لیکن وہ اسرائیل کے بادشاہوں کے راستے میں چلتا رہا، ہاں، اور اپنے بیٹے کو آگ سے گزرنے پر مجبور کیا، جیسا کہ کافروں کی گناہوں کے مطابق تھا، جنہیں خداوند نے بنی اسرائیل کے سامنے نکال دیا تھا۔\n4۔ اور اس نے اونچی جگہوں پر، پہاڑوں پر، اور ہر سبز درخت کے نیچے لوبان قربان اور جلایا۔\n5۔ پھر رزین، شام کا بادشاہ اور پیکاہ کا بیٹا رمالیا، اسرائیل کے بادشاہ یروشلم میں جنگ کے لیے آئے: اور انہوں نے آہاز کا محاصرہ کیا، لیکن وہ اسے شکست نہ دے سکے۔\n6۔ اس وقت شام کے بادشاہ رضین نے ایلاث کو شام واپس لے آیا اور یہودیوں کو ایلاث سے نکال دیا: اور شامی ایلات آئے اور آج تک وہاں مقیم ہیں۔ {ایلاتھ: عبرانی سے. ایلوتھ سے}\n7۔ لہٰذا آحاز نے آشور کے بادشاہ تگلتھ پیلسر کے پاس پیغام بھیجے اور کہا، میں تمہارا خادم اور بیٹا ہوں: آؤ اور مجھے شام کے بادشاہ کے ہاتھوں اور اسرائیل کے بادشاہ کے ہاتھوں سے بچا لو، جو میرے خلاف اٹھ کھڑے ہوئے ہیں۔\n8۔ اور آحاز نے وہ چاندی اور سونا لیا جو خداوند کے گھر اور بادشاہ کے گھر کے خزانے میں پائے گئے تھے، اور اسے آشور کے بادشاہ کو تحفے کے لیے بھیجا۔\n9۔ اور آشور کے بادشاہ نے اس کی بات مانی: کیونکہ آشور کا بادشاہ دمشق کے خلاف گیا، اسے قبضے میں لے گیا، اور اس کے لوگوں کو قید کر میں لے گیا، اور ریزن کو قتل کر دیا۔ {دمشق: عبرانی۔ ڈامیسیک}\n10۔ اور بادشاہ آحاز دمشق گیا تاکہ آشور کے بادشاہ تگلتھ پیلسر سے ملے، اور وہاں ایک قربان گاہ دیکھی جو {تھا} میں تھی: اور بادشاہ آحاز نے یوریاہ کو کاهن کو قربان گاہ کا نقشہ اور اس کا نقشہ بھیجا، جیسا کہ تمام کاریگری کے مطابق تھا۔ {دمشق: عبرانی۔ ڈامیسیک}\n11۔ اور یوریاہ کاهن نے دمشق سے بادشاہ آحاز کی بھیجی گئی تمام چیزوں کے مطابق ایک قربان گاہ بنائی: تو یوریاہ کاهن نے بادشاہ احاز کے خلاف دمشق سے آ کر ایک قربان گاہ بنائی۔\n12۔ اور جب بادشاہ دمشق سے آیا، بادشاہ نے قربان گاہ دیکھی، اور بادشاہ قربان گاہ کے پاس گیا اور اس پر پیش کیا۔\n13۔ اور اس نے اپنی جلتی ہوئی قربانی اور گوشت کی قربانی جلائی، اور اپنی شراب کی قربانی دی، اور اپنے صلح کی قربانیوں کا خون قربان گاہ پر چھڑکا۔ {اس کی صلح کی پیشکشیں: عبرانی۔ وہ امن کی پیشکشیں جو اس کی تھیں}\n14۔ اور اس نے براسن قربان گاہ، جو خدا کے سامنے تھا، گھر کے سامنے سے، قربان گاہ اور خداوند کے گھر کے درمیان سے لایا اور اسے قربان گاہ کے شمالی جانب رکھا۔\n15۔ اور بادشاہ آحاز نے یوریاہ کاهن کو حکم دیا، کہا، عظیم قربان گاہ پر صبح کی جلنے کی قربانی، شام کی گوشت کی قربانی، بادشاہ کی جلتی ہوئی قربانی، اور اس کی گوشت کی قربانی، زمین کے تمام لوگوں کی جلنے کی قربانی، ان کے گوشت کی قربانی، اور ان کے شراب کی قربانیاں جلاؤ؛ اور اس پر جلانے والی قربانی کا سارا خون اور قربانی کا سارا خون چھڑک دو: اور براسن قربان گاہ میرے لیے ہوگی {بائی}۔\n16. یوں ہی یوریاہ کاہن نے بادشاہ احاز کے حکم کے مطابق کیا۔\n17۔ اور بادشاہ آحاز نے بنیادوں کی سرحدیں کاٹ دیں اور ان کے اوپر سے لیور ہٹا دیا؛ اور اس کے نیچے موجود براسن بیلوں سے سمندر کو نیچے اتار کر پتھروں کی فرش پر رکھ دیا۔\n18۔ اور سبت کے لیے جو پناہ گاہ انہوں نے گھر میں بنائی تھی، اور بادشاہ کے داخلے کے باوجود، اس نے خداوند کے گھر سے آشور کے بادشاہ کے لیے بھگا دیا۔\n19۔ اب آحاز کے باقی اعمال جو اس نے کیے، کیا وہ یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n20۔ اور آحاز نے اپنے باپ دادا کے ساتھ سونا اور اپنے آباؤ اجداد کے ساتھ داؤد کے شہر میں دفن ہوا: اور حزقیاہ اس کا بیٹا اس کی جگہ بادشاہی کرنے لگا۔","1۔ یہوداہ کے بادشاہ آحاز کے بارہویں سال میں ہوشع، ایلہ کے بیٹے، نے نو سال تک سامریہ میں اسرائیل پر حکومت کرنے کا فیصلہ کیا۔\n2۔ اور اس نے وہ کیا جو خداوند کی نظر میں برا تھا، لیکن اسرائیل کے بادشاہوں کی طرح نہیں جو اس سے پہلے تھے۔\n3۔ اس کے خلاف آشور کے بادشاہ شلمانسیر سامنے آئے؛ اور ہوشیہ اس کا خادم بن گیا، اور اسے تحفے دیے۔ {دیا گیا: عبوری۔ rendered} {presents: or, tribute}\n4۔ اور آشور کے بادشاہ کو ہوشیا میں سازش ملی: کیونکہ اس نے مصر کے بادشاہ سو کے پاس پیغام بھیجے تھے، اور آشور کے بادشاہ کو کوئی تحفہ نہیں دیا، جیسا کہ وہ سال بہ سال کرتا رہا: اس لیے آشور کے بادشاہ نے اسے بند کر دیا اور قید میں باندھ دیا۔ {حاضر: یا، خراج تحسین پیش کرنا}\n5۔ پھر آشور کا بادشاہ پورے ملک میں آیا، اور سامریہ تک گیا، اور تین سال تک اس کا محاصرہ کیا۔\n6۔ ہوشع کے نویں سال میں آشور کے بادشاہ نے سامریہ پر قبضہ کیا، اور اسرائیل کو آشور میں لے گیا، اور انہیں ہالہ اور حبور میں گوزان دریا کے کنارے، اور میڈز کے شہروں میں رکھا۔\n7۔ کیونکہ {یوں} یہ تھا کہ بنی اسرائیل نے اپنے خدا خداوند کے خلاف گناہ کیا تھا، جس نے انہیں مصر کی سرزمین سے، فرعون بادشاہ مصر کے ہاتھوں سے نکالا تھا، اور دوسرے دیوتاؤں سے ڈرتے تھے،\n8۔ اور وہ کافروں کے مجسموں میں چلے، جنہیں خداوند نے بنی اسرائیل اور اسرائیل کے بادشاہوں کے سامنے نکال دیا تھا، جو انہوں نے بنائے تھے۔\n9۔ اور بنی اسرائیل نے خفیہ طور پر وہ کام کیے جو خداوند ان کے خدا کے خلاف درست نہیں تھے، اور انہوں نے اپنے تمام شہروں میں اونچی جگہیں تعمیر کیں، چوکیداروں کے مینار سے لے کر باڑ والے شہر تک۔\n10۔ اور انہوں نے ہر اونچی پہاڑی پر، اور ہر سبز درخت کے نیچے ان کے لیے مجسمے اور جھنڈ بنائے۔ {تصاویر: عبرانی۔ مجسمے}\n11۔ اور وہاں انہوں نے تمام اونچی جگہوں پر لوبان جلائی، جیسا کہ وہ کافر جنہیں خداوند نے ان کے سامنے لے جایا تھا؛ اور خداوند کو غصہ دلانے کے لیے برے کام کیے:\n12۔ کیونکہ وہ بتوں کی عبادت کرتے تھے، جن کے بارے میں خداوند نے انہیں کہا تھا، تم یہ کام نہیں کرو گے۔\n13۔ پھر بھی خداوند نے اسرائیل اور یہوداہ کے خلاف، تمام نبیوں کے ذریعے، {اور} تمام بصیرت والوں کے ذریعے گواہی دی، کہ: اپنے برے راستوں سے منہ موڑو، اور میرے احکامات اور میرے قوانین کی پاسداری کرو، جیسا کہ میں نے تمہارے آباؤ اجداد کو حکم دیا تھا، اور جو میں نے اپنے بندوں نبیوں کے ذریعے تمہیں بھیجا تھا۔ {بذریعہ: عبرانی ہاتھوں سے}\n14۔ اگرچہ وہ سننا نہیں چاہتے تھے، بلکہ اپنے گلے سخت کر لیے، جیسے اپنے باپ اجداد کی گردن میں، جو خداوند اپنے خدا پر ایمان نہیں رکھتے تھے۔\n15۔ اور انہوں نے اس کے قوانین، اس کے اپنے باپ اجداد کے ساتھ کیے گئے وعدے اور ان کے خلاف گواہی دیے گئے بیانات کو رد کر دیا؛ اور انہوں نے غرور کی پیروی کی، اور خود پسند ہو گئے، اور ان کافروں کے پیچھے گئے جو ان کے ارد گرد تھے، {ان کے بارے میں} جن کے بارے میں خداوند نے انہیں حکم دیا تھا کہ وہ ان کی طرح نہ رہیں۔\n16۔ اور انہوں نے خداوند اپنے خدا کے تمام احکامات چھوڑ دیے، انہیں پگھلے ہوئے مجسمے بنائے، {حتیٰ کہ} دو بچھڑے بھی، ایک جنگل بنایا، آسمان کے تمام لشکر کی عبادت کی، اور بعل کی عبادت کی۔\n17۔ اور انہوں نے اپنے بیٹوں اور بیٹیوں کو آگ سے گزارا، پیش گوئی اور جادو استعمال کیے، اور خود کو خدا کے سامنے برائی کرنے کے لیے بیچ دیا، تاکہ اسے غصہ دلا سکیں۔\n18۔ اسی لیے خداوند اسرائیل سے بہت ناراض ہوا، اور انہیں اپنی نظر سے دور کر دیا: صرف یہوداہ قبیلے کے سوا کوئی باقی نہیں رہا۔\n19۔ یہوداہ نے خداوند کے احکامات کو نہیں اپنایا، بلکہ اسرائیل کے ان قوانین میں چلتا رہا جو انہوں نے بنائے تھے۔\n20۔ اور خداوند نے اسرائیل کی تمام نسل کو رد کر دیا، انہیں تکلیف دی، اور انہیں بگاڑنے والوں کے ہاتھ میں دے دیا، یہاں تک کہ اسے اپنی نظر سے دور کر دیا۔\n21۔ کیونکہ اس نے اسرائیل کو داؤد کے گھر سے کرایہ پر لیا؛ اور انہوں نے نیبت کے بیٹے یربعام کو بادشاہ بنایا: اور یربعام نے اسرائیل کو خداوند کی پیروی سے روک دیا، اور انہیں بڑا گناہ بنایا۔\n22۔ کیونکہ بنی اسرائیل یربعام کے تمام گناہوں میں چلے جو اس نے کیے؛ وہ ان سے نہیں ہٹے؛\n23۔ یہاں تک کہ خداوند نے اسرائیل کو اپنی نظر سے ہٹا دیا، جیسا کہ اس نے اپنے تمام بندوں نے نبیوں کو کہا تھا۔ اسی طرح اسرائیل کو آج تک ان کی سرزمین سے آشور لے جایا گیا۔\n24۔ اور آشور کے بادشاہ نے بابل، کوتھا، آوا، حماث اور سیفارویم سے {لوگ} لائے، اور انہیں اسرائیلی اولاد کی جگہ سامریہ کے شہروں میں رکھا، اور انہوں نے سامریہ پر قبضہ کر لیا اور وہاں کے شہروں میں بسے۔\n25۔ اور {یوں} ان کے قیام کے آغاز میں، {کہ} وہ خداوند سے نہیں ڈرتے تھے: اس لیے خداوند نے ان کے درمیان شیر بھیجے، جنہوں نے {کچھ} کو مار ڈالا۔\n26۔ اسی لیے انہوں نے آشور کے بادشاہ سے بات کی، کہا، جنہیں تم نے ہٹا کر سامریہ کے شہروں میں رکھا ہے، وہ زمین کے خدا کا طریقہ نہیں جانتیں، اس لیے اس نے ان کے درمیان شیر بھیجے ہیں، اور دیکھتے ہیں کہ وہ انہیں مار ڈالتے ہیں، کیونکہ وہ زمین کے خدا کے طریقہ کار کو نہیں جانتے۔\n27۔ پھر آشور کے بادشاہ نے حکم دیا، کہا کہ وہاں سے لائی گئی ایک پادری کو لے جاؤ؛ اور انہیں وہاں رہنے دو، اور وہ انہیں زمین کے خدا کا طریقہ سکھائے۔\n28۔ پھر ان پادریوں میں سے ایک جسے انہوں نے سامریہ سے لے جا کر لے جایا تھا، بیٹھل میں آیا اور انہیں سکھایا کہ خداوند سے کیسے ڈرنا چاہیے۔\n29۔ تاہم ہر قوم نے اپنے دیوتا بنائے، اور انہیں ان اونچے مقامات کے گھروں میں رکھا جو سامریتیوں نے بنائے تھے، ہر قوم کو ان کے شہروں میں جہاں وہ رہتے تھے۔\n30۔ اور بابل کے لوگوں نے سوکوتھبینوت بنایا، کوتھ کے لوگوں نے نرگال بنایا، اور حمات کے لوگوں نے اشیما بنایا،\n31۔ اور آویوں نے نیبہاز اور تارتک بنائے، اور سفارویوں نے اپنے بچوں کو آگ میں جلا دیا، جو سیفارویم کے دیوتاؤں ادراملک اور انامیلیک تھے۔\n32۔ یوں وہ خداوند سے ڈرتے تھے، اور ان میں سب سے نچلے درجے کے پادری کو بلند مقامات کے پادری بنا دیے، جو ان کے لیے اونچے مقامات کے گھروں میں قربانی دیتے تھے۔\n33۔ وہ خداوند سے ڈرتے تھے، اور اپنے دیوتاؤں کی خدمت کرتے تھے، ان قوموں کی طرح جنہیں وہ وہاں سے لے گئے۔ {کون...: یا، جس نے انہیں وہاں سے لے جایا}\n34۔ آج تک وہ پہلے آداب کی پیروی کرتے ہیں: وہ خداوند سے نہیں ڈرتے، نہ اپنے قوانین، نہ اپنے احکام، اور نہ ہی اس قانون اور حکم کے بعد جو خداوند نے یعقوب کے بچوں کو حکم دیا، جسے اس نے اسرائیل کا نام دیا؛\n35۔ جن سے خداوند نے عہد کیا تھا، اور انہیں حکم دیا تھا، کہ تم دوسرے دیوتاؤں سے نہ ڈرو، نہ ان کے سامنے جھکنا، نہ ان کی عبادت کرنا، نہ ان کے لیے قربانی کرنا:\n36۔ لیکن اس خداوند، جس نے تمہیں مصر کی سرزمین سے بڑی طاقت اور پھیلائے ہوئے بازو کے ساتھ نکالا، اس سے ڈرو گے، اس کی عبادت کرو گے، اور اس کے لیے قربانی کرو گے۔\n37۔ اور وہ قوانین، احکامات، قانون اور حکم جو اس نے تمہارے لیے لکھا، تم ہمیشہ کے لیے عمل کرو گے؛ اور تم دوسرے دیوتاؤں سے مت ڈرو۔\n38۔ اور وہ عہد جو میں نے آپ سے کیا ہے، آپ اسے کبھی نہیں بھولیں گے؛ نہ ہی تم دوسرے دیوتاؤں سے ڈرو گے۔\n39۔ لیکن خداوند آپ کے خدا سے آپ ڈریں گے؛ اور وہ تمہیں تمہارے تمام دشمنوں کے ہاتھوں سے آزاد کرے گا۔\n40۔ تاہم انہوں نے سنا نہیں، لیکن اپنے پہلے انداز میں سنے۔\n41۔ تو یہ قومیں خداوند سے ڈرتی تھیں، اور اپنے کندہ شدہ مجسموں کی خدمت کرتی تھیں، اپنے بچوں اور بچوں کے بچوں کی بھی: جیسے ان کے باپوں نے کیا، آج تک ایسا ہی کرتے ہیں۔","1۔ یہ واقعہ اسرائیل کے بادشاہ ایلاہ کے ہوشع کے تیسرے سال میں ہوا، {کہ} حزقیاہ بادشاہ آحاز بادشاہ کا بیٹا حکومت کرنے لگا۔ {حزقیاہ: اسے ایزیکیا کہا جاتا ہے}\n2۔ جب اس نے حکومت شروع کی تو وہ پچیس سال کا تھا؛ اور انہوں نے یروشلم میں انتیس سال حکومت کی۔ ان کی والدہ کا نام بھی ابی تھا، جو زکریا کی بیٹی تھیں۔ {ابی: جسے ابیاہ بھی کہا جاتا ہے}\n3۔ اور اس نے خداوند کی نظر میں جو کچھ تھا کیا، جیسا کہ اس کے باپ نے کیا۔\n4۔ اس نے اونچی جگہیں ہٹا دیں، اور مجسمے توڑے، جھنڈ کاٹ دیے، اور موسیٰ کے بنائے ہوئے اس سانپ کو ٹکڑوں میں توڑ دیا: کیونکہ ان دنوں تک بنی اسرائیل اس پر لوبان جلاتے تھے: اور اس نے اسے نہوشتان کہا۔ {تصاویر: عبرانی۔ مجسمے} {نہوشتان: یعنی پیتل کا ایک ٹکڑا}\n5. اس نے اسرائیل کے خداوند خدا پر بھروسہ کیا؛ تاکہ اس کے بعد یہوداہ کے تمام بادشاہوں میں اس جیسا کوئی نہ ہو، نہ ہی اس سے پہلے کوئی بادشاہ۔\n6۔ کیونکہ اس نے خداوند کے سامنے وفاداری اختیار کی، {اور} اس کی پیروی سے نہیں ہٹا، بلکہ اپنے احکامات کی پاسداری کی، جو خداوند نے موسیٰ کو حکم دیے۔ {سے...: عبرانی اس کے بعد سے}\n7۔ اور خداوند اس کے ساتھ تھا؛ {اور} وہ جہاں بھی گیا وہاں خوشحال ہوا: اور اس نے آشور کے بادشاہ کے خلاف بغاوت کی، اور اس کی خدمت نہیں کی۔\n8۔ اس نے فلسطینیوں کو، {حتیٰ کہ} غزہ اور اس کی سرحدوں تک، چوکیداروں کے برج سے لے کر باڑ والے شہر تک، شکست دی۔ {غزہ: عبرانی۔ عزا}\n9۔ اور یہ بادشاہ حزقیاہ کے چوتھے سال میں ہوا، جو اسرائیل کے بادشاہ ایلاہ کے ہوشع کے بیٹے کا ساتواں سال تھا، {و} شلمانسیر بادشاہ آشور نے سامریہ پر حملہ کیا اور اس کا محاصرہ کر لیا۔\n10۔ اور تین سال کے آخر میں انہوں نے اسے لے لیا: حزقیاہ کے چھٹے سال میں، یعنی اسرائیل کے بادشاہ ہوشع کا نویں سال، سامریہ پر قبضہ کر لیا گیا۔\n11۔ اور آشور کے بادشاہ نے اسرائیل کو آشور لے جایا، اور انہیں ہالہ اور ہابور میں گوزان دریا کے کنارے، اور میڈیز کے شہروں میں رکھا:\n12۔ کیونکہ انہوں نے خداوند اپنے خدا کی آواز کی اطاعت نہیں کی، بلکہ اس کے عہد کی خلاف ورزی کی، {اور} وہ سب کچھ جو موسیٰ خداوند کے بندے نے حکم دیا، اور نہ ہی ان کی بات سنی۔\n13۔ بادشاہ حزقیاہ کے چودہویں سال میں، آشور کے بادشاہ سناخریب نے یہوداہ کے تمام باڑ والے شہروں پر حملہ کیا اور انہیں فتح کر لیا۔ {سیناخریب: عبرانی۔ سنہریب}\n14۔ اور یہوداہ کے بادشاہ حزقیاہ نے آشور کے بادشاہ کو لاخیش کے پاس بھیجا اور کہا، میں نے ناراض کیا ہے؛ مجھ سے واپس: جو کچھ تو مجھ پر ڈالتا ہے میں اٹھاؤں گا۔ اور آشور کے بادشاہ نے حزقیاہ کو یہوداہ کا بادشاہ تین سو ٹیلنٹ چاندی اور تیس ٹیلنٹ سونا مقرر کیا۔\n15۔ اور حزقیاہ نے {اسے} وہ تمام چاندی دی جو خداوند کے گھر اور بادشاہ کے گھر کے خزانے میں ملی تھی۔\n16۔ اسی وقت حزقیاہ نے خداوند کے مندر کے دروازوں سے سونا کاٹ دیا، اور وہ ستون جو یہوداہ کے بادشاہ حزقیاہ نے لگائے تھے، اور اسے آشور کے بادشاہ کو دے دیا۔ {it: عبرانی وہ}\n17۔ اور آشور کے بادشاہ نے ترتان، ربساریس اور ربشاکہ کو لاخیش سے بادشاہ حزقیاہ کے پاس ایک بڑی فوج کے ساتھ یروشلم کے خلاف بھیجا۔ اور وہ اوپر گئے اور یروشلم آئے۔ اور جب وہ اوپر آئے، تو وہ اوپر والے تالاب کے راستے کے پاس کھڑے ہو گئے، جو فلر کے میدان کی شاہراہ پر واقع ہے۔ {زبردست: عبوری۔ ہیوی}\n18۔ اور جب انہوں نے بادشاہ کو بلایا، تو ان کے پاس ایلیاکیم، ہلکیا کا بیٹا، جو گھرانے کا محافظ تھا، اور شبنا کاتب، اور یوح، عصفہ کا بیٹا، ریکارڈر آیا۔ {کاتب: یا، سیکرٹری}\n19۔ اور ربشکہ نے ان سے کہا، اب حزقیاہ سے بات کرو، یہی عظیم بادشاہ، آشور کے بادشاہ نے فرمایا، یہ کس اعتماد پر ہے جس پر تم بھروسہ کرتے ہو؟\n20۔ تم کہتے ہو، (لیکن {یہ صرف فضول باتیں ہیں،) {میرے پاس جنگ کے لیے مشورہ اور طاقت ہے۔ اب تم کس پر بھروسہ کرتے ہو کہ تم میرے خلاف بغاوت کرتے ہو؟ {سیسٹ: یا، باتیں کرنا} {vanin...: عبرانی ہونٹوں کا لفظ} {میرے پاس ہے...: یا، لیکن مشورہ اور طاقت جنگ کے لیے ہے}\n21۔ اب دیکھو، تم اس زخمی سرکنڈے کے عصا پر مصر پر بھروسہ کرتے ہو، جس پر اگر کوئی آدمی جھکے گا تو وہ اس کے ہاتھ میں چلا جائے گا اور اسے چیر دے گا: اسی طرح فرعون مصر کا بادشاہ ہے ان سب کے لیے جو اس پر بھروسہ کرتے ہیں۔ {قابل اعتماد: عبرانی۔ تم پر بھروسہ کرو}\n22. لیکن اگر تم مجھ سے کہو، ہم اپنے خداوند خدا پر بھروسہ کرتے ہیں: کیا وہ نہیں کہ جس کے بلند مقامات اور قربان گاہیں حزقیاہ نے لے لی ہیں، اور یہوداہ اور یروشلم سے کہا ہے، تم یروشلم میں اس مذبح کے سامنے عبادت کرو گے؟\n23۔ اب میں تم سے درخواست کرتا ہوں، میرے آقا آشور کے بادشاہ کو وعدے دو، اور میں تمہیں دو ہزار گھوڑے دے دوں گا، اگر تم ان پر سوار بٹھا سکو۔ {وعدے: یا، یرغمالی}\n24۔ تو پھر تم میرے آقا کے سب سے چھوٹے خادموں میں سے ایک کپتان کا چہرہ کیسے موڑو گے، اور مصر پر رتھ اور گھڑ سواروں کے لیے بھروسہ کرو گے؟\n25. کیا اب میں خدا کے بغیر اس جگہ کے خلاف آ رہا ہوں تاکہ اسے تباہ کر سکوں؟ خداوند نے مجھ سے کہا، اس زمین کے خلاف جاؤ اور اسے تباہ کر دو۔\n26۔ پھر الیاقیم ہلکیاہ کے بیٹے، شبنا، اور جوح نے ربشکہ سے کہا، میں تم سے دعا کرتا ہوں کہ اپنے بندوں سے شامی زبان میں بات کرو؛ کیونکہ ہم سمجھتے ہیں: اور ہم سے یہودیوں کی زبان میں ان لوگوں کے کانوں میں بات نہیں کرتے جو دیوار پر ہیں۔\n27۔ لیکن ربشکہ نے ان سے کہا، کیا میرے آقا نے مجھے تمہارے آقا اور تمہارے پاس بھیجا ہے تاکہ یہ الفاظ کہہ سکوں؟ کیا اس نے مجھے ان لوگوں کے پاس نہیں بھیجا جو دیوار پر بیٹھے ہیں، تاکہ وہ اپنا گوبر کھائیں اور تمہارے ساتھ اپنا پیشاب پی سکیں؟ {ان کا اپنا پیشاب: عبرانی۔ ان کے پاؤں کا پانی}\n28۔ پھر ربشاکہ کھڑا ہوا اور یہودیوں کی زبان میں بلند آواز میں پکارا اور کہا، عظیم بادشاہ، آشور کے بادشاہ کا کلام سنو:\n29۔ بادشاہ یوں کہتا ہے، حزقیاہ تمہیں دھوکہ نہ دے، کیونکہ وہ تمہیں اپنے ہاتھوں سے آزاد نہیں کر سکے گا:\n30. حزقیاہ تمہیں خداوند پر بھروسہ کرنے پر مجبور نہ کرے، یہ کہتے ہوئے، خداوند ہمیں ضرور نجات دے گا، اور یہ شہر آشور کے بادشاہ کے ہاتھ میں نہیں دیا جائے گا۔\n31۔ حزقیاہ کی بات نہ سنو: کیونکہ آشور کے بادشاہ نے یوں کہا، مجھ سے تحفے کے ذریعے معاہدہ کرو، اور میرے پاس آؤ، اور پھر ہر آدمی کو اس کی انگور اور اس کے انجیر کے درخت سے کھاؤ، اور ہر ایک کو اس کے حوض کے پانی سے پی لو: {بنو...: یا، میری عنایت طلب کرو:  عبرانی۔ میرے ساتھ ایک دعا بناؤ} {حوض: یا، گڑھ}\n32۔ جب تک میں آ کر تمہیں تمہاری اپنی زمین کی طرح لے جاؤں، اناج اور شراب کی زمین، روٹی اور انگور کی زمین، تیل زیتون اور شہد کی زمین، تاکہ تم زندہ رہو اور مر نہ سکو: اور حزقیاہ کی بات نہ سنو، جب وہ تمہیں قائل کرے کہ خداوند ہمیں نجات دے گا۔ {قائل کرو: یا، دھوکہ دو}\n33۔ کیا قوموں کے کسی دیوتاؤں نے اپنی زمین پر آشور کے بادشاہ کے ہاتھوں سے نجات دلائی ہے؟\n34. حماتھ اور آرپاد کے دیوتا کہاں ہیں؟ سیفاروائم، ہینا، اور ایواہ کے دیوتا کہاں ہیں؟ کیا انہوں نے سامریا میرے ہاتھ سے آزاد کر دیا ہے؟\n35۔ وہ ان تمام دیوتاؤں میں کون ہیں جنہوں نے اپنے ملک کو میرے ہاتھوں سے بچایا، کہ خداوند یروشلم کو میرے ہاتھ سے آزاد کرے؟\n36۔ لیکن لوگوں نے خاموش رہے، اور اس کا ایک لفظ بھی جواب نہ دیا: کیونکہ بادشاہ کا حکم تھا، \"اس کا جواب نہ دو۔\"\n37۔ پھر ایلیاکیم، ہلکیا کا بیٹا، جو گھرانے کا ذمہ دار تھا، اور شبنا کاتب اور یوح عیساف کا بیٹا، حزقیاہ کے پاس آئے اور ان کے کپڑے پھاڑ دیے، اور اسے ربشکہ کے الفاظ سنائے۔","1۔ اور ایسا ہوا جب بادشاہ حزقیاہ نے سنا، کہ اس نے اپنے کپڑے پھاڑ دیے، خود کو تھیلے کے کپڑے سے ڈھانپ لیا، اور خداوند کے گھر میں چلا گیا۔\n2۔ اور اس نے ایلیاکیم، جو گھر کے اوپر تھا، اور شبنا کاتب اور کاہنوں کے بزرگ، جو کپڑے سے ڈھکے ہوئے تھے، اشعیا نبی آموز کے بیٹے کے پاس بھیجا۔\n3۔ اور انہوں نے اس سے کہا، حزقیاہ نے یوں کہا، آج دن مصیبت، ملامت اور کفر کا دن ہے: کیونکہ بچے پیدائش کے لیے آئے ہیں، اور پیدا کرنے کی طاقت نہیں۔ {کفر: یا، اشتعال انگیزی}\n4. ممکن ہے کہ خداوند تیرا خدا ربشاکہ کے تمام الفاظ سنے، جسے اس کا آقا آشور کے بادشاہ نے زندہ خدا کو ملامت کرنے کے لیے بھیجا ہے؛ اور ان الفاظ کو ملامت کرے گا جو خداوند تیرے خدا نے سنے ہیں: لہٰذا باقی ماندہ لوگوں کے لیے اپنی دعا بلند کرو۔ {بائیں: عبرانی۔ مل گیا}\n5۔ یوں بادشاہ حزقیاہ کے خادم یسعیاہ کے پاس آئے۔\n6۔ اور یسعیاہ نے ان سے کہا، تو تم اپنے آقا سے یوں کہو گے، خداوند نے فرمایا، ان الفاظ سے نہ ڈرو جو تم نے سنے، جن سے آشور کے بادشاہ کے خادموں نے میری کفر کی ہے۔\n7۔ دیکھو، میں اس پر ایک دھماکہ بھیجوں گا، اور وہ افواہ سنے گا، اور اپنے ملک واپس چلا جائے گا؛ اور میں اسے اس کی اپنی زمین میں تلوار کے ہاتھوں مارنے پر مجبور کروں گا۔\n8۔ تو ربشکہ واپس آیا، اور دیکھا کہ آشور کا بادشاہ لبنہ کے خلاف جنگ کر رہا ہے: کیونکہ اس نے سنا تھا کہ وہ لاخیش سے چلا گیا ہے۔\n9۔ اور جب اس نے ایتھوپیا کے بادشاہ ترحکہ کے بارے میں سنا، دیکھو، وہ تمہارے خلاف لڑنے آیا ہے: اس نے حزقیاہ کے پاس دوبارہ قاصد بھیجے اور کہا،\n10۔ اسی طرح تم یہوداہ کے بادشاہ حزقیاہ سے بات کرو گے، کہو گے، اپنے خدا کو جس پر تم بھروسہ کرتے ہو، تمہیں دھوکہ نہ دے، اور کہیں کہ یروشلم کو آشور کے بادشاہ کے ہاتھ میں نہیں دیا جائے گا۔\n11۔ دیکھو، تم نے سنا کہ آشور کے بادشاہوں نے تمام زمینوں کے ساتھ کیا کیا ہے، انہیں مکمل طور پر تباہ کر کے: اور کیا تم آزاد ہو جاؤ گے؟\n12۔ قوموں کے دیوتاؤں نے انہیں نجات دی جنہیں میرے آباؤ اجداد نے تباہ کیا؛ {as} گوزان، اور ہاران، اور ریزف، اور عدن کے بچے جو تھیلاسر میں تھے؟\n13۔ حمتھ کا بادشاہ، آرپاد کا بادشاہ، اور شہر سیفاروایم، حنا اور ایوا کا بادشاہ کہاں ہے؟\n14۔ اور حزقیاہ نے رسولوں کے ہاتھ کا خط وصول کیا اور اسے پڑھا: اور حزقیاہ خداوند کے گھر میں چلا گیا اور اسے خداوند کے سامنے پھیلایا۔\n15۔ اور حزقیاہ نے خداوند کے سامنے دعا کی اور کہا، اے خداوند اسرائیل کے خدا، جو فرشتہوں کے درمیان رہتا ہے، تو خدا ہے، {حتیٰ کہ} تو اکیلا زمین کی تمام بادشاہتوں کا ہے؛ تو نے آسمان اور زمین کو بنایا ہے۔\n16۔ اے خداوند، اپنا کان جھک کر سنو: اے خداوند، اپنی آنکھیں کھول، اور دیکھو: اور سنحرب کے الفاظ سنو، جنہوں نے اسے زندہ خدا کو ملامت کرنے بھیجا ہے۔\n17۔ اے خداوند، سچ کہوں تو، آشور کے بادشاہوں نے قوموں اور ان کی زمینوں کو تباہ کر دیا ہے،\n18۔ اور انہوں نے اپنے دیوتاؤں کو آگ میں پھینک دیا: کیونکہ وہ کوئی خدا نہیں تھے، بلکہ انسانوں کے ہاتھوں، لکڑی اور پتھر کا کام تھا، اس لیے انہوں نے انہیں تباہ کر دیا۔ {کاسٹ: عبوری۔ دیا گیا}\n19۔ اب، اے خداوند ہمارے خدا، میں تجھ سے التجا کرتا ہوں کہ ہمیں اس کے ہاتھ سے بچا لے، تاکہ زمین کی تمام بادشاہتیں جان سکیں کہ تو ہی خداوند خدا ہے، {حتیٰ کہ} صرف تو۔\n20۔ پھر اموز کے بیٹے یسعیاہ نے حزقیاہ کے پاس بھیجا اور کہا، \"یہی فرماتا ہے اسرائیل کے خداوند نے، {وہ} جو تم نے مجھ سے سنخریب بادشاہ آشور کے خلاف دعا کی ہے، میں نے سنا ہے۔\n21. یہ وہ کلام ہے جو خداوند نے اس کے بارے میں کہا ہے؛ کنواری صیون کی بیٹی نے تمہیں حقیر سمجھا، {اور} تم پر ہنسی اڑائی؛ یروشلم کی بیٹی نے تم پر سر ہلا دیا ہے۔\n22۔ تم نے کس کو ملامت اور گستاخی کی؟ اور کس کے خلاف تم نے اپنی آواز بلند کی، اور اپنی آنکھیں بلند کیں؟ {حتیٰ کہ} اسرائیل کے مقدس {واحد} کے خلاف۔\n23۔ اپنے رسولوں کے ذریعے تم نے خداوند کو ملامت کی ہے، اور کہا ہے، میں اپنی رتھوں کی کثرت کے ساتھ پہاڑوں کی بلندی پر پہنچا ہوں، لبنان کے کناروں پر، اور ان کے اونچے دیودار کے درخت کاٹوں گا، {اور} ان کے منتخب صنوبر کے درخت: اور میں اس کی سرحدوں کے ٹھکانوں میں داخل ہو جاؤں گا،  {اور} اپنے کارمل کے جنگل میں۔ {بذریعہ: عبرانی۔ {لمبا...: عبرانی کے ہاتھوں لمبائی وغیرہ} {اس کے کارمل: یا، اور اس کے زرخیز کھیت کی}\n24. میں نے عجیب پانی کھودا اور پیا، اور اپنے پیروں کے تلوے سے محصور علاقوں کی تمام ندیاں خشک کیں۔ {محصور: یا، باڑ لگا ہوا}\n25. کیا تم نے بہت پہلے نہیں سنا {کیسے} میں نے یہ کیا، {اور} قدیم زمانے سے کہ میں نے اسے بنایا ہے؟ اب میں نے یہ حقیقت بنا دی ہے کہ تم باڑ والے شہروں کو تباہ شدہ ڈھیروں میں بدل دو۔ {لمبا...: یا، میں نے اسے بہت پہلے بنایا، اور اسے قدیم زمانے کی شکل دی؟ کیا اب مجھے اسے تباہ کر دینا چاہیے، اور باڑ والے شہروں کو تباہ کن ڈھیر بنا دینا چاہیے؟}\n26۔ اسی لیے ان کے باشندے کم طاقت کے حامل تھے، وہ پریشان اور پریشان تھے؛ وہ کھیت کی گھاس کی طرح تھے، اور سبز جڑی بوٹی کی طرح، گھروں کی چھتوں پر گھاس کی طرح، اور مکئی کی طرح جو اگنے سے پہلے اڑی جاتی تھی۔ {چھوٹے...: عبرانی۔ ہاتھ کم ہے}\n27۔ لیکن میں تمہارا ٹھکان، تمہارا جانا، تمہارا آنا، اور تمہارا میرے خلاف غصہ جانتا ہوں۔ {رہائش: یا، بیٹھنا}\n28۔ کیونکہ تمہارا غصہ میرے خلاف اور تمہارا ہنگامہ میرے کانوں تک پہنچ گیا ہے، اس لیے میں اپنا کانٹا تمہاری ناک میں رکھوں گا، اور اپنی لگام تمہارے ہونٹوں میں رکھوں گا، اور تمہیں اس راستے سے واپس موڑ دوں گا جس سے تم آئے تھے۔\n29۔ اور یہ تمہارے لیے ایک نشانی ہوگی، اس سال تم وہ چیزیں کھاؤ گے جو خود اگتی ہیں، اور دوسرے سال وہ جو اس سے نکلتی ہے؛ اور تیسرے سال میں بوئیں، فصل لگائیں، انگور کے باغ لگائیں، اور ان کے پھل کھائیں۔\n30۔ اور یہوداہ کے گھر کی باقیات دوبارہ نیچے کی طرف جڑ پکڑے گی، اور اوپر پھل دے گی۔ {باقیات...: عبرانی۔ یہوداہ کے گھر سے فرار جو باقی ہے}\n31۔ کیونکہ یروشلم سے ایک باقی ماندہ فوج نکلے گی، اور جو پہاڑ صیون سے نکلیں گے: خداوند [لشکروں} کا جوش یہی کرے گا۔ {وہ...: عبرانی۔ دی ایسکیپنگ}\n32. لہٰذا خداوند آشوری کے بادشاہ کے بارے میں یوں فرماتا ہے، وہ اس شہر میں داخل نہیں ہوگا، نہ وہاں تیر چلے گا، نہ ڈھال لے کر آئے گا، نہ اس پر کوئی کنارہ ڈالے گا۔\n33۔ جس راستے سے وہ آیا، اسی راستے سے واپس آئے گا، اور اس شہر میں نہیں آئے گا، خداوند فرماتا ہے۔\n34۔ کیونکہ میں اس شہر کا دفاع کروں گا، اسے بچانے کے لیے، اپنے لیے، اور اپنے خادم داؤد کے لیے۔\n35۔ اور اسی رات ایسا ہوا کہ خداوند کا فرشتہ باہر نکلا، اور آشوریوں کے کیمپ میں ایک لاکھ چولیس پانچ ہزار کو مارا: اور جب وہ صبح سویرے اٹھے، تو وہ سب مردہ لاشیں تھے۔\n36۔ یوں آشور کا بادشاہ سنحریب، روانہ ہوا، واپس آیا، اور نینوا میں بسنے لگا۔\n37۔ اور جب وہ اپنے خدا نسرخ کے گھر میں عبادت کر رہا تھا، تو اس کے بیٹوں ادرامیلخ اور شارزر نے اسے تلوار سے مارا: اور وہ آرمینیا کی سرزمین میں فرار ہو گئے۔ اور اس کا بیٹا ایسرحدون اس کی جگہ حکمرانی کرتا رہا۔ {آرمینیا: عبرانی۔ ارارات}","1۔ ان دنوں حزقیاہ موت کے قریب بیمار تھا۔ اور پیغمبر یسعیاہ ابن اموز اس کے پاس آیا اور کہا، خداوند یوں فرماتا ہے، اپنے گھر کو ترتیب دو؛ کیونکہ تم مر جاؤ گے، اور زندہ نہیں رہو گے۔ {سیٹ...: عبرانی اپنے گھر کی ضمانت دو}\n2۔ پھر اس نے اپنا چہرہ دیوار کی طرف موڑا اور خداوند سے دعا کرتے ہوئے کہا،\n3۔ اے خداوند، میں تجھ سے التجا کرتا ہوں کہ اب یاد کرو کہ میں تمہارے سامنے سچائی اور کامل دل کے ساتھ چلا ہوں، اور تمہاری نظر میں وہ سب کچھ کیا جو اچھا ہے۔ اور حزقیاہ شدید آنسو بہانے لگا۔ {درد: عبوری۔ بڑے رونے کے ساتھ}\n4۔ اور یہ ہوا، جب یسعیاہ درمیانی صحن میں جانے سے پہلے ہی خداوند کا کلام اس کے پاس آیا، اور کہا، {دربار: یا، شہر}\n5۔ دوبارہ مڑو، اور حزقیاہ کو بتانا، جو میری قوم کا سردار ہے، یہ فرماتا ہے، خداوند تمہارے باپ، داؤد کا خدا، میں نے تمہاری دعا سنی ہے، میں نے تمہارے آنسو دیکھے ہیں: دیکھو، میں تمہیں شفا دوں گا: تیسرے دن تم خداوند کے گھر جاؤ گے۔\n6۔ اور میں تیرے دنوں میں پندرہ سال شامل کروں گا؛ اور میں تمہیں اور اس شہر کو آشور کے بادشاہ کے ہاتھوں سے آزاد کروں گا؛ اور میں اس شہر کا دفاع اپنے لیے کروں گا، اور اپنے خادم داؤد کی خاطر۔\n7۔ اور یسعیاہ نے کہا، انجیر کا ایک گٹھا لے لو۔ اور انہوں نے اسے ابال پر رکھ دیا، اور وہ صحت یاب ہو گیا۔\n8۔ اور حزقیاہ نے یسعیاہ سے کہا، وہ کیا نشانی ہوگی کہ خداوند مجھے شفا دے گا، اور میں تیسرے دن خداوند کے گھر میں جاؤں گا؟\n9۔ اور یسعیاہ نے کہا، یہ نشانی تمہیں خداوند کی طرف سے ملے گی، کہ خداوند وہی کرے گا جو اس نے کہا ہے: کیا سایہ دس ڈگری آگے جائے گا یا دس ڈگری پیچھے؟\n10۔ اور حزقیاہ نے جواب دیا، سایہ دس درجے نیچے جانا ہلکی بات ہے: نہیں، لیکن سایہ دس ڈگری پیچھے لوٹ جائے۔\n11۔ اور یسعیاہ نبی نے خداوند کو پکارا: اور اس نے سایہ کو دس درجے پیچھے لے آیا، جس سے وہ آہاز کے ڈائل میں نیچے چلا گیا۔ {ڈائل: عبرانی ڈگریا}\n12۔ اس وقت بابل کے بادشاہ بالادان کے بیٹے بیروڈخبالادان نے حزقیاہ کو خطوط اور تحفہ بھیجا: کیونکہ اس نے سنا تھا کہ حزقیاہ بیمار ہے۔ {بروداچبالادان: یا، میروداخبالادان}\n13۔ اور حزقیاہ نے ان کی بات مانی، اور انہیں اپنی قیمتی چیزوں کا گھر دکھایا، چاندی، سونا، مصالحے، قیمتی مرہم، اور اپنے زرہ کا سارا گھر، اور جو کچھ اس کے خزانے میں ملا: اس کے گھر اور اس کی سلطنت میں کچھ ایسا نہیں تھا جو حزقیاہ نے انہیں نہ دکھایا۔ قیمتی چیزیں:  یا، مصالحہ} {زرہ: یا، جواہرات: عبرانی۔ vessels}\n14۔ پھر یسعیاہ نبی بادشاہ حزقیاہ کے پاس آئے اور اس سے پوچھا، ان لوگوں نے کیا کہا؟ اور وہ کہاں سے تمہارے پاس آئے؟ اور حزقیاہ نے کہا، وہ ایک دور دراز ملک سے آئے ہیں، {حتیٰ کہ} بابل سے۔\n15۔ اور اس نے کہا، انہوں نے تمہارے گھر میں کیا دیکھا ہے؟ اور حزقیاہ نے جواب دیا، \"میرے گھر میں جو کچھ بھی ہے، انہوں نے دیکھا ہے: میرے خزانے میں سے کوئی چیز ایسی نہیں جو میں نے نہ دکھائی ہو۔\n16۔ اور یسعیاہ نے حزقیاہ سے کہا، خداوند کا کلام سنو۔\n17۔ دیکھو، دن آتے ہیں کہ تمہارے گھر میں جو کچھ ہے، اور جو تمہارے آباؤ اجداد نے آج تک رکھا ہے، وہ بابل میں لے جائے گا: کچھ باقی نہیں رہے گا، خداوند فرماتا ہے۔\n18۔ اور تمہارے بیٹوں میں سے جو تم سے پیدا ہوں گے، جنہیں تم پیدا کرو گے، وہ لے جائیں گے؛ اور وہ بابل کے بادشاہ کے محل میں خواجہ سرا ہوں گے۔\n19۔ پھر حزقیاہ نے یسعیاہ سے کہا، نیکی وہ کلام ہے جو تم نے کہا ہے۔ اور اس نے کہا، {کیا یہ اچھا نہیں ہے}، اگر میرے دنوں میں امن اور سچائی ہو؟ {کیا یہ...: یا، کیا امن اور سچائی نہیں ہوگی، وغیرہ}\n20۔ اور حزقیاہ کے باقی اعمال، اس کی تمام طاقت، اور کیسے اس نے ایک تالاب اور راستہ بنایا اور شہر میں پانی لایا، کیا وہ یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n21۔ اور حزقیاہ نے اپنے باپ و اجداد کے ساتھ سونا شروع کیا: اور مناسی اس کا بیٹا اس کی جگہ حکومت کرنے لگا۔","1. مناسی بارہ سال کا تھا جب اس نے حکومت شروع کی، اور یروشلم میں پچپن سال حکومت کی۔ اور اس کی والدہ کا نام {تھا} ہیفزیبا تھا۔\n2۔ اور اس نے خداوند کی نظر میں وہ برا کیا جو کافروں کی گناہوں کے بعد کیا، جنہیں خداوند نے بنی اسرائیل کے سامنے نکال دیا۔\n3۔ کیونکہ اس نے وہ بلند مقامات دوبارہ تعمیر کیے جو حزقیاہ نے اپنے والد نے تباہ کیے تھے؛ اور اس نے بعل کے لیے قربان گاہیں کھڑی کیں، اور ایک جھنڈ بنایا، جیسا کہ اسرائیل کے بادشاہ اہاب نے کیا؛ اور آسمان کے تمام لشکر کی عبادت کی، اور ان کی خدمت کی۔\n4۔ اور اس نے خداوند کے گھر میں قربان گاہیں بنائیں، جن کے بارے میں خداوند نے فرمایا، یروشلم میں اپنا نام رکھوں گا۔\n5۔ اور اس نے خداوند کے گھر کے دونوں صحنوں میں آسمان کے تمام لشکر کے لیے قربان گاہیں بنائیں۔\n6۔ اور اس نے اپنے بیٹے کو آگ میں سے گزارا، وقت دیکھا، جادو کیا، اور مانوس روحوں اور جادوگروں سے نمٹا: اس نے خداوند کے سامنے بہت برا کیا، تاکہ {اسے} کو غصہ دلائے۔\n7۔ اور اس نے اس جنگل کی ایک تراشی ہوئی تصویر رکھی جو اس نے گھر میں بنائی تھی، جس کے بارے میں خداوند نے داؤد اور اس کے بیٹے سلیمان سے کہا، اس گھر میں، اور یروشلم میں، جسے میں نے اسرائیل کی تمام قبائل میں سے چنا ہے، میں ہمیشہ کے لیے اپنا نام رکھوں گا:\n8۔ نہ ہی میں اسرائیل کے قدموں کو اس زمین سے باہر نکالوں گا جو میں نے ان کے باپ اجداد کو دی تھی؛ صرف اگر وہ ان سب چیزوں کے مطابق عمل کریں جو میں نے انہیں حکم دیا ہے، اور وہ تمام قانون جو میرے خادم موسیٰ نے انہیں حکم دیا ہے۔\n9۔ لیکن انہوں نے نہیں سنا: اور منسی نے انہیں ان قوموں سے زیادہ برا کرنے پر آمادہ کیا جنہیں خداوند نے بنی اسرائیل کے سامنے تباہ کیا۔\n10۔ اور خداوند نے اپنے بندوں کے ذریعے نبیوں سے کہا،\n11۔ کیونکہ یہوداہ کے بادشاہ مناسی نے یہ گناہوں کا کام کیا، {اور} نے وہ سب سے زیادہ برے کام کیے جو اموریوں نے کیے جو اس سے پہلے تھے، اور یہوداہ کو بھی اپنے بتوں کے ساتھ گناہ کرنے پر مجبور کیا:\n12۔ لہٰذا اسرائیل کے خداوند خدا نے یوں فرمایا، دیکھو، میں یروشلم اور یہوداہ پر ایسی برائی لا رہا ہوں کہ جو بھی اس کی بات سنے گا، اس کے دونوں کان سنسناہٹ محسوس کریں گے۔\n13۔ اور میں یروشلم پر سامریہ کی نسل اور اخاب کے گھرانے کے زوال کو پھیلاؤں گا: اور میں یروشلم کو ایسے صاف کروں گا جیسے {آدمی} برتن صاف کرے گا، اسے صاف کرے گا اور الٹ پلٹ کرے گا۔ {صاف کرنا...: عببرانی۔ وہ اسے مٹاتا ہے اور اس کے چہرے پر پلٹ دیتا ہے}\n14۔ اور میں اپنی باقی ماندہ وراثت کو چھوڑ دوں گا، اور انہیں ان کے دشمنوں کے حوالے کر دوں گا؛ اور وہ اپنے تمام دشمنوں کے لیے شکار اور مال کا شکار بن جائیں گے؛\n15۔ کیونکہ انہوں نے میرے سامنے جو برا کیا اور مجھے غصہ دلایا ہے، اس دن سے جب ان کے باپ مصر سے نکلے، آج تک۔\n16۔ مزید برآں، منسی نے معصوموں کا خون بہت بہایا، یہاں تک کہ اس نے یروشلم کو ایک سرے سے دوسرے سرے تک بھر دیا؛ اس کے گناہ کے علاوہ جس سے اس نے یہوداہ کو گناہ کیا، جو خداوند کی نظر میں برا تھا۔ {سے...: عبرانی منہ سے منہ تک}\n17۔ اب منسی کے باقی اعمال، جو کچھ اس نے کیا، اور اس کا گناہ جو اس نے کیا، کیا وہ یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n18۔ اور منسی اپنے باپ اجداد کے ساتھ سویا اور اپنے گھر کے باغ میں، عزا کے باغ میں دفن کیا گیا: اور اس کا بیٹا آمون اس کی جگہ بادشاہی کرنے لگا۔\nانیس۔ آمن {تھا} جب اس نے حکومت شروع کی تو اس کی عمر بائیس سال تھی، اور اس نے یروشلم میں دو سال حکومت کی۔ اور اس کی والدہ کا نام مشولیمت تھا، جو یوتبہ کے ہاروز کی بیٹی تھی۔\n20۔ اور اس نے وہ کیا جو خداوند کی نظر میں برا تھا، جیسا کہ اس کے باپ منسی نے کیا۔\n21۔ اور وہ اپنے والد کے پورے راستے سے گزرا، اور ان بتوں کی خدمت کی جن کی اس کے والد عبادت کرتے تھے، اور ان کی عبادت کی:\n22۔ اور اس نے اپنے باپ اجداد کے خداوند خدا کو چھوڑ دیا، اور خداوند کے راستے میں نہیں چلا۔\n23۔ اور آمون کے خادموں نے اس کے خلاف سازش کی اور بادشاہ کو اس کے اپنے گھر میں قتل کر دیا۔\n24۔ اور اس ملک کے لوگوں نے ان سب کو مار ڈالا جنہوں نے بادشاہ آمون کے خلاف سازش کی تھی؛ اور اس ملک کے لوگوں نے یوشیا کو اس کی جگہ اپنا بیٹا بادشاہ بنایا۔\n25۔ اب آمون کے باقی اعمال جو اس نے کیے، کیا وہ یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n26۔ اور اسے اپنے قبر میں عزا کے باغ میں دفن کیا گیا: اور اس کا بیٹا یوشیا اس کی جگہ بادشاہی کرنے لگا۔ {جوسیاہ: گریڈ جوسیاس}","1. یوشیا آٹھ سال کا تھا جب اس نے حکومت شروع کی، اور اس نے یروشلم میں اکتیس سال حکومت کی۔ اور اس کی والدہ کا نام جدیدہ تھا، جو بوسکاتھ کے عدایہ کی بیٹی تھی۔\n2۔ اور اس نے خداوند کی نظر میں جو کچھ تھا وہ کیا، اور اپنے باپ داؤد کے راستے میں چلتا رہا، نہ دائیں ہاتھ کی طرف مڑا نہ بائیں طرف۔\n3۔ اور بادشاہ یوشیا کے اٹھارہویں سال میں ایسا ہوا کہ بادشاہ نے شافان کے بیٹے عزالیا، میشولم کا بیٹا، کاتب کو خداوند کے گھر بھیجا، اور کہا،\n4۔ ہلکیاہ کے پاس جاؤ، جو اعلیٰ کاہن ہے، تاکہ وہ وہ چاندی جمع کرے جو خداوند کے گھر میں لائی گئی ہے، جو دروازے کے محافظوں نے لوگوں سے جمع کی ہے: {دروازہ: عبرانی۔ تھریش ہولڈ}\n5۔ اور وہ اسے کام کرنے والوں کے ہاتھ میں دے دیں جو خداوند کے گھر کی نگرانی کرتے ہیں: اور وہ یہ کام کرنے والوں کو دے دیں جو خداوند کے گھر میں ہے، تاکہ گھر کی دراڑیں درست کی جا سکیں۔\n6۔ بڑھئیوں، معماروں، اور معماروں کو، اور گھر کی مرمت کے لیے لکڑی اور پتھر خریدنے کے لیے۔\n7۔ تاہم ان کے ہاتھ میں دی گئی رقم کا کوئی حساب نہیں لگایا گیا، کیونکہ وہ وفاداری سے سودا کرتے تھے۔\n8۔ اور حلقیہ اعلیٰ کاهن نے شافان کاتب سے کہا، میں نے شریعت کی کتاب خداوند کے گھر میں پائی ہے۔ اور ہلکیاہ نے وہ کتاب شافان کو دی، اور اس نے اسے پڑھا۔\n9۔ اور شافان کاتب بادشاہ کے پاس آیا، اور بادشاہ کو دوبارہ پیغام دیا، اور کہا، \"تمہارے خادموں نے گھر میں پایا ہوا پیسہ جمع کر لیا ہے، اور اسے ان کے ہاتھ میں دے دیا ہے جو کام کرتے ہیں، جو خداوند کے گھر کی نگرانی کرتے ہیں۔ {جمع شدہ: عبوری۔ پگھلا ہوا}\n10۔ اور شفان کاتب نے بادشاہ کو دکھایا، کہا، حلقیاہ کاهن نے مجھے ایک کتاب دی ہے۔ اور شافان نے اسے بادشاہ کے سامنے پڑھا۔\n11۔ اور ایسا ہوا جب بادشاہ نے قانون کی کتاب کے الفاظ سنے، کہ اس نے اپنے کپڑے کرایہ پر لے لیے۔\n12۔ اور بادشاہ نے حلقیاہ کو کاہن، احیکم شافان کا بیٹا، اور اخبور میخیا کا بیٹا، اور شفان کاتب اور عساحیاہ کو بادشاہ کا خادم حکم دیا، اور کہا، {اخبور: یا، عدون} {میخایا: یا، میکاہ}\n13۔ جاؤ، خداوند سے میرے لیے، اور لوگوں کے لیے، اور تمام یہوداہ کے لیے، اس کتاب کے الفاظ کے بارے میں پوچھو: کیونکہ خداوند کا غضب جو ہمارے خلاف بھڑکا گیا ہے، بہت بڑا ہے، کیونکہ ہمارے آباؤ اجداد نے اس کتاب کے الفاظ نہیں سنے، اور ہمارے بارے میں لکھی گئی تمام باتوں کے مطابق عمل کرو۔\n14۔ تو حلقیاہ کاہن، اور احیکم، اور اخبور، اور شافان، اور اساحیاہ، ہلدہ نبی کے پاس گئے، جو شلوم، ٹکواہ کے بیٹے کی بیوی تھی، جو ہارہاس کا بیٹا تھا، اور لباس کا محافظ تھا؛ (اب وہ یروشلم میں کالج میں رہتی تھیں؛) اور وہ اس سے بات چیت کرتے تھے۔ {وارڈروب: عبوری۔ گارمنٹس} {میں...: یا، دوسرے حصے میں}\n15۔ اور اس نے ان سے کہا، یوں اسرائیل کے خداوند خدا نے فرمایا، اس آدمی کو بتاؤ جس نے تمہیں میرے پاس بھیجا،\n16۔ خداوند یوں فرماتا ہے، دیکھو، میں اس جگہ اور اس کے باشندوں پر برائی لاؤں گا، {حتیٰ کہ} اس کتاب کے تمام الفاظ جو یہوداہ کے بادشاہ نے پڑھے ہیں:\n17۔ کیونکہ انہوں نے مجھے چھوڑ دیا ہے، اور دوسرے دیوتاؤں کے لیے لوبان جلا دیا ہے، تاکہ وہ اپنے تمام کاموں سے مجھے غصہ دلا سکیں؛ لہٰذا میرا غصہ اس جگہ پر بھڑکائے گا، اور بجھا نہیں جائے گا۔\n18۔ لیکن یہوداہ کے بادشاہ سے جس نے تمہیں خداوند سے پوچھنے بھیجا ہے، تو تم اس سے یوں کہو گے، یہی فرماتا ہے اسرائیل کے خداوند خدا، {جیسا کہ چھوئے} وہ الفاظ جو تم نے سنے؛\n19۔ کیونکہ تمہارا دل نرم تھا، اور تم نے خداوند کے سامنے خود کو عاجز کر دیا، جب تم نے سنا کہ میں نے اس جگہ اور اس کے باشندوں کے خلاف کیا کہا، تاکہ وہ ویران اور لعنت بن جائیں، اور تمہارے کپڑے پھاڑ دیے اور میرے سامنے رو دیا؛ میں نے بھی سنا ہے {تم}، خداوند فرماتا ہے۔\n20۔ دیکھو، میں تمہیں تمہارے باپ دادا کے پاس لے آؤں گا، اور تمہیں سکون سے قبر میں جمع کیا جائے گا؛ اور تمہاری آنکھیں وہ تمام برائی نہیں دیکھیں گی جو میں اس جگہ پر لاؤں گا۔ اور انہوں نے دوبارہ بادشاہ کا حکم دیا۔","1۔ اور بادشاہ نے بھیجا، اور انہوں نے یہوداہ اور یروشلم کے تمام بزرگوں کو اس کے پاس جمع کیا۔\n2۔ اور بادشاہ خداوند کے گھر میں چلا گیا، اور یہوداہ کے تمام لوگ اور یروشلم کے تمام باشندے، کاہن، نبی اور تمام لوگ، چھوٹے اور بڑے دونوں، اور ان کے کانوں میں عہد کی کتاب کے تمام الفاظ پڑھے جو خداوند کے گھر میں پایا گیا تھا۔ {دونوں...: عبرانی۔ چھوٹے سے بڑے تک}\n3۔ اور بادشاہ ایک ستون کے پاس کھڑا ہوا، اور خداوند کے سامنے عہد کیا کہ خداوند کے پیچھے چلے گا، اور اپنے احکامات، گواہیوں اور قوانین کو پورے دل اور پوری جان سے نبھائے، تاکہ اس عہد کے الفاظ کو پورا کریں جو اس کتاب میں لکھے گئے ہیں۔ اور تمام لوگ اس عہد کے خلاف کھڑے ہو گئے۔\n4۔ اور بادشاہ نے حلقیاہ اعلیٰ کاہن، دوسرے درجے کے کاہنوں اور دروازے کے محافظوں کو حکم دیا کہ خداوند کے مندر سے وہ تمام برتن نکالیں جو بعل، جنگل کے لیے اور آسمان کی تمام لشکریوں کے لیے بنے تھے، اور اس نے انہیں یروشلم کے بغیر قدرون کے کھیتوں میں جلا دیا،  اور ان کی راکھ کو بیت ھل لے گیا۔\n5۔ اور اس نے بت پرست کاہنوں کو گرا دیا، جنہیں یہوداہ کے بادشاہوں نے یہوداہ کے شہروں اور یروشلم کے آس پاس کے مقامات پر لوبان جلانے کا حکم دیا تھا؛ وہ بھی جو بعل، سورج، چاند، سیاروں، اور آسمان کے تمام لشکر کے لیے دھوئیں جلاتے تھے۔ {put...: عبدی۔ ختم ہو گیا} {بت پرست...: عبرانی۔ کیماریم} {سیارے: یا، بارہ نشانیاں یا، برجے}\n6۔ اور اس نے خداوند کے گھر سے، یروشلم کے بغیر، کدرون کے نالے تک جنگل نکالا، اسے کیدرون ندی پر جلا دیا، اور اسے چھوٹا سا پاؤڈر بنا دیا، اور اس کا بارود لوگوں کے بچوں کی قبروں پر ڈال دیا۔\n7۔ اور اس نے ہم جنس پرستوں کے گھروں کو توڑ دیا، جو خداوند کے گھر کے پاس تھے، جہاں عورتیں جنگل کے لیے پھانسی بناتی تھیں۔ {پھانسی دینا: عبوری۔ ہاؤسز}\n8۔ اور اس نے یہوداہ کے شہروں سے تمام کاہنوں کو نکالا، اور ان اونچائی جگہوں کو ناپاک کیا جہاں کاہنوں نے لوبان جلایا تھا، جبا سے بئر شبع تک، اور ان دروازوں کی اونچی جگہیں توڑ دیں جو یشوع کے دروازے کے داخلے میں تھے، جو شہر کے دروازے پر ایک آدمی کے بائیں ہاتھ پر تھے۔\n9۔ تاہم اعلیٰ مقامات کے پادری یروشلم میں خداوند کے مذبح تک نہیں پہنچے، بلکہ اپنے بھائیوں کے درمیان خمیر کے بغیر روٹی سے کھاتے تھے۔\n10۔ اور اس نے توفیت کو ناپاک کیا، جو ہنوم کے بچوں کی وادی میں ہے، تاکہ کوئی آدمی اپنے بیٹے یا بیٹی کو آگ کے ذریعے مولخ جانے پر مجبور نہ کرے۔\n11۔ اور اس نے وہ گھوڑے لے گئے جو یہوداہ کے بادشاہوں نے سورج کو دیے تھے، خداوند کے گھر کے داخلے پر، ناتھن میلک کے کمرے سے، جو مضافات میں تھا، اور سورج کی رتھوں کو آگ سے جلا دیا۔ {چیمبرلین: یا، خواجہ سرا، یا، افسر}\n12۔ اور وہ قربان گاہیں جو آحاز کے اوپری کمرے کی چوٹی پر تھیں، جو یہوداہ کے بادشاہوں نے بنائی تھیں، اور وہ قربان گاہیں جو منسی نے خداوند کے گھر کے دونوں صحنوں میں بنائی تھیں، جنہیں بادشاہ نے توڑ کر توڑ دیا، اور ان کی خاک کو کیدرون ندی میں پھینک دیا۔ {بریک...: یا، وہاں سے دوڑا}\n13۔ اور وہ اونچی جگہیں جو یروشلم سے پہلے تھیں، جو فساد کے پہاڑ کے دائیں ہاتھ پر تھیں، جو سلیمان نے اسرائیل کے بادشاہ نے اشتوریت کے لیے زیدونیوں کی مکروہ چیز بنائی تھی، اور کیموش کے لیے موآبیوں کی مکروہ بدکاری، اور ملکم کے لیے عمون کے بچوں کی مکروہ کاری، بادشاہ نے ناپاک کی۔ {پہاڑ...: یعنی زیتون کا پہاڑ}\n14۔ اور اس نے مجسمے ٹکڑے ٹکڑے کر دیے، جھنڈ کاٹ دیے، اور ان کی جگہ انسانوں کی ہڈیوں سے بھر دی۔ {تصاویر: عبرانی۔ مجسمے}\n15۔ مزید یہ کہ وہ قربان گاہ جو بیت ایل میں {تھا}، {اور} وہ اونچی جگہ جو یربعام نیبت کے بیٹے نے، جس نے اسرائیل کو گناہ پر مجبور کیا، اس نے وہ قربان گاہ اور اونچی جگہ دونوں بنائی، اونچی جگہ کو جلا دیا، {اور} اسے چھوٹا سا پاؤڈر بنا دیا، اور جھنڈ کو جلا دیا۔\n16۔ اور جب یوشع نے خود کو مڑا، تو اس نے وہ قبریں دیکھیں جو پہاڑ میں تھیں، اور بھیجی، اور قبروں سے ہڈیاں نکالیں، اور انہیں قربان گاہ پر جلا دیا، اور اسے آلودہ کر دیا، خداوند کے کلام کے مطابق جو خدا کے آدمی نے اعلان کیا تھا، جس نے یہ الفاظ بیان کیے۔\n17۔ پھر اس نے کہا، یہ کون سا لقب ہے جو میں دیکھ رہا ہوں؟ اور شہر کے لوگوں نے اسے بتایا، {یہ} خدا کے آدمی کی قبر ہے، جو یہوداہ سے آئی ہے، اور انہوں نے یہ سب کچھ اعلان کیا جو تم نے بیت ال کے مذبح کے خلاف کیا ہے۔\n18۔ اور اس نے کہا، اسے چھوڑ دو؛ کوئی انسان اپنی ہڈیاں نہ ہلائے۔ لہٰذا انہوں نے اس کی ہڈیوں کو چھوڑ دیا، اس نبی کی ہڈیوں کے ساتھ جو سامریہ سے نکلا تھا۔ {صرف ہڈیاں: عبرانی۔ ہڈیوں سے بچنے کے لیے}\n19۔ اور وہ تمام گھر جو سامرے کے شہروں میں تھے، جنہیں اسرائیل کے بادشاہوں نے خداوند کو غصہ دلانے کے لیے بنایا تھا، یوشیا نے لے لیا اور ان کے ساتھ ان کے مطابق کیا جیسا کہ اس نے بیت ایل میں کیا تھا۔\n20۔ اور اس نے تمام اونچی جگہوں کے پادریوں کو قتل کر دیا جو وہاں قربان گاہوں پر تھے، اور ان پر لوگوں کی ہڈیاں جلا دیں، اور یروشلم واپس چلا گیا۔ {سلیو: یا، قربان کیا گیا}\n21۔ اور بادشاہ نے سب لوگوں کو حکم دیا، کہہ دیا، \"عید فسح کو خداوند تمہارے خدا کے پاس رکھو، جیسا کہ اس عہد نامے کی کتاب میں لکھا ہے۔\"\n22۔ یقینا ایسا عید فصح ان قاضیوں کے دنوں سے نہیں منایا گیا جو اسرائیل کا فیصلہ کرتے تھے، نہ ہی اسرائیل کے بادشاہوں کے تمام دنوں میں، نہ یہوداہ کے بادشاہوں کا؛\n23۔ لیکن بادشاہ یوسیاہ کے اٹھارہویں سال میں، {جس میں} یہ فسح یروشلم میں خداوند کے نام کیا گیا۔\n24۔ مزید برآں، وہ {مزدور} جن کے پاس جانی پہچانی روحیں، جادوگر، اور مجسمے، بتیں اور وہ تمام مکروہ مخلوقات تھیں جو یہوداہ کی سرزمین اور یروشلم میں دیکھی گئیں، یوشیا نے رکھ دی، تاکہ وہ وہ قانون کے الفاظ ادا کر سکے جو کتاب میں لکھے گئے تھے جو ہلکیا پادری نے خداوند کے گھر میں پایا۔ {تصاویر: یا، ترافیم}\n25۔ اور اس کے سامنے کوئی بادشاہ نہیں تھا جو پورے دل، جان اور پوری طاقت سے خداوند کی طرف رجوع کرے، جیسا کہ موسیٰ کے تمام قانون کے مطابق؛ اس کے بعد وہاں {کوئی بھی} اس جیسا نہیں تھا۔\n26۔ اگرچہ خداوند نے اپنے شدید غضب سے منہ نہ موڑا، جس سے اس کا غصہ یہوداہ کے خلاف بھڑکایا گیا، ان تمام اشتعال انگیزیوں کی وجہ سے جو منسی نے اسے بھڑکایا۔ {اشتعال انگیزی: عبرانی۔ غصہ}\n27۔ اور خداوند نے فرمایا، میں یہوداہ کو بھی اپنی نظر سے ہٹا دوں گا، جیسے میں نے اسرائیل کو ہٹا دیا ہے، اور اس شہر یروشلم کو چھوڑ دوں گا جسے میں نے چنا ہے، اور جس کے بارے میں میں نے کہا ہے، میرا نام وہاں ہوگا۔\n28۔ اب یوشیا کے باقی اعمال اور اس نے جو کچھ کیا، کیا وہ یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n29۔ اپنے زمانے میں مصر کے بادشاہ فرعونخوح نے آشور کے بادشاہ کے خلاف دریائے فرات کے کنارے حملہ کیا: اور بادشاہ یوشیا اس کے خلاف گیا؛ اور اس نے اسے میگیدو میں مار ڈالا، جب اس نے اسے دیکھا تھا۔\n30۔ اور اس کے خادموں نے اسے مگیدو کے مردہ رتھ میں اٹھایا، یروشلم لے جا کر اس کے اپنے مقبرے میں دفن کیا۔ اور اس ملک کے لوگوں نے یوسیاہ کے بیٹے یہواہاز کو لے کر اسے مسح کیا اور اپنے باپ کی جگہ بادشاہ بنایا۔\n31. یہوآہاز {تھا} جب اس نے حکومت شروع کی تو اس کی عمر بیس سال تھی؛ اور اس نے یروشلم میں تین ماہ حکومت کی۔ اور اس کی والدہ کا نام ہموتال تھا، جو یرمیاہ آف لبنہ کی بیٹی تھی۔ {یہوآہز: جسے شلم بھی کہا جاتا ہے}\n32۔ اور اس نے خداوند کی نظر میں جو کچھ برا تھا، اس کے تمام اعمال کے مطابق کیا جو اس کے آباؤ اجداد نے کیا تھا۔\n33۔ اور فرعونخوہ نے اسے ربلہ میں ہمت کی سرزمین میں گروہوں میں رکھا تاکہ وہ یروشلم میں حکومت نہ کرے؛ اور زمین کو سو ٹیلنٹ چاندی اور ایک ٹیلنٹ سونے کا خراج دیا۔ {وہ...: یا، کیونکہ وہ حکمرانی کرتا تھا} {ڈالو...: عببرانی۔ زمین پر جرمانہ عائد کرنا}\n34۔ اور فرعونخوح نے یوسیاہ کے بیٹے الیاقیم کو یوشیا کے کمرے میں بادشاہ بنایا، اور اس کا نام یہویاقیم رکھ دیا، اور یہوآہاز کو لے گیا: اور وہ مصر پہنچا اور وہیں فوت ہوا۔\n35۔ اور یہویاقیم نے چاندی اور سونا فرعون کو دے دیا؛ لیکن اس نے زمین پر ٹیکس لگایا تاکہ فرعون کے حکم کے مطابق رقم دے سکے: اس نے زمین کے لوگوں سے چاندی اور سونا وصول کیا، ہر ایک سے اس کے ٹیکس کے مطابق، تاکہ وہ فرعون نیکو کو دے دے۔\n36۔ یہویاکیم کی عمر پچیس سال تھی جب اس نے حکومت شروع کی؛ اور انہوں نے یروشلم میں گیارہ سال حکومت کی۔ اور اس کی ماں کا نام زبودہ تھا، جو روماہ کے پدعیہ کی بیٹی تھی۔\n37۔ اور اس نے خداوند کے سامنے جو کچھ برا تھا، اس کے تمام اعمال کے مطابق کیا جو اس کے آباؤ اجداد نے کیا تھا۔","1۔ اس کے زمانے میں بابل کا بادشاہ نبوکدنصر آیا، اور یہویاکیم تین سال اس کا خادم بنا: پھر اس نے اس کے خلاف بغاوت کی۔\n2۔ اور خداوند نے اس کے خلاف کلدیوں کے گروہ بھیجے، سریوں کے گروہ، موآبیوں کے گروہ اور آمون کے بچوں کے گروہ بھیجے اور انہیں یہوداہ کے خلاف بھیجا تاکہ اسے تباہ کر دیں، جیسا کہ خداوند کے کلام کے مطابق اس نے اپنے بندوں کے ذریعے نبیوں کے ذریعے کہا تھا۔ {بذریعہ: عبرانی ہاتھوں سے}\n3۔ یقینا خداوند کے حکم پر یہوداہ پر آیا، کہ وہ انہیں اس کی نظر سے دور کر دے، کیونکہ منسی کے گناہوں کے مطابق، جو کچھ اس نے کیا؛\n4۔ اور اس معصوم خون کے لیے بھی جو اس نے بہایا: کیونکہ اس نے یروشلم کو معصوم خون سے بھر دیا؛ جسے خداوند معاف نہیں کرے گا۔\n5. اب یہویاکیم کے باقی اعمال اور جو کچھ اس نے کیا، کیا وہ یہوداہ کے بادشاہوں کی تاریخ کی کتاب میں نہیں لکھے گئے؟\n6۔ یوں یہویاقیم اپنے باپ دادا کے ساتھ سو گیا: اور اس کا بیٹا یہویاکین اس کی جگہ حکومت کرنے لگا۔\n7۔ اور مصر کا بادشاہ اپنی سرزمین سے دوبارہ باہر نہیں آیا، کیونکہ بابل کے بادشاہ نے مصر کے دریا سے فرات تک سب کچھ لے لیا تھا جو مصر کے بادشاہ سے متعلق تھا۔\n8۔ یہویاکین جب اس نے حکومت شروع کی تو اس کی عمر اٹھارہ سال تھی، اور اس نے یروشلم میں تین ماہ حکومت کی۔ اور اس کی والدہ کا نام {تھا} نہوشتا، یروشلم کے الناتھن کی بیٹی۔ {یہویاخین: جسے جیکونیاہ اور کونیاہ بھی کہا جاتا ہے}\n9۔ اور اس نے خداوند کی نظر میں جو کچھ برا تھا، اس کے باپ کے تمام اعمال کے مطابق کیا تھا۔\n10۔ اسی وقت بابل کے بادشاہ نبوکدنصر کے خادم یروشلم کے خلاف آئے اور شہر کا محاصرہ کر لیا گیا۔ {تھا...: عبرانی۔ محاصرے میں آ گیا}\n11۔ اور بابل کے بادشاہ نبوکدنصر نے شہر پر حملہ کیا، اور اس کے خادموں نے اسے محاصرہ کر لیا۔\n12۔ اور یہویاکین یہوداہ کا بادشاہ بابل کے بادشاہ کے پاس گیا، وہ، اس کی ماں، اس کے خادم، اس کے شہزادے اور اس کے افسران، اور بابل کے بادشاہ نے اسے اپنی حکومت کے آٹھویں سال میں لے لیا۔ {افسران: یا، خواجہ سرا} {اس کی حکومت: نبوکدنضر کا آٹھواں سال}\n13۔ اور اس نے وہاں سے خداوند کے گھر کے تمام خزانے اور بادشاہ کے گھر کے خزانے نکالے اور وہ تمام سونے کے برتن ٹکڑوں میں کاٹ دیے جو سلیمان بادشاہ اسرائیل نے خداوند کے مندر میں بنائے تھے، جیسا کہ خداوند نے فرمایا۔\n14۔ اور اس نے تمام یروشلم، تمام شہزادے، اور تمام بہادر آدمیوں کو، {حتیٰ کہ} دس ہزار قیدی، اور تمام کاریگر اور لوہاروں کو اغوا کر لیا: کوئی باقی نہ رہا، سوائے ملک کے سب سے غریب لوگوں کے۔\n15۔ اور اس نے یہویاکین کو بابل لے جایا، اور بادشاہ کی ماں، بادشاہ کی بیویاں، اس کے افسران اور زمین کے طاقتور افراد کو، جو اسے یروشلم سے بابل قید میں لے گئے۔ {افسران: یا، خواجہ سرا}\n16۔ اور تمام طاقتور آدمی، {حتیٰ کہ} سات ہزار، اور کاریگر اور لوہار ہزار، جو {جو } مضبوط تھے {اور} جنگ کے لیے موزوں تھے، حتیٰ کہ وہ بھی بابل کے بادشاہ نے بابل میں قید کر لیا۔\n17۔ اور بابل کے بادشاہ نے متانیاہ کو اپنے والد کا بھائی بادشاہ بنایا، اور اس کا نام صدقیہ رکھ لیا۔\n18۔ صدقیاہ {تھا} جب اس نے حکومت شروع کی تو وہ بیس سال کا تھا، اور اس نے یروشلم میں گیارہ سال حکومت کی۔ اور اس کی والدہ کا نام ہموتال تھا، جو یرمیاہ آف لبنہ کی بیٹی تھی۔\n19۔ اور اس نے خداوند کی نظر میں جو کچھ بھی برا تھا، جیسا کہ یہویاقیم نے کیا تھا۔\n20۔ کیونکہ خداوند کے غصے سے یروشلم اور یہوداہ میں یہ ہوا، یہاں تک کہ اس نے انہیں اپنی موجودگی سے نکال دیا، کہ صدقیاہ نے بابل کے بادشاہ کے خلاف بغاوت کی۔","1۔ اور یہ اس کی حکومت کے نویں سال، دسویں مہینے میں، مہینے کے دسویں دن میں ہوا کہ بابل کا بادشاہ نبوکدنصر یروشلم کے خلاف آیا، وہ اور اس کی پوری فوج یروشلم پر حملہ آور ہوا؛ اور انہوں نے اس کے ارد گرد قلعے بنائے۔\n2۔ اور شہر بادشاہ صدقیاہ کے گیارہویں سال تک محاصرے میں رہا۔\n3۔ اور چوتھے مہینے کے نویں دن کو شہر میں قحط چھا گیا، اور زمین کے لوگوں کے لیے روٹی نہیں تھی۔\n4۔ اور شہر توڑ دیا گیا، اور تمام جنگجو رات کو دو دیواروں کے درمیان دروازے کے راستے سے بھاگ گئے، جو بادشاہ کے باغ کے پاس ہے: (اب کلدی شہر کے ارد گرد کے خلاف تھے:) اور بادشاہ میدان کی طرف بڑھا۔\n5۔ اور کلدیوں کی فوج بادشاہ کا پیچھا کرتی ہوئی یریحو کے میدانوں میں اسے پکڑ لیتی، اور اس کی ساری فوج اس سے بکھر جاتی۔\n6۔ تو انہوں نے بادشاہ کو لے کر بابل کے بادشاہ کے پاس ربلہ لے گئے؛ اور انہوں نے اس پر فیصلہ دیا۔ {دیا گیا...: عببرانی۔ اس سے فیصلہ کیا}\n7۔ اور انہوں نے زدیقیاہ کے بیٹوں کو اس کی آنکھوں کے سامنے قتل کر دیا، زدیقیاہ کی آنکھیں بجھا دیں، اسے پیتل کی زنجیروں سے باندھ کر بابل لے گئے۔ {put...: عبدی۔ اندھا کر دیا گیا}\n8۔ اور پانچویں مہینے میں، مہینے کے ساتویں دن، جو بابل کے بادشاہ نبوکدنضر کے انیسویں سال کا ہے، نبوزاردان، محافظ کا کپتان، بابل کے بادشاہ کا خادم، یروشلم آیا: {کپتان...: یا، چیف مارشل}\n9۔ اور اس نے خداوند کے گھر، بادشاہ کے گھر، اور یروشلم کے تمام گھروں کو جلا دیا، اور ہر بڑے {انسان} کے گھر کو آگ سے جلا دیا۔\n10۔ اور تمام کلدیوں کی فوج، جو محافظ کے کپتان کے ساتھ تھی، یروشلم کی دیواروں کو توڑ دیتی ہے۔\n11۔ اب باقی لوگ جو شہر میں رہ گئے تھے، اور وہ فراری جو بابل کے بادشاہ کے پاس چلے گئے، ہجوم کے باقیات کے ساتھ، نبوزارادان محافظوں کے کپتان کو لے گئے۔ {فراری: عبوری۔ گر گیا}\n12۔ لیکن گارڈ کا کپتان جو زمین کے غریبوں میں سے بچا تھا، انگور بنانے والے اور کسان بن گئے۔\n13۔ اور وہ پیتل کے ستون جو خداوند کے گھر میں تھے، اور اس کے نیچے اور وہ برسن سمندر جو خداوند کے گھر میں تھا، کلدیوں نے ٹکڑوں میں توڑ دیا اور ان کے پیتل کو بابل لے گئے۔\n14۔ اور برتن، بیلچے، سنیفرز، چمچ، اور تمام پیتل کے برتن جن سے وہ خدمت کرتے تھے، انہیں لے گئے۔\n15۔ اور آگ کے برتن، اور پیالے، {اور} وہ چیزیں جو {سونے کی} تھیں، {میں} سونے کی، اور چاندی کے، {میں} چاندی کے، جو گارڈ کے کپتان نے لے لیے۔\n16۔ دو ستون، ایک سمندر، اور وہ بنیادیں جو سلیمان نے خداوند کے گھر کے لیے بنائی تھیں؛ ان تمام جہازوں کا پیتل بے وزن تھا۔ {ایک...: عبرانی۔ ایک سمندر}\n17۔ ایک ستون کی اونچائی اٹھارہ کیوبٹ تھی، اور اس پر موجود چپیٹر پیتل کا تھا؛ اور چپٹر کی اونچائی تین کیوبٹ؛ اور پھولوں کا کام، اور چپیٹر کے ارد گرد انار کے ساتھ، سب پیتل کے بنے ہوئے تھے: اور ان کی طرح دوسرا ستون بھی ہاروں سے بنا ہوا تھا۔\n18۔ اور محافظوں کے کپتان نے سریاہ کو سردار کاہن، زفانیاہ کو دوسرا کاہن، اور دروازے کے تین محافظوں کو لے لیا: {دروازہ: عبرانی۔ تھریش ہولڈ}\n19۔ اور شہر سے اس نے ایک افسر کو لے کر لیا جو جنگی سپاہیوں پر تعینات تھا، اور پانچ مرد جو بادشاہ کے حضور میں تھے اور شہر میں پائے جاتے تھے، اور فوج کے مرکزی کاتب کو بھی لے گیا، جس نے زمین کے لوگوں کو جمع کیا، اور شہر میں پائے جانے والے زمین کے تین ساٹھ آدمی جمع کیے:  {افسر: یا، خواجہ سرا} {تھے...: عبرانی میں۔ بادشاہ کا چہرہ دیکھا} {پرنسپل...: یا، فوج کے کپتان کا کاتب}\n20۔ اور محافظ کے کپتان نبوزاردان نے یہ لے کر بابل کے بادشاہ کو ربلہ پہنچایا:\n21۔ اور بابل کے بادشاہ نے انہیں مارا اور ربلہ میں حمتھ کی سرزمین میں قتل کر دیا۔ یوں یہوداہ کو ان کی سرزمین سے نکال دیا گیا۔\n22۔ اور {جہاں تک} وہ لوگ جو یہوداہ کی سرزمین میں رہ گئے، جنہیں بابل کے بادشاہ نبوکدنصر نے چھوڑا تھا، ان پر بھی اس نے گڈالیا، احیکم کا بیٹا، شافان کا بیٹا، حکمران بنایا۔\n23۔ اور جب تمام فوجوں کے کپتانوں نے، وہ اور ان کے آدمی، سنا کہ بابل کے بادشاہ نے گدلیاہ کو گورنر بنایا ہے، تو گدلیاہ کے پاس مزپاہ آئے، یہاں تک کہ اسماعیل نیثانیاہ کا بیٹا، یوحنا کیراح کا بیٹا، اور سریاہ تنہومیت نیتوفاتی کا بیٹا، اور یعقوبیاہ ایک ماختی کا بیٹا،  وہ اور ان کے آدمی۔\n24۔ اور گدالیا نے ان سے اور ان کے آدمیوں سے قسم کھائی اور کہا، کلدیوں کے خادم بننے سے نہ ڈرو: زمین میں رہو اور بابل کے بادشاہ کی خدمت کرو؛ اور یہ تمہارے لیے اچھا ہوگا۔\n25۔ لیکن ساتویں مہینے میں، اسماعیل، نیتھانیا کا بیٹا، الیشامہ کا بیٹا، شاہی نسل سے آیا، اور اس کے ساتھ دس آدمی بھی آئے، اور گدلیاہ کو مارا کہ وہ مارا، اور یہودیوں اور کلدی جو اس کے ساتھ مزپا میں تھے۔ {شاہی: عبوری۔ سلطنت کی}\n26۔ اور تمام لوگ، چھوٹے اور بڑے دونوں، اور فوجوں کے کپتان، اٹھے اور مصر آئے، کیونکہ وہ کلدیوں سے ڈرتے تھے۔\n27۔ اور یہ واقعہ یہوداہ کے بادشاہ یہویاکین کی قید کے ساتویں اور تیسویں سال میں، بارہویں مہینے میں، مہینے کے ساتویں اور بیسویں دن ہوا، {کہ} بابل کے بادشاہ ایول میروداخ نے جس سال اس نے حکومت شروع کی، یہوویاچن بادشاہ یہوداہ کا سر قید سے اٹھایا؛\n28۔ اور اس نے اس سے مہربانی سے بات کی، اور اپنے تخت کو ان بادشاہوں کے تخت پر بٹھایا جو اس کے ساتھ بابل میں تھے؛ {مہربانی سے...: عبرانی۔ اس کے ساتھ اچھی باتیں}\n29۔ اور اپنی قید خانے کے کپڑے بدلے: اور اپنی زندگی کے تمام دنوں اس کے سامنے مسلسل روٹی کھاتا رہا۔\n30۔ اور اس کی وظیفہ بادشاہ کی طرف سے دی جانے والی مسلسل الاؤنس تھی، روزانہ کی شرح، اس کی زندگی کے تمام دنوں کے لیے۔"];
